  violet      = '#6c71c4',
  bg_red      = '#da0000',
  bg_green    = '#859000',
  bg_yellow   = '#b59900',
  diff_add    = '#003200',
  diff_change = '#323200',
  diff_delete = '#320000',
  diff_text   = '#404000',
  none        = "NONE"
}

-- @class Light Color Palette
M.light = {
  bg0         = '#fdf6e3',
  bg1         = '#eee8d5',
  bg2         = '#fdf6e3',
  fg0         = '#002b36',
  fg1         = '#839496',
