  blue        = '#268bd2',
  purple      = '#d33682',
  violet      = '#6c71c4',
  bg_red      = '#da0000',
  bg_green    = '#859000',
  bg_yellow   = '#b59900',
  diff_add    = '#caffca',
  diff_change = '#ffffca',
  diff_delete = '#ffcaca',
  diff_text   = '#e8e8b3',
  none        = "NONE"
}

function M.setup(opts)
  opts = opts or {}
  local config = require("NeoSolarized.config")

  local palette = M.dark
  if config.is_day() then
    palette = M.light
  end
  if type(palette) == "function" then
    palette = palette()
  end
  return palette
end

return M

end end

-- NeoSolarized/lua/NeoSolarized/config.lua
if not package.preload["NeoSolarized.config"] then package.preload["NeoSolarized.config"] = function(...)
local M = {}

local defaults = {
  style = "dark",         -- "dark" or "light"
  transparent = true,     -- Enable this to disable setting the background color
  terminal_colors = true, -- Configure the colors used when opening a `:terminal` in Neovim
  enable_italics = true,  -- Italics for different hightlight groups (eg. Statement, Condition, Comment, Include, etc.)
  styles = {
    -- Style to be applied to different syntax groups
    comments = { italic = true },
    keywords = { italic = true },
    functions = { bold = true },
    variables = {},
    string = { italic = true },
    underline = true,
    undercurl = true,
  },
  -- Add specific hightlight groups
  on_highlights = function(highlights, colors)
  end,
}

M.options = {}

function M.setup(options)
  M.options = vim.tbl_deep_extend("force", {}, defaults, options or {})
  if M.options.transparent and M.options.style == "light" then
    print(
      "NeoSolarized does not support transparent mode in Light theme. Switching Back to dark theme with transparent mode.")
    M.options.style = "dark"
    M.options.transparent = true
  end
end

function M.extend(options)
  M.options = vim.tbl_deep_extend("force", {}, M.options or defaults, options or {})
end

function M.is_day()
  return M.options.style == "light" and M.options.transparent == false or vim.o.background == "light"
end

M.setup()

return M

end end

-- NeoSolarized/lua/NeoSolarized/init.lua
if not package.preload["NeoSolarized"] then package.preload["NeoSolarized"] = function(...)
local util = require("NeoSolarized.util")
local theme = require("NeoSolarized.theme")
local config = require("NeoSolarized.config")

local M = {}

function M._load()
  util.load(theme.setup())
end

M.setup = config.setup

-- keep for backward compatibility
M.colorscheme = M.load

return M

end end

-- NeoSolarized/lua/NeoSolarized/theme.lua
if not package.preload["NeoSolarized.theme"] then package.preload["NeoSolarized.theme"] = function(...)
local colors = require("NeoSolarized.colors")

local M = {}
function M.setup()
  local config = require("NeoSolarized.config")
  local options = config.options
  local theme = {
    config = options, colors = colors.setup(),
  }

  local c = theme.colors

  theme.highlights = {
    ColorColumn                              = { bg = c.bg1 },                                  -- used for the columns set with 'colorcolumn'
    Comment                                  = { fg = c.fg2, style = options.styles.comments }, -- any comment
    Conceal                                  = { fg = c.bg1 },                                  -- placeholder characters substituted for concealed text (see 'conceallevel')
    CurSearch                                = { link = "IncSearch" },
    CurrentWord                              = { fg = c.bg0, bg = c.bg_green },
    Cursor                                   = { fg = c.bg1, bg = c.fg0 },                      -- character under the cursor
    CursorColumn                             = { link = "CursorLine" },                         -- Screen-column at the cursor, when 'cursorcolumn' is set.
