-- NeoSolarized/lua/NeoSolarized/treesitter.lua
if not package.preload["NeoSolarized.treesitter"] then package.preload["NeoSolarized.treesitter"] = function(...)
local M = {}

function M.new_style()
  ---@diagnostic disable-next-line: undefined-field
  return vim.treesitter.highlighter.hl_map == nil
end

function M.get(group)
  if group:sub(1, 1) ~= "@" or M.new_style() then
    return group
  end

  group = group:sub(2)

  local lang
  while group do
    if M.fallbacks[group] then
      return (lang or "") .. M.fallbacks[group]
    end
    group, lang = group:match("(.*)%.(.*)")
  end
end

