-- lua/pure/dashboard.lua
package.preload["pure.dashboard"] = function(...)
-- ~/.config/nvim/lua/Custom_dashboard.lua

local M = {}

-- What the dashboard hides, in two parts:
--
-- * Line numbers and the cursorline are set on the dashboard's own window,
--   like :setlocal (vim.wo[win][0]): they belong to the dashboard buffer in
--   that window and go with it, so a file opened there, or any other window,
--   keeps its own. (They used to be set globally, for every window, and put
--   back afterwards.)
-- * The statusline and the tabline are global, so they follow the current
--   tab: hidden while it shows the dashboard, back as soon as it does not (a
--   file opened over it, another tab entered). With other tabs open the
--   tabline stays, so they can still be seen. The check used to look at the
--   windows of every tab, and gave up after the first restore: a dashboard in
--   one tab kept the statusline hidden in the others.
M.state = {
  hidden = false,   -- the statusline / tabline are the dashboard's
  laststatus = nil, -- the values to put back
  showtabline = nil,
}

local function tabShowsDashboard()
  for _, win in ipairs(vim.api.nvim_tabpage_list_wins(0)) do
    if vim.bo[vim.api.nvim_win_get_buf(win)].filetype == 'dashboard' then return true end
  end
  return false
end

--- Hide the statusline and tabline if the current tab shows the dashboard,
--- or put them back if it no longer does.
function M.syncUI()
  if tabShowsDashboard() then
    if not M.state.hidden then
      M.state.laststatus, M.state.showtabline = vim.o.laststatus, vim.o.showtabline
      M.state.hidden = true
    end
    vim.o.laststatus = 0
    vim.o.showtabline = #vim.api.nvim_list_tabpages() > 1 and M.state.showtabline or 0
  elseif M.state.hidden then
    vim.o.laststatus, vim.o.showtabline = M.state.laststatus, M.state.showtabline
    M.state.hidden = false
  end
end

vim.api.nvim_create_autocmd({ 'BufEnter', 'WinEnter', 'TabEnter' }, {
  group = vim.api.nvim_create_augroup('PureDashboardUI', { clear = true }),
  callback = function() M.syncUI() end,
})

--- Whether `buf` is the blank buffer Neovim starts with, or :tabnew opens:
--- no name, a normal buffer, unchanged and empty.
local function isBlank(buf)
  return vim.api.nvim_buf_get_name(buf) == '' and vim.bo[buf].buftype == ''
    and not vim.bo[buf].modified and vim.api.nvim_buf_line_count(buf) == 1
    and vim.api.nvim_buf_get_lines(buf, 0, 1, false)[1] == ''
end

--- The art without its surrounding blank space: trailing blank lines dropped
--- and the indentation shared by every line removed, so it can be centred.
local function trimArt(lines)
  local out = vim.deepcopy(lines)
  while #out > 0 and out[#out]:match('^%s*$') do table.remove(out) end
  local indent = math.huge
  for _, l in ipairs(out) do
    if l:match('%S') then indent = math.min(indent, #l:match('^%s*')) end
  end
  if indent == math.huge then indent = 0 end
  for i, l in ipairs(out) do out[i] = l:sub(indent + 1):gsub('%s+$', '') end
  return out
end

--- Scale the art by `k`: each character repeated k times, each line k times,
--- which keeps its proportions (a cell is about twice as tall as wide either
--- way). Menu lines ("[n] New File ...") are text, so they are left as is.
local function scaleArt(lines, k)
  if k <= 1 then return lines end
  local out = {}
  for _, l in ipairs(lines) do
    if l:match('%[%a%]') then
      table.insert(out, l)
    else
      local wide = table.concat(vim.tbl_map(function(c) return c:rep(k) end, vim.fn.split(l, [[\zs]])))
      for _ = 1, k do table.insert(out, wide) end
    end
  end
  return out
end

--- Fill the window with the art centred in it, at the largest scale that fits
--- (vim.g.pure_dashboard_scale: 'auto', the default, or a fixed number).
--- It used to be written as is, at the top left: in a big or full-screen
--- window the planet sat in one corner.
local function render(buf, win)
  if not (vim.api.nvim_buf_is_valid(buf) and vim.api.nvim_win_is_valid(win)) then return end
  local art = trimArt(require('pure.ascii').saturn)
  local width, height = vim.api.nvim_win_get_width(win), vim.api.nvim_win_get_height(win)

  local art_w = 0
  for _, l in ipairs(art) do art_w = math.max(art_w, vim.fn.strdisplaywidth(l)) end
  local setting = vim.g.pure_dashboard_scale or 'auto'
  local k = tonumber(setting) or 1
  if setting == 'auto' then
    k = math.max(1, math.min(math.floor(width / math.max(art_w, 1)), math.floor(height / math.max(#art, 1))))
  end
  local lines = scaleArt(art, k)

  -- One left margin for the whole drawing, so it keeps its shape; the menu
  -- line is centred on its own.
  local block_w = 0
  for _, l in ipairs(lines) do
    if not l:match('%[%a%]') then block_w = math.max(block_w, vim.fn.strdisplaywidth(l)) end
  end
  local left = string.rep(' ', math.max(0, math.floor((width - block_w) / 2)))
  local out, menu_row = {}, 1
  for _ = 1, math.max(0, math.floor((height - #lines) / 2)) do table.insert(out, '') end
  for _, l in ipairs(lines) do
    if l:match('%[%a%]') then
      -- Centred without the spaces the art puts before it: counted, they
      -- pushed the menu a few columns right of the middle (Improvment.md).
      l = vim.trim(l)
      local pad = math.max(0, math.floor((width - vim.fn.strdisplaywidth(l)) / 2))
      table.insert(out, string.rep(' ', pad) .. l)
      menu_row = #out
    else
      table.insert(out, l ~= '' and (left .. l) or '')
    end
  end

  -- Blank lines down to the bottom of the window. Past a buffer's last line
  -- Neovim draws '~', which showed under the drawing whenever it did not fill
  -- the window; the blank lines at the end of the art itself cannot do it,
  -- trimArt() drops them to centre it. Recomputed on every resize.
  while #out < height do table.insert(out, '') end

  vim.bo[buf].modifiable = true
  vim.api.nvim_buf_set_lines(buf, 0, -1, false, out)
  vim.bo[buf].modifiable = false
  -- Rest the cursor on the menu line, out of the drawing.
  pcall(vim.api.nvim_win_set_cursor, win, { menu_row, 0 })
end

--- l on the dashboard: back to the last note of the vault that was open
--- (Improvment.md), at the line where it was left: the newest entry of
--- v:oldfiles that is a markdown file inside the vault. With no such note
--- (or no vault), the last file Neovim was closed on, Vim's '0 mark.
function M.lastNote()
  local ok, zet = pcall(require, 'pure.zettelkasten')
  local vault = ok and zet.vaultPath() or nil
  local key = function(p)
    p = vim.fs.normalize(p)
    return vim.fn.has('win32') == 1 and p:lower() or p
  end
  if vault then
    local root = key(vault) .. '/'
    for _, f in ipairs(vim.v.oldfiles) do
      local path = vim.fs.normalize(f)
      if f:match('%.md$') and key(path):sub(1, #root) == root and vim.fn.filereadable(path) == 1 then
        vim.cmd('edit ' .. vim.fn.fnameescape(path))
        -- Where it was left ('"), as reopening a file with :e does not do.
        pcall(vim.cmd, 'normal! g`"')
        return
      end
    end
  end
  if not pcall(vim.cmd, "normal! '0") then vim.notify('No recent note or file') end
end

--- Show the dashboard in the current window.
function M.drawDashboard()
  local previous = vim.api.nvim_get_current_buf()
  local buf = vim.api.nvim_create_buf(false, true)

  -- Set buffer options
  vim.bo[buf].filetype = 'dashboard'
  vim.bo[buf].bufhidden = 'wipe'
  vim.bo[buf].buftype = 'nofile'
  vim.bo[buf].swapfile = false

  vim.api.nvim_win_set_buf(0, buf)
  local win = vim.api.nvim_get_current_win()
  vim.wo[win][0].number = false
  vim.wo[win][0].relativenumber = false
  vim.wo[win][0].cursorline = false
  M.syncUI()
  render(buf, win)

  -- The blank buffer it covers (Neovim's first one, or the one :tabnew made)
  -- would stay behind in the buffer list, unnamed and unused.
  if previous ~= buf and isBlank(previous) and #vim.fn.win_findbuf(previous) == 0 then
    pcall(vim.api.nvim_buf_delete, previous, {})
  end

  -- Redraw centred (and rescaled) whenever the window changes size: going
  -- full screen, a split, a font change.
  vim.api.nvim_create_autocmd({ 'VimResized', 'WinResized' }, {
    callback = function()
      if not vim.api.nvim_buf_is_valid(buf) then return true end -- drop the autocmd
      local win = vim.fn.bufwinid(buf)
      if win ~= -1 then render(buf, win) end
    end,
  })

  -- Set your keymaps for the dashboard buffer
  local opts = { buffer = buf, silent = true, nowait = true }
  vim.keymap.set('n', 'd', function() require('pure.zettelkasten').openDaily() end, opts)
  vim.keymap.set('n', 'l', M.lastNote, opts)
  vim.keymap.set('n', 'n', ':enew<CR>', opts)
  -- A note in the vault's inbox, asking only its name (like <leader>vn).
  vim.keymap.set('n', 'v', function() require('pure.zettelkasten').newNote() end, opts)
  -- In a tab of its own, q closes that tab; from the last one it quits.
  vim.keymap.set('n', 'q', function()
    vim.cmd(#vim.api.nvim_list_tabpages() > 1 and 'tabclose' or 'qa')
  end, opts)
  -- The configuration's own repository first, then the plugins (pure/update.lua).
  vim.keymap.set('n', 'u', function() require('pure.update').run() end, opts)
end

--- Show the dashboard in `tab` if it is still what :tabnew leaves: one
--- window on a blank buffer. Called once the command that opened the tab is
--- done, so a tab opened on a file, or filled in right away by whatever
--- opened it, is left alone.
function M.drawInBlankTab(tab)
  if not vim.api.nvim_tabpage_is_valid(tab) or tab ~= vim.api.nvim_get_current_tabpage() then return end
  local win = vim.api.nvim_get_current_win()
  for _, other in ipairs(vim.api.nvim_tabpage_list_wins(tab)) do
    -- Floating windows (a notification) do not count.
    if other ~= win and vim.api.nvim_win_get_config(other).relative == '' then return end
  end
  if isBlank(vim.api.nvim_win_get_buf(win)) then M.drawDashboard() end
end

return M

end

-- lua/pure/folding.lua
package.preload["pure.folding"] = function(...)
local M = {}
local fold_group = vim.api.nvim_create_augroup("PureFoldingAuto", { clear = true })

-- -----------------------------------------------------------------------------
--- A markdown line as it reads: links as their text, [[a|b]] as b, the
--- checkbox as an icon. A synced Todoist task shows only the task itself,
--- without the link to it and the date / priority / project after it.
local function plainMarkdown(line)
    local box, rest = line:match("^[-*] %[(.)%] (.*)$")
    local icon = box and (box == " " and "󰄱 " or "󰄲 ") or ""
    -- A task with a [[link]] is written as its text and then [↗](url).
    local linked = rest and rest:match("^(.-)%s*%[↗%]%(https://app%.todoist%.com/app/task/")
    if linked and linked:find("[[", 1, true) then
        rest = linked
    else
        -- The task's own text may hold escaped brackets: \[1\].
        local task = rest and rest:match("^%[(.-)%]%(https://app%.todoist%.com/app/task/")
        if task then
            return icon .. task:gsub("\\([%[%]])", "%1")
        end
    end
    line = (box and (icon .. rest) or line)
        :gsub("%[%[([^%]|]-)|([^%]]-)%]%]", "%2")  -- [[target|alias]]
        :gsub("%[%[([^%]]-)%]%]", "%1")            -- [[note]]
        :gsub("%[([^%]]*)%]%b()", "%1")            -- [text](url)
    return line
end

-- -----------------------------------------------------------------------------
--  Folding tasks by state (<leader>zt / <leader>zT, asked for in the vault's
--  Improvment.md): the done tasks folded away to see what is left, or the
--  open ones to see what was done. A task's sub-items and indented lines go
--  with it; headings and other text stay. <leader>zr (M.auto) goes back.
--
--  vim.g.pure_tasks_done: the checkbox states that count as done, default
--  "xX-" (done, cancelled), as the vault's legend has them; every other
--  state ([ ], [~], [!], [>]...) is open.
-- -----------------------------------------------------------------------------

--- The state of the task on `line` (the character in its box), or nil.
local function taskState(line)
    return line:match("^%s*[-*+] %[(.)%]") or line:match("^%s*%d+[.)] %[(.)%]")
end

local function isDone(state)
    return (vim.g.pure_tasks_done or "xX-"):find(state, 1, true) ~= nil
end

--- Per line of `buf`: whether it belongs to a task that is folded away in
--- `mode` ('done' hides done tasks, 'open' hides open ones). Cached by
--- changedtick: foldexpr asks once per line.
local task_cache = {}
local function hiddenLines(buf, mode)
    local c = task_cache[buf]
    local tick = vim.b[buf].changedtick
    if c and c.tick == tick and c.mode == mode then return c.hidden end
    local lines = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
    local hidden = {}
    local i = 1
    while i <= #lines do
        local state = taskState(lines[i])
        if state and (isDone(state) == (mode == "done")) then
            -- The task and everything indented deeper under it.
            local indent = #lines[i]:match("^%s*")
            hidden[i] = true
            local j = i + 1
            while j <= #lines do
                local l = lines[j]
                if l:match("^%s*$") then
                    -- A blank line is the task's only when more of it follows.
                    local nxt = lines[j + 1]
                    if not nxt or nxt:match("^%s*$") or #nxt:match("^%s*") <= indent then break end
                elseif #l:match("^%s*") <= indent then
                    break
                end
                hidden[j] = true
                j = j + 1
            end
            i = j
        else
            i = i + 1
        end
    end
    task_cache[buf] = { tick = tick, mode = mode, hidden = hidden }
    return hidden
end

--- foldexpr while a task view is on: the hidden task lines are one fold.
function M.taskFoldExpr(lnum)
    local buf = vim.api.nvim_get_current_buf()
    return hiddenLines(buf, vim.w.pure_task_fold or "done")[lnum] and "1" or "0"
end

--- <leader>zt ('done') / <leader>zT ('open'): fold those tasks away; the
--- same key again goes back to the automatic folds.
function M.tasks(mode)
    if vim.w.pure_task_fold == mode then return M.auto() end
    local buf = vim.api.nvim_get_current_buf()
    local any = next(hiddenLines(buf, mode)) ~= nil
    if not any then
        return vim.notify(mode == "done" and "No done tasks to fold" or "No open tasks to fold")
    end
    -- The foldlevel of before, for M.auto to put back: this view closes
    -- every fold (0), and leaving it at 0 closed the whole note afterwards.
    if not vim.w.pure_task_fold then
        vim.w.pure_task_prev_foldlevel = vim.wo.foldlevel
        vim.w.pure_task_prev_foldminlines = vim.wo.foldminlines
    end
    -- A task of one line is a fold of one line, which 'foldminlines' (1)
    -- never closes: with the open tasks one line each, <leader>zT did nothing.
    vim.wo.foldminlines = 0
    vim.w.pure_task_fold = mode
    -- Through manual: from one task view to the other the foldexpr is the
    -- same string, and Neovim recomputes expr folds only when it changes.
    vim.wo.foldmethod = "manual"
    vim.wo.foldexpr = "v:lua.require'pure.folding'.taskFoldExpr(v:lnum)"
    vim.wo.foldmethod = "expr"
    vim.wo.foldlevel = 0
    -- Setting foldlevel to the 0 it already was (the other task view) does
    -- not close the new folds; zX applies it to them. Neovim recomputes the
    -- folds only when they are next asked for, so they are asked for first
    -- (foldlevel()), or zX works on the old ones.
    vim.fn.foldlevel(1)
    vim.cmd("normal! zX")
end

--- <leader>zz: open or close the fold that STARTS on this line. It was za,
--- which closes the fold around the line: on a list item of a markdown
--- note that is the whole section, and in the last section everything to
--- the end of the buffer went with it. A line where no fold starts (and
--- that is not in a closed one) is left alone.
function M.toggleHere()
    local lnum = vim.fn.line(".")
    if vim.fn.foldclosed(lnum) ~= -1 then return vim.cmd("normal! zo") end
    local here, above = vim.fn.foldlevel(lnum), lnum > 1 and vim.fn.foldlevel(lnum - 1) or 0
    if here > 0 and here > above then return vim.cmd("normal! zc") end
    vim.notify("No fold starts on this line", vim.log.levels.INFO)
end

-- Example: "function foo() ... 󰁂 15 lines"
function _G.PureFoldText()
    local pos = vim.v.foldstart
    local line = vim.api.nvim_buf_get_lines(0, pos - 1, pos, false)[1]
    local lines_count = vim.v.foldend - vim.v.foldstart + 1

    -- A fold of the task view says what it holds: "󰄲 5 done tasks".
    local mode = vim.w.pure_task_fold
    if mode then
        local n = 0
        for _, l in ipairs(vim.api.nvim_buf_get_lines(0, pos - 1, vim.v.foldend, false)) do
            local state = taskState(l)
            if state and isDone(state) == (mode == "done") then n = n + 1 end
        end
        local indent = line:match("^%s*")
        return ("%s%s %d %s task%s"):format(indent, mode == "done" and "󰄲" or "󰄱", n, mode, n == 1 and "" or "s")
    end

    local clean_line = line:gsub("^%s+", ""):gsub("%s+$", "")
    if vim.bo.filetype == "markdown" then
        clean_line = plainMarkdown(clean_line)
    end

    -- "lines", not the Portuguese "linhas" it said: text in the code is
    -- English in this configuration.
    return clean_line .. " ... 󰁂 " .. lines_count .. " lines "
end

-- A folded line: no background, its text in the colorscheme's blue (the
-- Directory colour) instead of the solid Folded bar (Improvment.md). Set
-- again after every colorscheme, which would bring the bar back.
local function foldedHighlight()
    local dir = vim.api.nvim_get_hl(0, { name = "Directory", link = false })
    vim.api.nvim_set_hl(0, "Folded", { fg = dir.fg, bg = "NONE", ctermbg = "NONE" })
end
foldedHighlight()
vim.api.nvim_create_autocmd("ColorScheme", {
    group = vim.api.nvim_create_augroup("PureFoldedHighlight", { clear = true }),
    callback = foldedHighlight,
})

-- Automatic folds for the current window: treesitter when the buffer has a
-- parser, indentation otherwise. Also what <leader>zr goes back to after
-- folding by hand; the manual folds are dropped then.
function M.auto()
    -- Out of the task view, if it was on, with the foldlevel of before it.
    if vim.w.pure_task_fold then
        vim.w.pure_task_fold = nil
        vim.wo.foldlevel = vim.w.pure_task_prev_foldlevel or vim.o.foldlevel
        vim.wo.foldminlines = vim.w.pure_task_prev_foldminlines or vim.o.foldminlines
    end
    local ok, parser = pcall(vim.treesitter.get_parser)

    -- The fallback used to sit *inside* the success branch, where `ok` is
    -- always true, so it was dead code and buffers without a parser kept
    -- whatever foldmethod happened to be set.
    if ok and parser then
        vim.opt_local.foldmethod = "expr"
        vim.opt_local.foldexpr = "v:lua.vim.treesitter.foldexpr()"
    else
        vim.opt_local.foldmethod = "indent"
    end
end

vim.api.nvim_create_autocmd("FileType", {
    group = fold_group,
    pattern = "*",
    callback = M.auto,
})

return M

end

-- lua/pure/fuzzyUtils.lua
package.preload["pure.fuzzyUtils"] = function(...)
local M = {}
local func = require('configs.functions')
local terms = require('pure.terms')
-- Every path handed to the shell is shellescape()d: this user's home is
-- "C:/Users/Mia Schionato", and an unquoted path broke at the space, so the
-- command died instantly and the floating window just blinked shut.
local cache_dir = vim.fn.stdpath("cache") if vim.fn.isdirectory(cache_dir) == 0 then vim.fn.mkdir(cache_dir, "p") end

-- Directories the pickers never descend into. `fd --hidden` walks straight into
-- .git and buries real results under dozens of internal files, and `ls -a`
-- lists it too. ripgrep already skips it on its own, so fuzzyGrep needs nothing.
--
-- ".obsidian" is the vault's own config directory: it holds hundreds of json
-- and plugin files that drown out the actual notes.
--
-- Override with, for example:
--   vim.g.pure_fuzzy_ignore = { ".git", ".obsidian", "node_modules", "target" }
local function ignoredDirs()
  return vim.g.pure_fuzzy_ignore or { ".git", ".obsidian" }
end

--- Guarantee a single trailing slash.
---
--- The pickers build the final file name with `path .. selection`, so a caller
--- passing ".../Atlas" instead of ".../Atlas/" silently produced
--- ".../Atlasnote.md". Normalising here keeps every call site in keymaps.lua
--- from having to remember the slash.
--- @param path string|nil
--- @return string|nil
local function asDir(path)
  if path == nil or path == "" then
    return path
  end
  return (path:gsub("[/\\]+$", "")) .. "/"
end

--- @return string flags for fd, e.g. --exclude '.git'
local function fdExcludes()
  local parts = {}
  for _, dir in ipairs(ignoredDirs()) do
    table.insert(parts, "--exclude " .. vim.fn.shellescape(dir))
  end
  return table.concat(parts, " ")
end

--- " --no-ignore-vcs" when `path` is inside the Obsidian vault, else "".
---
--- fd and rg skip what .gitignore lists, and the vault's .gitignore lists
--- the private folder (kept out of git, not out of reach): its notes never
--- showed in <leader>vf / <leader>vg. Outside the vault .gitignore is still
--- honoured, which is what keeps node_modules and build output out of a
--- project's pickers. The LLM tools (pure/llm.lua) keep honouring it in the
--- vault too, so private notes stay out of what a model can read.
--- @param path string|nil
--- @return string
local function vaultNoIgnore(path)
  local ok, zet = pcall(require, 'pure.zettelkasten')
  local vault = ok and zet.vaultPath and zet.vaultPath()
  if not (vault and path) then return "" end
  local function norm(p) return (vim.fs.normalize(p):gsub("/+$", "")):lower() .. "/" end
  local v = norm(vault)
  return norm(path):sub(1, #v) == v and " --no-ignore-vcs" or ""
end

--- @return string flags for ls, e.g. --ignore='.git'
---
--- Filtering inside ls rather than grepping its output is deliberate:
--- `ls --color=always` emits the reset sequence *between* the name and the
--- trailing slash (".git<ESC>[0m/"), so a plain `grep -v '\.git/$'` never
--- matches. '.' and '..' survive --ignore, so navigation still works.
local function lsIgnores()
  local parts = {}
  for _, dir in ipairs(ignoredDirs()) do
    table.insert(parts, "--ignore=" .. vim.fn.shellescape(dir))
  end
  return table.concat(parts, " ")
end--- The name a tool goes by on this system. Debian and Ubuntu, and so
--- Raspberry Pi OS, ship fd as "fdfind" and bat as "batcat" because other
--- packages had taken the short names; asking for "fd" there found nothing.
--- @param name string
--- @param alt string
--- @return string
local function tool(name, alt)
  if vim.fn.executable(name) == 0 and vim.fn.executable(alt) == 1 then
    return alt
  end
  return name
end

--- Whether `ls` is GNU's. --color and --ignore are GNU only: macOS ships BSD
--- ls, where the explorer's listing failed with "unrecognized option".
--- Asked once. On Windows the pickers run through Git bash, whose ls is GNU's.
local gnu_ls
local function isGnuLs()
  if gnu_ls == nil then
    if vim.fn.has("win32") == 1 then
      gnu_ls = true
    else
      local ok, res = pcall(function() return vim.system({ "ls", "--version" }):wait() end)
      gnu_ls = ok and res.code == 0
    end
  end
  return gnu_ls
end

--- The explorer's listing: hidden files included, "/" after directories, the
--- ignored directories left out.
--- @return string
local function lsList()
  if isGnuLs() then
    return "ls -ap --color=always " .. lsIgnores()
  end
  -- BSD ls has no --ignore, so grep drops them instead. Without colours: grep
  -- can only match a whole name when no escape sequence surrounds it.
  local parts = {}
  for _, dir in ipairs(ignoredDirs()) do
    table.insert(parts, "-e " .. vim.fn.shellescape(dir .. "/"))
  end
  if #parts == 0 then return "ls -ap" end
  return "ls -ap | grep -vxF " .. table.concat(parts, " ")
end

--- `ls` for the explorer's preview of a directory, in colour on both kinds.
--- @return string
local function lsPreview()
  return isGnuLs() and "ls -apF --color=always" or "CLICOLOR_FORCE=1 ls -apFG"
end

-- fzf starts its child processes (--preview above all) through its own shell,
-- which on Windows is cmd.exe -- not Neovim's 'shell'. The preview commands in
-- this file are POSIX ("if [ -d {} ]; then ... fi"), so cmd.exe answered with
-- "-d was unexpected at this time." and the picker closed the instant it opened.
--
-- Point fzf at the same bash Neovim already validated in init.lua. Set through
-- FZF_DEFAULT_OPTS so every picker in this file inherits it. Needs fzf >= 0.52
-- for --with-shell; older builds ignore the unknown option in the env var.
local function appendFzfOpts(extra)
  local existing = vim.env.FZF_DEFAULT_OPTS
  vim.env.FZF_DEFAULT_OPTS = existing and (existing .. " " .. extra) or extra
end

if vim.fn.has("win32") == 1 then
  local sh = vim.o.shell
  if not sh:lower():find("bash", 1, true) then
    sh = vim.fn.exepath("bash")
  end
  if sh ~= "" then
    appendFzfOpts('--with-shell "' .. vim.fs.normalize(sh) .. ' -c"')
  end
end

-- These pickers already run inside a dedicated floating window, so fzf must not
-- size or frame itself again.
--
-- A shell profile that exports FZF_DEFAULT_OPTS for interactive use (this one
-- sets "--height=60% --border") leaked into Neovim: fzf then took 60% of the
-- float and drew its own frame inside Neovim's rounded border, leaving roughly
-- four in every ten lines blank with a doubled outline. Appending wins because
-- fzf honours the last occurrence of a flag.
appendFzfOpts("--height=100% --border=none")

---@param opts table The options for fuzzy logic.
function M.fuzzyLogic(opts)
  local win,buf = func.createWindow(opts.title, opts.ratio)
  local temp = vim.fn.stdpath("cache") .. "/opts_run"
  vim.api.nvim_set_option_value('bufhidden', 'wipe', {buf = buf})
  -- The redirect target must be quoted; stdpath("cache") sits under the home
  -- directory, which contains a space, so "> C:/Users/Mia Schionato/..." was
  -- read by the shell as "> C:/Users/Mia" and every picker failed at once.
  vim.cmd(string.format("terminal %s > %s", opts.cmd, vim.fn.shellescape(temp)))

  -- Arrows reach fzf as an escape sequence (<Esc>[A). On Windows the
  -- terminal can deliver it split when fzf is busy, fzf then reads a lone
  -- <Esc> and quits: the grep picker closed on the first arrow key. Its own
  -- one-byte keys for the same moves cannot be split.
  local term_opts = { buffer = buf, nowait = true }
  vim.keymap.set('t', '<Up>', '<C-k>', term_opts)
  vim.keymap.set('t', '<Down>', '<C-j>', term_opts)

  vim.api.nvim_create_autocmd("TermClose", {
    buffer = buf,
    callback = function()
      local data = ""

      if vim.fn.filereadable(temp) == 1 then
        local f = io.open(temp, "r")
        if f then
          local last_line = ""
          for line in f:lines() do
            last_line = line
          end
          f:close()
          os.remove(temp)
          data = last_line:gsub("%s+$", "")
        end
      end

      vim.schedule(function()
        if vim.api.nvim_win_is_valid(win) then vim.api.nvim_win_close(win, true) end
        if vim.api.nvim_buf_is_valid(buf) then vim.api.nvim_buf_delete(buf, { force = true }) end

        local function finish()
          if data ~= "" then
            opts.callback(data)
          elseif opts.on_cancel then
            -- Esc / Ctrl-C in fzf, or nothing matched.
            opts.on_cancel()
          end
        end

        -- Leave terminal mode before handing over. Closing the window does not,
        -- and neither does :stopinsert: Neovim stays in terminal mode until the
        -- next key arrives, so the callback ran with mode() still 't' and the
        -- first key typed afterwards was spent leaving that mode (an input()
        -- prompt opened from the callback could lose it, or be cancelled).
        -- Feed the key that leaves terminal mode, and run the callback once
        -- Neovim reports the mode change.
        if vim.api.nvim_get_mode().mode == "t" then
          vim.api.nvim_create_autocmd("ModeChanged", {
            pattern = "t:*",
            once = true,
            callback = function() vim.schedule(finish) end,
          })
          vim.api.nvim_feedkeys(vim.keycode("<C-\\><C-n>"), "n", false)
        else
          finish()
        end
      end)
    end
    })
  -- Enter terminal mode straight away, then once more on the next tick.
  --
  -- This used to be deferred by 50ms alone, which left the picker sitting in
  -- terminal-normal mode for that window. Arrow keys pressed in it hit the
  -- move-line mappings rather than fzf, so the first keystroke after opening a
  -- picker could be swallowed. The deferred call is kept as a second attempt in
  -- case something steals focus while the job starts.
  vim.cmd("startinsert")
  vim.defer_fn(function()
    if vim.api.nvim_get_current_buf() == buf and vim.api.nvim_get_mode().mode ~= "t" then
      vim.cmd("startinsert")
    end
  end, 50)
end

--- Pick one line of `lines` with fzf; `on_pick(line)` gets the choice and
--- `on_cancel()`, when given, runs if nothing was picked.
---
--- Five pickers (jumps, buffers, oldfiles, colorschemes, vim.ui.select) each
--- wrote their list to a fixed temp file and piped it into fzf by hand. The
--- file is now unique per call and always removed, picked or cancelled.
---
--- Added for the backlinks picker (pure/notes.lua), which wanted the note
--- shown as you move, like fuzzyGrep:
---   cwd      run fzf in this folder, so relative paths in `lines` resolve
---   preview  true: lines are "path:line:text"; the file is previewed with
---            that line highlighted, as in fuzzyGrep
--- @param lines string[]
--- @param opts { title: string, ratio: number?, fzf: string?, cwd: string?, preview: boolean? }  fzf: extra flags
local pick_count = 0
local function pickList(lines, opts, on_pick, on_cancel)
  pick_count = pick_count + 1
  local temp = vim.fn.stdpath("cache") .. "/pick_" .. pick_count
  vim.fn.writefile(lines, temp)
  local flags = opts.fzf or ""
  if opts.preview then
    flags = flags .. " --delimiter : --preview '" .. tool("bat", "batcat")
      .. " --style=numbers --color=always --highlight-line {2} {1}' --preview-window 'up,60\\%,border-bottom,+{2}+3/3'"
  end
  local cmd = string.format("cat %s | fzf %s", vim.fn.shellescape(temp), flags)
  if opts.cwd then cmd = string.format("cd %s && %s", vim.fn.shellescape(opts.cwd), cmd) end
  M.fuzzyLogic({
    title = opts.title,
    ratio = opts.ratio or (opts.preview and 0.8 or 0.7),
    cmd = cmd,
    callback = function(selection)
      os.remove(temp)
      on_pick(selection)
    end,
    on_cancel = function()
      os.remove(temp)
      if on_cancel then on_cancel() end
    end,
  })
end

M.pickList = pickList

--- The fd list of `kind` ("file" or "directory") under `path` for fzf,
--- without what is under a folder starting with "." (.git, .cache,
--- AppData-like clutter), except .config, until the query itself starts
--- with ".": then everything, hidden included. Asked for in Improvment.md.
---
--- fzf reads one list; switching it needs a reload, done by a `change`
--- binding that runs a small script (on fzf's sh, Git bash on the windows
--- branch). It reloads only when the query's first character crosses "."
--- (the prompt, "> " or ".> ", remembers which list is shown), not on every
--- key. The commands live in temp files, which keeps the quoting of paths
--- with spaces out of fzf's own argument.
--- @return string cmd, function cleanup
local function dotAwareList(path, kind)
  local fd = tool("fd", "fdfind")
  local common = fdExcludes() .. vaultNoIgnore(path) .. " --type " .. kind
  local base = vim.fn.shellescape(path)
  local function script(lines)
    local file = vim.fs.normalize(vim.fn.tempname()) .. ".sh"
    vim.fn.writefile(lines, file)
    return file
  end
  -- Symlinked folders (Improvment.md: ~/windows, ~/D, ~/.config/windows in
  -- WSL) were never listed: fd does not follow links. Following them
  -- everywhere would walk a whole Windows home or a whole drive, so only a
  -- link sitting directly in `path` is followed, LINK_DEPTH levels deep, and
  -- the link itself is offered as a folder. .config follows its links too.
  local LINK_DEPTH = 3
  local links = ("(cd %s && for l in * .config/*; do [ -L \"$l\" ] && [ -d \"$l\" ] || continue; %s"
    .. "%s --follow --max-depth %d %s . \"$l\"; done)"):format(base,
    kind == "directory" and 'echo "$l"; ' or "", fd, LINK_DEPTH, common)
  local normal = script({
    ("%s %s . --strip-cwd-prefix --base-directory %s"):format(fd, common, base),
    ("[ -d %s ] && %s --hidden %s . .config --base-directory %s"):format(
      vim.fn.shellescape(path .. ".config"), fd, common, base),
    -- A folder list also offers .config itself.
    kind == "directory" and ("[ -d %s ] && echo .config"):format(vim.fn.shellescape(path .. ".config")) or "",
    links,
    "true",
  })
  local hidden = script({ ("%s --hidden %s . --strip-cwd-prefix --base-directory %s"):format(fd, common, base) })
  local toggle = script({
    'case "$FZF_QUERY" in',
    ('  .*) [ "$FZF_PROMPT" = ".> " ] || printf %%s \'change-prompt(.> )+reload(sh "%s")\' ;;'):format(hidden),
    ('  *) [ "$FZF_PROMPT" = ".> " ] && printf %%s \'change-prompt(> )+reload(sh "%s")\' ;;'):format(normal),
    'esac',
    'true',
  })
  local cmd = ('sh "%s" | fzf --prompt %s --bind %s'):format(normal, vim.fn.shellescape("> "),
    vim.fn.shellescape(('change:transform(sh "%s")'):format(toggle)))
  return cmd, function()
    for _, f in ipairs({ normal, hidden, toggle }) do os.remove(f) end
  end
end

function M.fuzzySearch(path)
  if path == nil then path = vim.uv.os_homedir():gsub("\\", "/") .. "/" end
  path = asDir(path)
  local list, cleanup = dotAwareList(path, "file")

  M.fuzzyLogic({
    title = "Fuzzy Search",
    ratio = 0.6,
    cmd = list .. " --keep-right --tiebreak=end",
    callback = function(selection)
      cleanup()
      vim.cmd("edit! " .. vim.fn.fnameescape(path .. selection))
      vim.cmd("filetype detect")
    end,
    on_cancel = cleanup,
  })
end


--- Live grep: ripgrep runs again on every change of the query, and fzf only
--- shows its results. It used to pipe `rg .` into fzf -- every line of every
--- file under `path`, twice (the "." was given two times), all loaded before
--- the first key. Nothing is listed until something is typed.
function M.fuzzyGrep(path)
  path = asDir(path)
  local rg = "rg --column --line-number --no-heading --color=always --smart-case" .. vaultNoIgnore(path)
  -- fzf wants input on stdin even with --disabled; give it an empty one.
  -- By shell, not by OS: the windows branch runs these through Git bash.
  local empty = vim.o.shell:lower():match("cmd%.exe$") and "type nul" or "true"
  local fzf = "fzf --ansi --disabled --delimiter :"
    -- An empty query would match every line; list nothing instead. POSIX
    -- test: fzf runs reload through sh (Git bash on the windows branch).
    .. string.format(" --bind %s", vim.fn.shellescape("change:reload:[ -z {q} ] || " .. rg .. " -- {q}"))
    .. " --preview '" .. tool("bat", "batcat") .. " --style=numbers --color=always --highlight-line {2} {1}' --preview-window 'up,60\\%,border-bottom,+{2}+3/3'"

  M.fuzzyLogic({
    title = "Fuzzy Grep",
    ratio = 0.8,
    -- Run from inside `path` so ripgrep prints relative names. Given an
    -- absolute path its output starts with the drive letter, and fzf splitting
    -- on ":" then made {1} the bare "C" and {2} the path, so bat was handed a
    -- path where it wanted a line number. Counting fields from the end is not
    -- an option here, unlike fuzzyJump: the matched text can contain colons.
    cmd = string.format("cd %s && %s | %s", vim.fn.shellescape(path), empty, fzf),
    callback = function(selection)
      local rel, line, col = selection:match("^(.-):(%d+):(%d+)")
      if not (rel and line and col) then return end
      -- Those names are relative to the cd above, so rebuild the full one.
      local full_path = path .. (rel:gsub("^%.[/\\]", ""))
      vim.cmd("edit! " .. vim.fn.fnameescape(full_path))
      -- ripgrep's column is 1-based, the cursor's 0-based: without the -1
      -- the cursor landed one character right of the match.
      vim.api.nvim_win_set_cursor(0, {tonumber(line), tonumber(col) - 1})
      vim.cmd("filetype detect")
    end
  })
end

--- Neovim's help files, and every section of this config's own docs/ pages
--- ("pure todoist › Sync on …"): picking a section opens its page in a split
--- at that heading, drawn by mdview.
function M.fuzzyHelp()
  local entries, targets = {}, {}

  -- The one-file build (scripts/bundle.lua) unpacks them elsewhere.
  local docs = (vim.g.pure_bundle_dir or vim.fn.stdpath("config")) .. "/docs"
  for _, name in ipairs(vim.fn.isdirectory(docs) == 1 and vim.fn.readdir(docs) or {}) do
    local file = docs .. "/" .. name
    if name:match("%.md$") then
      local page = name == "README.md" and "index" or name:gsub("%.md$", "")
      local in_code = false
      for lnum, line in ipairs(vim.fn.readfile(file)) do
        -- Headings inside code blocks are examples, not sections.
        if line:match("^%s*```") then in_code = not in_code end
        local heading = not in_code and line:match("^#+%s+(.+)")
        if heading then
          local entry = ("pure %s › %s"):format(page, heading)
          if not targets[entry] then
            table.insert(entries, entry)
            targets[entry] = { file = file, lnum = lnum }
          end
        end
      end
    end
  end

  for _, name in ipairs(vim.fn.readdir(vim.fn.expand("$VIMRUNTIME/doc"))) do
    if name:match("%.txt$") then table.insert(entries, name) end
  end

  pickList(entries, { title = "Help" }, function(selection)
    local target = targets[selection]
    if not target then return vim.cmd("help " .. vim.fn.fnameescape(selection)) end
    vim.cmd("split " .. vim.fn.fnameescape(target.file))
    vim.api.nvim_win_set_cursor(0, { target.lnum, 0 })
    vim.cmd("normal! zt")
  end)
end

function M.fuzzyGit()
  local path = vim.fn.expand("%:p:h")

  local fzf = "fzf --ansi --preview 'git show --color=always {1}' --preview-window 'up,60\\%,wrap,border-bottom'"
  local git = "git log --oneline --color=always "

  M.fuzzyLogic({
    title = "Fuzzy Git log",
    ratio = 0.8,
    cmd = string.format("cd %s && %s | %s", vim.fn.shellescape(path), git, fzf),
    -- The selection is "abc1234 commit message"; it used to be passed to
    -- :edit, which opened an empty file named after the commit. Show the
    -- commit instead, in a scratch split (q closes it).
    callback = function (selection)
      local sha = selection:match("^(%x+)")
      if not sha then return end
      local out = vim.fn.systemlist({ "git", "-C", path, "show", "--stat", "--patch", sha })
      vim.cmd("botright new")
      local buf = vim.api.nvim_get_current_buf()
      vim.bo[buf].buftype = "nofile"
      vim.bo[buf].bufhidden = "wipe"
      vim.api.nvim_buf_set_lines(buf, 0, -1, false, out)
      vim.bo[buf].filetype = "git"
      vim.bo[buf].modifiable = false
      vim.keymap.set("n", "q", "<cmd>close<cr>", { buffer = buf })
    end
  })
end


function M.fuzzyGitGrep()
  local git_grep = "git grep --line-number --column"
  local fzf = "fzf --ansi --delimiter : --preview '" .. tool("bat", "batcat") .. " --style=numbers --color=always --highlight-line {2} {1}' --preview-window 'up,60\\%,border-bottom,+{2}+3/3'"
  -- Already cd's below, so git grep prints relative names and {1}/{2} line up.
  local path = asDir(vim.fn.expand("%:p:h"))

  M.fuzzyLogic({
    title = "Fuzzy Git Grep",
    ratio = 0.8,
    cmd = string.format("cd %s && %s . | %s", vim.fn.shellescape(path), git_grep, fzf),
    callback = function(selection)
      local rel, line, col_str = selection:match("^(.-):(%d+):(%d+)")
      if not rel then return end
      local col = tonumber(col_str)
      -- Relative to the cd above, so opening it as-is only worked when Neovim's
      -- own cwd happened to match. Rebuild the full name instead.
      local full_path = path .. (rel:gsub("^%.[/\\]", ""))

      vim.cmd("edit! " .. vim.fn.fnameescape(full_path))
      if line and col then
        vim.api.nvim_win_set_cursor(0, {tonumber(line), col - 1}) -- git grep's column is 1-based
      end
      vim.cmd("filetype detect")
    end
  })
end

function M.fuzzyJump()
  local jumps = {}
  for _, jump in ipairs(vim.fn.getjumplist()[1]) do
    local path = vim.api.nvim_buf_get_name(jump.bufnr)
    if path ~= "" then
      table.insert(jumps, string.format("%s:%d:%d", path, jump.lnum, jump.col))
    end
  end

  -- Fields are counted from the END. These lines are "path:line:col", and on
  -- Windows the path starts with a drive letter, so splitting on ":" made {1}
  -- the bare letter "C" and {2} the path -- which bat received where it wanted
  -- a line number, hence "[bat error]: invalid digit found in string".
  -- {-2} is the line and {1..-3} rejoins the whole path, drive letter included.
  pickList(jumps, {
    title = "fuzzy jumps",
    ratio = 0.8,
    fzf = "--ansi --delimiter : --preview '" .. tool("bat", "batcat") .. " --style=numbers --color=always --highlight-line {-2} {1..-3}' --preview-window 'up,60\\%,border-bottom,+{-2}+3/3'",
  }, function(selection)
    -- Windows paths start with a drive letter, so a '^([^:]+):' pattern would
    -- stop at the 'C:' colon; the lazy '.-' matches up to ':line:col'.
    local full_path, line, col = selection:match("^(.-):(%d+):(%d+)")
    if not full_path then return end
    vim.cmd("edit! " .. vim.fn.fnameescape(full_path))
    vim.api.nvim_win_set_cursor(0, { tonumber(line), tonumber(col) })
    vim.cmd("filetype detect")
  end)
end


function M.fuzzyBuffers()
  local buffers = {}
  for _, bufnr in ipairs(vim.api.nvim_list_bufs()) do
    local name = vim.api.nvim_buf_get_name(bufnr)
    if vim.api.nvim_buf_is_loaded(bufnr) and vim.bo[bufnr].buflisted and name ~= "" then
      table.insert(buffers, vim.fn.fnamemodify(name, ":."))
    end
  end
  pickList(buffers, { title = "Fuzzy buffers", fzf = "--keep-right --tiebreak=end" }, function(selection)
    vim.cmd("edit " .. vim.fn.fnameescape(selection))
    vim.cmd("filetype detect")
  end)
end

function M.fuzzyOldfiles()
  local oldfiles = vim.tbl_filter(function(f)
    return vim.fn.filereadable(f) == 1
  end, vim.v.oldfiles)
  pickList(oldfiles, { title = "Oldfiles" }, function(selection)
    vim.cmd("edit " .. vim.fn.fnameescape(selection))
    vim.cmd("filetype detect")
  end)
end

function M.fuzzyColorscheme()
  pickList(vim.fn.getcompletion("", "color"), { title = "Colorschemes" }, function(theme)
    vim.cmd("colorscheme " .. vim.fn.fnameescape(theme))
    vim.g.MY_THEME = theme
    if vim.g.neovide then
      vim.api.nvim_set_hl(0, 'Normal', { bg = "#060b1e" })
    end
  end)
end

function M.setup()
  vim.ui.select = function(items, opts, selected)
    opts = opts or {}
    if #items == 0 then
      selected(nil, nil)
      return
    end

    local choices = {}
    for i, item in ipairs(items) do -- Check if table or plain text
      if opts.format_item then
        choices[i] = opts.format_item(item)
      else
        choices[i] = tostring(item)
      end
    end

    -- on_choice(nil, nil) on cancel, as vim.ui.select promises.
    pickList(choices, { title = opts.prompt or "Select" }, function(selection)
      for i, choice in ipairs(choices) do
        if choice == selection then return selected(items[i], i) end
      end
      selected(nil, nil)
    end, function() selected(nil, nil) end)
  end

  vim.ui.input = function(opts, callback)
    opts = opts or {}
    local prompt = opts.prompt or "Input: "
    local win, buf = func.createWindow(prompt, 0.8)
    vim.api.nvim_win_set_height(win, 1)

    if opts.default then
      vim.api.nvim_buf_set_lines(buf, 0, -1, false, {opts.default})
      vim.cmd("startinsert!")
    end

    local confirmed = false

    local function submit()
      local lines = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
      confirmed = true
      local input = table.concat(lines, "\n")
      -- <CR> in insert mode submits: leave insert mode, or the window
      -- underneath is left in it.
      vim.cmd("stopinsert")
      vim.api.nvim_win_close(win, true)
      vim.api.nvim_buf_delete(buf, { force = true })
      callback(input)
    end

    local function cancel()
      -- Marked as handled before the buffer goes: deleting it fires the
      -- BufWipeout below, which called back with nil a second time.
      confirmed = true
      vim.api.nvim_win_close(win, true)
      vim.api.nvim_buf_delete(buf, { force = true })
      callback(nil)
    end

    local opts_map = {noremap = true, silent = true, nowait = true, buffer = buf}
    vim.keymap.set('i', '<CR>', submit, opts_map)
    vim.keymap.set('n', '<CR>', submit, opts_map)

    vim.keymap.set('n', 'q', cancel, opts_map)
    vim.keymap.set('n', '<Esc>', cancel, opts_map)

    vim.api.nvim_create_autocmd("BufWipeout", {
      buffer = buf,
      callback = function()
        if not confirmed then
          callback(nil)
        end
      end
    })


    vim.defer_fn(function()
        if vim.api.nvim_win_is_valid(win) then
            if opts.default then
                vim.cmd("startinsert!")
            else
                vim.cmd("startinsert")
            end
        end
    end, 10)
  end
end

function M.NewFile(path)
  path = asDir(path)
  local list, cleanup = dotAwareList(path, "directory")
  M.fuzzyLogic({
    title = "Select New File Path",
    ratio = 0.6,
    cmd = list .. " --keep-right --tiebreak=end",
    on_cancel = cleanup,
    callback = function(selection)
      cleanup()
      vim.ui.input({prompt = "New file name: "}, function(input)
        if input and input ~= "" then
          vim.cmd("edit! " .. vim.fn.fnameescape(path .. selection .. "/" .. input))
        else
          -- was `path .. selection` .. "Untitled" -> ".../dirUntitled"
          vim.cmd("edit! " .. vim.fn.fnameescape(path .. selection .. "/Untitled"))
        end
      end)
    end
  })
end

--- A new file straight in `path`, with no folder to pick: the key already
--- says where (<leader>n. is ~/.config). Added because NewFile above asked
--- for a folder even then. Only <leader>nf still picks one.
---
--- vim.g.pure_new_file_ask_name (default true) asks for the name. false opens
--- an unnamed buffer whose window works in `path`, so ":w name" saves there.
--- @param path string
function M.NewFileIn(path)
  path = asDir(path)
  if vim.g.pure_new_file_ask_name == false then
    vim.cmd('enew')
    -- Window-local, so other windows keep their directory. 'autochdir' leaves
    -- an unnamed buffer alone, so this holds until the file gets a name.
    vim.cmd('lcd ' .. vim.fn.fnameescape(path))
    return vim.notify('New buffer in ' .. path .. '  (:w name saves it there)')
  end
  vim.ui.input({ prompt = 'New file in ' .. vim.fn.fnamemodify(path, ':~') .. ': ' }, function(input)
    if input == nil then return end -- cancelled: nothing made
    if input == '' then input = 'Untitled' end
    local target = path .. input
    -- A name with folders in it ("notes/idea.md") makes them.
    vim.fn.mkdir(vim.fs.dirname(target), 'p')
    vim.cmd('edit ' .. vim.fn.fnameescape(target))
  end)
end

--- A new folder inside `path`, asked for by name. Added with <leader>nd:
--- new files and new folders both live under <leader>n.
--- @param path string
function M.NewFolder(path)
  path = asDir(path)
  vim.ui.input({ prompt = 'New folder in ' .. vim.fn.fnamemodify(path, ':~') .. ': ' }, function(input)
    if not input or vim.trim(input) == '' then return end
    local dir = path .. vim.trim(input)
    if vim.fn.isdirectory(dir) == 1 then
      return vim.notify('Already exists: ' .. dir, vim.log.levels.WARN)
    end
    vim.fn.mkdir(dir, 'p')
    vim.notify('Created ' .. dir)
  end)
end

function M.CompilerCommand()
  vim.ui.input({prompt = "Compiler Command:"}, function(input)
    if input and input ~= "" then
      terms.toggleTerminal(input, 0.6)
    end
  end)
end

---@param path string|nil The directory path to explore. If nil, uses current working directory.
function M.fuzzyExplorer(path)
  if path == nil then path = vim.fn.getcwd() end

  -- Use ls -ap to show hidden files and classify with indicators (/ for dirs)
  local list_cmd = lsList()

  -- Preview command for fzf. It's executed in `path` directory.
  -- Added --line-range to bat to avoid lagging on large files.
  -- POSIX 'if/then/fi'. This was fish syntax ("if ...; ...; else ...; end"),
  -- which the bash 'shell' set in init.lua rejects, so the preview pane only
  -- ever rendered a syntax error.
  local preview_cmd = "if [ -d {} ]; then " .. lsPreview() .. " {}; else " .. tool("bat", "batcat")
    .. " --color=always --style=numbers --line-range :500 {}; fi"
  local fzf_cmd = string.format("fzf --ansi --preview='%s' --print-query", preview_cmd)

  M.fuzzyLogic({
    title = "Explorer: " .. path,
    ratio = 0.8,
    cmd = string.format("cd %s && %s | %s", vim.fn.shellescape(path), list_cmd, fzf_cmd),
          callback = function(selection)
            if not selection or selection == "" or selection == "./" then
              return -- Do nothing
            end
    
            local new_path = vim.fn.resolve(path .. "/" .. selection)
    
            if selection:sub(-1) == '/' then
              -- User intends to create/enter a directory
              if vim.fn.isdirectory(new_path) == 0 then
                -- Directory doesn't exist, create it
                vim.fn.mkdir(new_path, "p")
              end
              -- Enter the directory
              M.fuzzyExplorer(new_path)
            else
              -- User intends to open/create a file
              if vim.fn.isdirectory(new_path) == 1 then
                -- It's an existing directory, but no trailing slash was typed
                -- so we enter it instead of trying to edit it as a file.
                M.fuzzyExplorer(new_path)
              else
                -- It's a file (new or existing)
                vim.cmd("edit! " .. vim.fn.fnameescape(new_path))
              end
            end
          end  })
end

-- Exposed for tests.
M._lsList, M._lsPreview, M._tool = lsList, lsPreview, tool
M._setGnuLs = function(v) gnu_ls = v end

return M


end

-- lua/pure/gcal.lua
package.preload["pure.gcal"] = function(...)
-- =============================================================================
--  Google Calendar
-- =============================================================================
--  The connection pure/calendar.lua syncs through: authorization, access
--  tokens and the Calendar API v3, through curl.
--
--  Google has no personal token like Todoist: reading and writing your
--  calendars takes OAuth. Once:
--
--    1. console.cloud.google.com: a project, "Google Calendar API" enabled,
--       an OAuth consent screen (External; add yourself as a test user, then
--       "Publish app": while it is in "Testing" the authorization expires
--       every 7 days), and Credentials > Create > OAuth client ID >
--       "Desktop app".
--    2. In Neovim (asked on start, like the Todoist token, or :CalendarAuth):
--       paste the client ID and the client secret; the browser opens,
--       you allow access, done.
--
--  What is kept, in stdpath('data') (never in the repository):
--    google_calendar.json            client ID, client secret, refresh token
--    google_calendar_no_prompt       "never ask on start"
--  Secrets go to curl on stdin, so they never show in the process list.
--
--  Scopes: events (read and write) and the list of calendars (read).
-- =============================================================================

local M = {}

local data_dir = vim.fn.stdpath('data')
local creds_file = data_dir .. '/google_calendar.json'
local no_prompt_file = data_dir .. '/google_calendar_no_prompt'

-- Replaceable, for tests against a local fake.
local function authUrl() return vim.g.pure_calendar_auth_url or 'https://accounts.google.com/o/oauth2/v2/auth' end
local function tokenUrl() return vim.g.pure_calendar_token_url or 'https://oauth2.googleapis.com/token' end
local function apiUrl() return vim.g.pure_calendar_api_url or 'https://www.googleapis.com/calendar/v3' end

local SCOPES = 'https://www.googleapis.com/auth/calendar.events '
  .. 'https://www.googleapis.com/auth/calendar.calendarlist.readonly'

-- -----------------------------------------------------------------------------
--  Credentials
-- -----------------------------------------------------------------------------

local function readCreds()
  local ok, data = pcall(function() return vim.json.decode(table.concat(vim.fn.readfile(creds_file), '\n')) end)
  return ok and type(data) == 'table' and data or nil
end

local function writeCreds(c)
  vim.fn.mkdir(data_dir, 'p')
  vim.fn.writefile({ vim.json.encode(c) }, creds_file)
  -- Only this user may read it (a no-op on Windows).
  pcall(vim.uv.fs_chmod, creds_file, 384) -- 0600
end

--- Whether Google Calendar is connected.
function M.connected()
  local c = readCreds()
  return c ~= nil and c.refresh_token ~= nil
end

-- -----------------------------------------------------------------------------
--  HTTP
-- -----------------------------------------------------------------------------

local function urlencode(s)
  return (tostring(s):gsub('[^%w%-_%.~]', function(ch) return ('%%%02X'):format(ch:byte()) end))
end

local function urldecode(s)
  return (s:gsub('%+', ' '):gsub('%%(%x%x)', function(h) return string.char(tonumber(h, 16)) end))
end

local function form(t)
  local parts = {}
  for k, v in pairs(t) do table.insert(parts, urlencode(k) .. '=' .. urlencode(v)) end
  table.sort(parts)
  return table.concat(parts, '&')
end
M.form, M.urlencode = form, urlencode

--- curl `args`; `cb(err, data)` on the main loop with the decoded JSON.
local function curl(args, stdin, cb)
  local cmd = vim.list_extend({ 'curl', '-sS', '-w', '\n%{http_code}' }, args)
  local ok, err = pcall(vim.system, cmd, { stdin = stdin, text = true }, vim.schedule_wrap(function(res)
    if res.code ~= 0 then return cb('curl failed: ' .. vim.trim(res.stderr or '')) end
    local body, status = res.stdout:match('^(.*)\n(%d+)$')
    status = tonumber(status)
    if not status or status >= 300 then
      return cb(('Google %s -> HTTP %s %s'):format(args[#args] and args[#args]:match('^[^?]+') or '',
        tostring(status), vim.trim(body or '')), nil, status)
    end
    if not body or body == '' then return cb(nil, nil) end
    local decoded, data = pcall(vim.json.decode, body, { luanil = { object = true, array = true } })
    if not decoded then return cb('Invalid JSON from Google: ' .. tostring(data)) end
    cb(nil, data)
  end))
  if not ok then cb('Could not run curl: ' .. tostring(err)) end
end

--- POST to the token endpoint; the form (with the secrets) goes on stdin.
local function tokenRequest(fields, cb)
  curl({ '-X', 'POST', '-H', 'Content-Type: application/x-www-form-urlencoded', '--data-binary', '@-', tokenUrl() },
    form(fields), cb)
end

local access = { token = nil, expires = 0 }

--- A valid access token, refreshed when it is about to expire.
function M.accessToken(cb)
  if access.token and os.time() < access.expires - 60 then return cb(nil, access.token) end
  local c = readCreds()
  if not (c and c.refresh_token) then return cb('Google Calendar is not connected: run :CalendarAuth') end
  tokenRequest({
    client_id = c.client_id, client_secret = c.client_secret,
    refresh_token = c.refresh_token, grant_type = 'refresh_token',
  }, function(err, data)
    if err then
      if err:find('invalid_grant', 1, true) then
        err = 'The Google authorization expired or was revoked: run :CalendarAuth'
          .. ' (an app left in "Testing" expires every 7 days)'
      end
      return cb(err)
    end
    access.token, access.expires = data.access_token, os.time() + (tonumber(data.expires_in) or 3600)
    cb(nil, access.token)
  end)
end

--- Call the Calendar API; `body` is sent as JSON. `cb(err, data, status)`.
function M.request(method, path, body, cb)
  M.accessToken(function(err, token)
    if err then return cb(err) end
    local args = { '-X', method, '-H', '@-' }
    if body then vim.list_extend(args, { '-H', 'Content-Type: application/json', '--data-binary', vim.json.encode(body) }) end
    table.insert(args, apiUrl() .. path)
    curl(args, 'Authorization: Bearer ' .. token .. '\n', cb)
  end)
end

--- GET every page of a list endpoint; `cb(err, items)`.
function M.getAll(path, cb)
  local items = {}
  local function page(tokenArg)
    local sep = path:find('?', 1, true) and '&' or '?'
    M.request('GET', path .. (tokenArg and (sep .. 'pageToken=' .. urlencode(tokenArg)) or ''), nil, function(err, data)
      if err then return cb(err) end
      vim.list_extend(items, data and data.items or {})
      if data and data.nextPageToken then return page(data.nextPageToken) end
      cb(nil, items)
    end)
  end
  page(nil)
end

-- -----------------------------------------------------------------------------
--  Authorization (once)
-- -----------------------------------------------------------------------------

local function page(ok)
  local msg = ok and 'Neovim is connected to Google Calendar. You can close this tab.'
    or 'Authorization failed or was denied. Go back to Neovim.'
  return 'HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nConnection: close\r\n\r\n'
    .. '<!doctype html><html><body style="font-family:sans-serif;margin:3em"><h2>' .. msg .. '</h2></body></html>'
end

--- Ask for the client ID and secret, open the browser to allow access, and
--- keep the refresh token Google gives back. The browser is sent back to a
--- one-off server on 127.0.0.1 (Google's "loopback" flow for desktop apps).
function M.auth(done)
  local c = readCreds() or {}
  local ok, id = pcall(vim.fn.input, 'Google OAuth client ID (empty to cancel): ', c.client_id or '')
  id = ok and vim.trim(id) or ''
  if id == '' then return vim.notify('Google Calendar: not connected') end
  local ok2, secret = pcall(vim.fn.inputsecret, 'Client secret: ')
  secret = ok2 and vim.trim(secret) or ''
  if secret == '' then return vim.notify('Google Calendar: not connected') end

  local server = vim.uv.new_tcp()
  server:bind('127.0.0.1', 0)
  local port = server:getsockname().port
  local redirect = ('http://127.0.0.1:%d'):format(port)
  local finished = false
  local function finish() if not finished then finished = true; pcall(function() server:close() end) end end

  server:listen(4, function()
    local client = vim.uv.new_tcp()
    server:accept(client)
    local req = ''
    client:read_start(function(_, chunk)
      if not chunk then return client:close() end
      req = req .. chunk
      if not req:find('\r\n\r\n', 1, true) or finished then return end
      local target = req:match('^GET (%S+)') or ''
      local code = target:match('[?&]code=([^&]+)')
      if not code and not target:find('[?&]error=') then
        -- favicon or another stray request: not the redirect.
        return client:write('HTTP/1.1 404 Not Found\r\nConnection: close\r\n\r\n', function() client:close() end)
      end
      client:write(page(code ~= nil), function() client:close() end)
      finish()
      vim.schedule(function()
        if not code then return vim.notify('Google Calendar: authorization denied', vim.log.levels.WARN) end
        tokenRequest({
          code = urldecode(code), client_id = id, client_secret = secret,
          redirect_uri = redirect, grant_type = 'authorization_code',
        }, function(err, data)
          if err or not (data and data.refresh_token) then
            return vim.notify('Google Calendar: could not finish the authorization: '
              .. (err or 'no refresh token'), vim.log.levels.ERROR)
          end
          writeCreds({ client_id = id, client_secret = secret, refresh_token = data.refresh_token })
          access.token, access.expires = data.access_token, os.time() + (tonumber(data.expires_in) or 3600)
          os.remove(no_prompt_file)
          vim.notify('Google Calendar connected')
          if done then done() end
        end)
      end)
    end)
  end)
  -- Five minutes to allow access in the browser.
  vim.defer_fn(function()
    if not finished then
      finish()
      vim.notify('Google Calendar: gave up waiting for the browser; run :CalendarAuth again', vim.log.levels.WARN)
    end
  end, 5 * 60 * 1000)

  local url = authUrl() .. '?' .. form({
    client_id = id, redirect_uri = redirect, response_type = 'code', scope = SCOPES,
    access_type = 'offline', prompt = 'consent',
  })
  -- On Windows vim.ui.open runs `cmd.exe /c start <url>`, and cmd.exe cuts
  -- the URL at its first '&' (a command separator there): the browser got
  -- a broken link, or did not open. rundll32 hands it to the default
  -- browser untouched.
  if vim.fn.has('win32') == 1 then
    pcall(vim.ui.open, url, { cmd = { 'rundll32.exe', 'url.dll,FileProtocolHandler' } })
  else
    pcall(vim.ui.open, url)
  end
  -- Also on the clipboard, to paste into a browser by hand if none opened.
  pcall(vim.fn.setreg, '+', url)
  vim.notify('Allow access in the browser that just opened. If none did, paste the link'
    .. ' (it is on the clipboard) into a browser:\n' .. url)
end

--- On the first start with a UI and no connection, offer to connect, with
--- the option never to be asked again (like the Todoist token).
local function askOnStartup()
  if M.connected() or vim.uv.fs_stat(no_prompt_file) or #vim.api.nvim_list_uis() == 0 then return end
  vim.schedule(function()
    local choice = vim.fn.confirm(
      'Google Calendar is not connected (for ```calendar blocks).\n'
        .. 'Connect now? You need an OAuth client ID and secret: see <leader>fh "pure calendar".',
      '&Yes\n&Later\nNe&ver ask', 1)
    if choice == 1 then
      M.auth(function() pcall(function() require('pure.calendar').sync() end) end)
    elseif choice == 3 then
      vim.fn.mkdir(data_dir, 'p')
      vim.fn.writefile({ 'Delete this file to be asked again, or run :CalendarAuth' }, no_prompt_file)
      vim.notify('Will not ask again. Run :CalendarAuth to connect Google Calendar.')
    end
  end)
end

vim.api.nvim_create_autocmd('VimEnter', {
  group = vim.api.nvim_create_augroup('PureGcal', { clear = true }),
  once = true,
  callback = askOnStartup,
})
if vim.v.vim_did_enter == 1 then askOnStartup() end

vim.api.nvim_create_user_command('CalendarAuth', function()
  M.auth(function() pcall(function() require('pure.calendar').sync() end) end)
end, { desc = 'Connect Google Calendar (OAuth, once)' })

return M

end

-- lua/pure/git.lua
package.preload["pure.git"] = function(...)
-- =============================================================================
--  Git
-- =============================================================================
--  Everyday git from inside Neovim, no plugins: git itself through
--  vim.system (no shell, so paths with spaces need no quoting on any OS).
--  Every command runs in the repository of the current file.
--
--  The status buffer (M.status) lists staged, unstaged and untracked files;
--  keys act on the file under the cursor:
--    a  stage        u  unstage       r  discard changes (asks first)
--    d  diff         <CR> open file   c  commit        p  push
--    R  refresh      q / <Esc> close
-- =============================================================================

local M = {}

-- -----------------------------------------------------------------------------
--  Running git
-- -----------------------------------------------------------------------------

--- Directory to run git from: the current file's, or the cwd for buffers
--- that are not files (the status buffer keeps its repository in b:pure_git_root).
local function startDir()
  if vim.b.pure_git_root then return vim.b.pure_git_root end
  local name = vim.api.nvim_buf_get_name(0)
  if name ~= '' and vim.bo.buftype == '' then return vim.fs.dirname(name) end
  return vim.fn.getcwd()
end

--- Top level of the repository containing `dir`, or nil.
local function repoRoot(dir)
  local res = vim.system({ 'git', '-C', dir, 'rev-parse', '--show-toplevel' }, { text = true }):wait()
  if res.code ~= 0 then return nil end
  return vim.fs.normalize(vim.trim(res.stdout))
end

--- Run `git <args>` in `root`; `cb(ok, output)` on the main loop.
--- Without a callback it reports the result as a notification.
local function git(root, args, cb)
  local cmd = vim.list_extend({ 'git', '-C', root }, args)
  vim.system(cmd, { text = true }, vim.schedule_wrap(function(res)
    local out = vim.trim((res.stdout or '') .. '\n' .. (res.stderr or ''))
    if cb then return cb(res.code == 0, out) end
    local level = res.code == 0 and vim.log.levels.INFO or vim.log.levels.ERROR
    vim.notify('git ' .. args[1] .. (out ~= '' and (':\n' .. out) or ' done'), level)
  end))
end

--- The repository root and the current file relative to it, or nil + a message.
local function currentFile()
  local root = repoRoot(startDir())
  if not root then return nil, 'Not inside a git repository' end
  local name = vim.fs.normalize(vim.api.nvim_buf_get_name(0))
  if name == '' or vim.bo.buftype ~= '' then return nil, 'No file in this buffer' end
  -- Plain prefix strip: the path may contain '-', '.' or spaces. Case-blind
  -- on Windows, where git may print C:/ for a buffer named c:/ (same file).
  local prefix = name:sub(1, #root + 1)
  local same = vim.fn.has('win32') == 1 and prefix:lower() == (root .. '/'):lower() or prefix == root .. '/'
  if not same then return nil, 'File is outside ' .. root end
  return root, name:sub(#root + 2)
end

--- Reload buffers whose files git just changed (restore, pull, switch).
local function reloadBuffers()
  vim.cmd('checktime')
end

-- -----------------------------------------------------------------------------
--  Single-file and repository commands
-- -----------------------------------------------------------------------------

function M.addFile()
  local root, file = currentFile()
  if not root then return vim.notify(file, vim.log.levels.WARN) end
  git(root, { 'add', '--', file }, function(ok, out)
    vim.notify(ok and ('Staged ' .. file) or out, ok and vim.log.levels.INFO or vim.log.levels.ERROR)
  end)
end

function M.addAll()
  local root = repoRoot(startDir())
  if not root then return vim.notify('Not inside a git repository', vim.log.levels.WARN) end
  git(root, { 'add', '-A' }, function(ok, out)
    vim.notify(ok and 'Staged all changes' or out, ok and vim.log.levels.INFO or vim.log.levels.ERROR)
  end)
end

function M.unstageFile()
  local root, file = currentFile()
  if not root then return vim.notify(file, vim.log.levels.WARN) end
  git(root, { 'restore', '--staged', '--', file }, function(ok, out)
    vim.notify(ok and ('Unstaged ' .. file) or out, ok and vim.log.levels.INFO or vim.log.levels.ERROR)
  end)
end

--- Discard the working-tree changes of `file`. Asks first: they are gone for
--- good, git keeps no copy of uncommitted edits.
local function restore(root, file, done)
  if vim.fn.confirm('Discard all uncommitted changes to ' .. file .. '?', '&Discard\n&Cancel', 2) ~= 1 then
    return
  end
  git(root, { 'restore', '--', file }, function(ok, out)
    vim.notify(ok and ('Restored ' .. file) or out, ok and vim.log.levels.INFO or vim.log.levels.ERROR)
    reloadBuffers()
    if done then done() end
  end)
end

function M.restoreFile()
  local root, file = currentFile()
  if not root then return vim.notify(file, vim.log.levels.WARN) end
  restore(root, file)
end

--- Commit what is staged, asking for the message.
function M.commit(done)
  local root = repoRoot(startDir())
  if not root then return vim.notify('Not inside a git repository', vim.log.levels.WARN) end
  local ok, msg = pcall(vim.fn.input, 'Commit message: ')
  if not ok or vim.trim(msg) == '' then return vim.notify('Commit cancelled') end
  git(root, { 'commit', '-m', msg }, function(success, out)
    -- First line is enough: "[branch abc123] message".
    vim.notify(success and out:match('^[^\n]*') or out, success and vim.log.levels.INFO or vim.log.levels.ERROR)
    if done then done() end
  end)
end

function M.push()
  local root = repoRoot(startDir())
  if not root then return vim.notify('Not inside a git repository', vim.log.levels.WARN) end
  vim.notify('git push…')
  git(root, { 'push' })
end

function M.pull()
  local root = repoRoot(startDir())
  if not root then return vim.notify('Not inside a git repository', vim.log.levels.WARN) end
  vim.notify('git pull…')
  git(root, { 'pull' }, function(ok, out)
    vim.notify('git pull:\n' .. out, ok and vim.log.levels.INFO or vim.log.levels.ERROR)
    reloadBuffers()
  end)
end

--- Who last changed the cursor line, when, and in which commit.
function M.blameLine()
  local root, file = currentFile()
  if not root then return vim.notify(file, vim.log.levels.WARN) end
  local lnum = vim.fn.line('.')
  git(root, { 'blame', '-L', lnum .. ',' .. lnum, '--porcelain', '--', file }, function(ok, out)
    if not ok then return vim.notify(out, vim.log.levels.ERROR) end
    local sha = out:match('^(%x+)')
    if sha and sha:match('^0+$') then return vim.notify('Line ' .. lnum .. ': not committed yet') end
    local author = out:match('\nauthor (.-)\n') or '?'
    local time = tonumber(out:match('\nauthor%-time (%d+)')) or 0
    local summary = out:match('\nsummary (.-)\n') or ''
    vim.notify(('%s  %s, %s\n%s'):format(sha and sha:sub(1, 7) or '?', author, os.date('%Y-%m-%d', time), summary))
  end)
end

--- Pick a local branch and switch to it.
function M.switchBranch()
  local root = repoRoot(startDir())
  if not root then return vim.notify('Not inside a git repository', vim.log.levels.WARN) end
  git(root, { 'branch', '--format=%(refname:short)' }, function(ok, out)
    if not ok then return vim.notify(out, vim.log.levels.ERROR) end
    local branches = vim.split(out, '\n', { trimempty = true })
    vim.ui.select(branches, { prompt = 'Switch to branch' }, function(branch)
      if not branch then return end
      git(root, { 'switch', branch }, function(sok, sout)
        -- git refuses when local edits would be overwritten; its message says which.
        vim.notify(sok and ('On ' .. branch) or sout, sok and vim.log.levels.INFO or vim.log.levels.ERROR)
        reloadBuffers()
      end)
    end)
  end)
end

-- -----------------------------------------------------------------------------
--  Status buffer
-- -----------------------------------------------------------------------------

local status = { buf = nil, root = nil, rows = {} } -- rows: line number -> { file, section }

--- Parse `git status --porcelain=v1 -b` into the branch line and three lists.
local function parseStatus(out)
  local branch, staged, changed, untracked = '', {}, {}, {}
  for _, line in ipairs(vim.split(out, '\n', { trimempty = true })) do
    if line:sub(1, 2) == '##' then
      branch = line:sub(4)
    else
      local x, y, path = line:sub(1, 1), line:sub(2, 2), line:sub(4)
      -- A rename reads "old -> new"; the new name is the file that exists.
      path = path:match('%-> (.+)$') or path
      path = path:match('^"(.*)"$') or path
      if x == '?' then
        table.insert(untracked, { code = '??', file = path })
      else
        if x ~= ' ' then table.insert(staged, { code = x, file = path }) end
        if y ~= ' ' then table.insert(changed, { code = y, file = path }) end
      end
    end
  end
  return branch, staged, changed, untracked
end

local function refresh()
  if not (status.buf and vim.api.nvim_buf_is_valid(status.buf)) then return end
  git(status.root, { 'status', '--porcelain=v1', '-b' }, function(ok, out)
    if not vim.api.nvim_buf_is_valid(status.buf) then return end
    local lines, rows = {}, {}
    if not ok then
      lines = { '# Git', '', out }
    else
      local branch, staged, changed, untracked = parseStatus(out)
      lines = { '# Git — ' .. branch, '' }
      local function section(title, list, kind)
        if #list == 0 then return end
        table.insert(lines, '## ' .. title)
        for _, e in ipairs(list) do
          table.insert(lines, e.code .. '  ' .. e.file)
          rows[#lines] = { file = e.file, section = kind }
        end
        table.insert(lines, '')
      end
      section('Staged', staged, 'staged')
      section('Changes', changed, 'changed')
      section('Untracked', untracked, 'untracked')
      if #staged + #changed + #untracked == 0 then table.insert(lines, 'Nothing to commit, working tree clean.') end
      table.insert(lines, 'a stage · u unstage · r discard · d diff · <CR> open · c commit · p push · R refresh · q close')
    end
    status.rows = rows
    vim.bo[status.buf].modifiable = true
    vim.api.nvim_buf_set_lines(status.buf, 0, -1, false, lines)
    vim.bo[status.buf].modifiable = false
  end)
end

local function entry()
  return status.rows[vim.fn.line('.')]
end

--- Run `git <args> -- <file>` for the entry under the cursor, then refresh.
local function onEntry(args, fn)
  return function()
    local e = entry()
    if not e then return end
    if fn then return fn(e) end
    git(status.root, vim.list_extend(vim.deepcopy(args), { '--', e.file }), function(ok, out)
      if not ok then vim.notify(out, vim.log.levels.ERROR) end
      refresh()
    end)
  end
end

--- Diff of one entry in a split: staged changes for staged entries, working
--- changes otherwise; an untracked file is shown whole.
local function showDiff(e)
  local args = e.section == 'staged' and { 'diff', '--cached', '--', e.file }
    or e.section == 'untracked' and { 'diff', '--no-index', '--', '/dev/null', e.file }
    or { 'diff', '--', e.file }
  git(status.root, args, function(_, out)
    -- --no-index exits 1 when the files differ, which is always here.
    vim.cmd('botright new')
    local buf = vim.api.nvim_get_current_buf()
    vim.bo[buf].buftype = 'nofile'
    vim.bo[buf].bufhidden = 'wipe'
    vim.api.nvim_buf_set_lines(buf, 0, -1, false, vim.split(out, '\n'))
    vim.bo[buf].filetype = 'diff'
    vim.bo[buf].modifiable = false
    vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = buf })
  end)
end

function M.status()
  local root = repoRoot(startDir())
  if not root then return vim.notify('Not inside a git repository', vim.log.levels.WARN) end
  status.root = root

  if not (status.buf and vim.api.nvim_buf_is_valid(status.buf)) then
    local buf = vim.api.nvim_create_buf(false, true)
    status.buf = buf
    vim.bo[buf].bufhidden = 'hide'
    pcall(vim.api.nvim_buf_set_name, buf, 'git://status')
    vim.b[buf].pure_mdview = true -- let mdview draw the ## headings
    vim.bo[buf].filetype = 'markdown'

    local map = function(lhs, fn, desc) vim.keymap.set('n', lhs, fn, { buffer = buf, desc = desc }) end
    map('a', onEntry({ 'add' }), 'Stage file')
    map('u', onEntry({ 'restore', '--staged' }), 'Unstage file')
    map('r', onEntry(nil, function(e)
      if e.section == 'untracked' then
        return vim.notify('Untracked file: delete it yourself if you mean to', vim.log.levels.WARN)
      end
      restore(status.root, e.file, refresh)
    end), 'Discard changes')
    map('d', onEntry(nil, showDiff), 'Show diff')
    map('<CR>', onEntry(nil, function(e)
      vim.cmd('wincmd p')
      vim.cmd('edit ' .. vim.fn.fnameescape(status.root .. '/' .. e.file))
    end), 'Open file')
    map('c', function() M.commit(refresh) end, 'Commit')
    map('p', M.push, 'Push')
    map('R', refresh, 'Refresh')
    map('q', '<cmd>close<cr>', 'Close')
    map('<Esc>', '<cmd>close<cr>', 'Close')
  end
  vim.b[status.buf].pure_git_root = root

  local win = vim.fn.bufwinid(status.buf)
  if win ~= -1 then
    vim.api.nvim_set_current_win(win)
  else
    vim.cmd('botright split')
    vim.api.nvim_win_set_buf(0, status.buf)
  end
  vim.wo.spell = false
  refresh()
end

return M

end

-- lua/pure/indentscope.lua
package.preload["pure.indentscope"] = function(...)
-- =============================================================================
--  Indent scope
-- =============================================================================
--  Replaces mini.indentscope. Draws a vertical line beside the indented block
--  the cursor is in, and adds a text object and motions for that block:
--
--    ii / ai   inner scope (the block) / outer scope (plus the lines around it)
--    [i / ]i   jump to the line above / below the block
--
--  A "scope" is the run of lines around the cursor whose indent is at least
--  the reference indent. Blank lines never end it, so a block with an empty
--  line in the middle stays one scope. The first line above and below with a
--  smaller indent are its borders ("if x then" / "end").
--
--  Colour: PureIndentscopeSymbol (links to Delimiter unless a theme sets it).
--  Disable in a buffer with  vim.b.pure_indentscope_disable = true
-- =============================================================================

local M = {}

local symbol = '╎'
local delay = 100       -- ms after the last cursor move before redrawing
local max_lines = 10000 -- stop scanning this far from the cursor

local ns = vim.api.nvim_create_namespace('pure_indentscope')
local timer = assert(vim.uv.new_timer())
local drawn_buf = nil   -- the buffer holding the current marks, to clear it

vim.api.nvim_set_hl(0, 'PureIndentscopeSymbol', { link = 'Delimiter', default = true })

local function isBlank(lnum)
  return vim.fn.getline(lnum):match('^%s*$') ~= nil
end

--- Indent the scope is measured against.
---
--- On a blank line the line itself says nothing, so the deeper of its two
--- neighbours is used: an empty line inside a block belongs to that block.
---
--- On other lines the cursor column caps it (mini's indent_at_cursor): with
--- the cursor inside the leading whitespace, moving left selects wider and
--- wider scopes. Not on blank lines, where the cursor always sits in column 0
--- and the cap would always pick the outermost scope.
local function referenceIndent(lnum)
  if isBlank(lnum) then
    local prev = vim.fn.prevnonblank(lnum)
    local next = vim.fn.nextnonblank(lnum)
    return math.max(prev > 0 and vim.fn.indent(prev) or 0, next > 0 and vim.fn.indent(next) or 0)
  end
  return math.min(vim.fn.indent(lnum), vim.fn.virtcol('.'))
end

--- Scope around `lnum`, or nil when the cursor is not inside an indented block.
--- @return { top: integer, bottom: integer, border_top: integer?, border_bottom: integer?, col: integer }?
function M.getScope(lnum)
  lnum = lnum or vim.fn.line('.')
  local ref = referenceIndent(lnum)
  -- Indent 0 means the whole file: nothing to draw and no borders to jump to.
  if ref <= 0 then return nil end

  local last = vim.fn.line('$')
  local function inside(l)
    return isBlank(l) or vim.fn.indent(l) >= ref
  end

  local top = lnum
  while top > 1 and lnum - top < max_lines and inside(top - 1) do
    top = top - 1
  end
  local bottom = lnum
  while bottom < last and bottom - lnum < max_lines and inside(bottom + 1) do
    bottom = bottom + 1
  end

  -- Blank lines at either edge sit between blocks, not inside this one.
  while top < bottom and isBlank(top) do top = top + 1 end
  while bottom > top and isBlank(bottom) do bottom = bottom - 1 end

  local border_top = top > 1 and top - 1 or nil
  local border_bottom = bottom < last and bottom + 1 or nil

  -- The line is drawn in the column where the borders start, i.e. inside the
  -- body's leading whitespace. Without borders (a block at the very top of the
  -- file) fall back to one step left of the body.
  local col
  if border_top or border_bottom then
    col = math.max(border_top and vim.fn.indent(border_top) or 0,
      border_bottom and vim.fn.indent(border_bottom) or 0)
  else
    col = math.max(ref - vim.fn.shiftwidth(), 0)
  end

  return { top = top, bottom = bottom, border_top = border_top, border_bottom = border_bottom, col = col }
end

-- -----------------------------------------------------------------------------
--  Drawing
-- -----------------------------------------------------------------------------
-- What is drawn now: the buffer, and the column the marks are drawn at.
local drawn_buf, drawn_col

local function clear()
  if drawn_buf and vim.api.nvim_buf_is_valid(drawn_buf) then
    vim.api.nvim_buf_clear_namespace(drawn_buf, ns, 0, -1)
  end
  drawn_buf, drawn_col = nil, nil
end

local function enabled(buf)
  -- buftype ~= '' skips terminals, help, oil, the dashboard, quickfix, ...
  return vim.bo[buf].buftype == ''
    and not vim.b[buf].pure_indentscope_disable
    and not vim.g.pure_indentscope_disable
end

local function draw()
  local buf = vim.api.nvim_get_current_buf()
  local scope = enabled(buf) and M.getScope() or nil
  -- Only the visible part needs marks, so a long block costs no more than a
  -- screenful. Horizontal scroll moves the column the line has to be drawn at.
  local leftcol = vim.fn.winsaveview().leftcol
  local win_col = scope and (scope.col - leftcol) or -1
  if not scope or win_col < 0 then return clear() end
  if drawn_buf ~= buf or drawn_col ~= win_col then clear() end

  -- The rows that should have the line.
  local want = {}
  for lnum = math.max(scope.top, vim.fn.line('w0')), math.min(scope.bottom, vim.fn.line('w$')) do
    -- Skip lines whose text starts at or before that column (a line inside a
    -- string, for instance); drawing there would cover real characters.
    if isBlank(lnum) or vim.fn.indent(lnum) > scope.col then want[lnum - 1] = true end
  end

  -- Only the rows that differ are touched. Clearing and drawing it all again
  -- on every pause while typing made the whole line blink.
  for _, m in ipairs(vim.api.nvim_buf_get_extmarks(buf, ns, 0, -1, {})) do
    if want[m[2]] then
      want[m[2]] = nil
    else
      vim.api.nvim_buf_del_extmark(buf, ns, m[1])
    end
  end
  for row in pairs(want) do
    vim.api.nvim_buf_set_extmark(buf, ns, row, 0, {
      virt_text = { { symbol, 'PureIndentscopeSymbol' } },
      virt_text_win_col = win_col,
      hl_mode = 'combine',
      priority = 2,
    })
  end
  drawn_buf, drawn_col = buf, win_col
end

--- Redraw after `delay` ms without movement, so holding j does not redraw on
--- every line.
local function schedule()
  timer:stop()
  timer:start(delay, 0, vim.schedule_wrap(draw))
end

vim.api.nvim_create_autocmd(
