output: replace
tools: Read, Glob, Write
dirs: vault
---
Crie uma nota nova na pasta "3-Resources" do vault (crie a pasta se não existir)
com o conteúdo da seleção, reescrito como uma nota permanente: um título claro
(que é o nome do arquivo .md), o texto organizado, e um link de volta para a nota
atual em "Origem: [[nome da nota atual]]".
Depois responda apenas com a linha que vai substituir a seleção na nota atual:
um resumo de uma frase seguido do link [[título da nota nova]].
]==],
}

--- Write the example actions into the actions folder (never over a file).
function M.examples()
  local dir, where = actionsDir()
  dir = dir or where
  if not dir then return vim.notify('No vault set: run :ZettelVault', vim.log.levels.WARN) end
  vim.fn.mkdir(dir, 'p')
  local made = {}
  for name, text in pairs(EXAMPLES) do
    local path = dir .. '/' .. name
    if not vim.uv.fs_stat(path) then
      vim.fn.writefile(vim.split(text, '\n', { plain = true }), path)
      table.insert(made, name)
    end
  end
  table.sort(made)
  vim.notify(#made > 0 and ('Created in %s:\n  %s'):format(dir, table.concat(made, '\n  '))
    or 'The examples are already there')
  M.mapActionKeys()
end

-- :LLM*, as the module is no longer Claude's alone; the :Claude* names stay
-- as aliases, so habits and notes that name them keep working.
for _, prefix in ipairs({ 'LLM', 'Claude' }) do
  vim.api.nvim_create_user_command(prefix .. 'Actions', M.pickAction, { desc = 'Pick an LLM action and run it' })
  vim.api.nvim_create_user_command(prefix .. 'ActionsExamples', M.examples,
    { desc = 'Write the example LLM actions into the actions folder' })
end

local actions_group = vim.api.nvim_create_augroup('PureClaudeActions', { clear = true })
vim.api.nvim_create_autocmd('VimEnter', { group = actions_group, once = true,
  callback = function() pcall(M.mapActionKeys) end })
if vim.v.vim_did_enter == 1 then pcall(M.mapActionKeys) end
-- A saved action file updates the keys.
vim.api.nvim_create_autocmd('BufWritePost', {
  group = actions_group,
  pattern = '*.md',
  callback = function(args)
    local dir = actionsDir()
    if dir and vim.fs.normalize(args.file):lower():find(dir:lower(), 1, true) then pcall(M.mapActionKeys) end
  end,
})

-- -----------------------------------------------------------------------------
--  Blocks in notes
-- -----------------------------------------------------------------------------

local block_begin, block_end = '<!-- claude -->', '<!-- /claude -->'

--- Every ```claude or ```llm block: { first, last (0-based fence rows), options, prompt }.
local function blocksIn(lines)
  local blocks, i = {}, 1
  while i <= #lines do
    if lines[i]:match('^%s*```%s*claude%s*$') or lines[i]:match('^%s*```%s*llm%s*$') then
      local j = i + 1
      while j <= #lines and not lines[j]:match('^%s*```%s*$') do j = j + 1 end
      local options, body, head = {}, {}, true
      for k = i + 1, j - 1 do
        local key, value = lines[k]:match('^%s*(%a+)%s*:%s*(.-)%s*$')
        if head and key and (key == 'when' or key == 'run' or key == 'model') then
          options[key] = (key == 'model') and value or value:lower()
        else
          head = head and lines[k]:match('^%s*$') ~= nil
          table.insert(body, lines[k])
        end
      end
      table.insert(blocks, {
        first = i - 1, last = math.min(j, #lines) - 1,
        options = options, prompt = vim.trim(table.concat(body, '\n')),
      })
      i = j + 1
    else
      i = i + 1
    end
  end
  return blocks
end

--- The answer under `block`: 0-based rows of its markers; false when the
--- begin marker has no end (left alone), nil when there is none.
local function regionOf(lines, block)
  local row = block.last + 1
  if vim.trim(lines[row + 1] or '') ~= block_begin then return nil end
  for r = row + 1, #lines - 1 do
    local text = vim.trim(lines[r + 1])
    if text == block_end then return { first = row, last = r } end
    if text == block_begin or text:match('^```%s*claude') or text:match('^```%s*llm') then break end
  end
  return false
end

--- mdview hides a block that has an answer, and the answer's markers.
function M.hiddenBlocks(buf)
  local ranges = {}
  local lines = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
  for _, b in ipairs(blocksIn(lines)) do
    local region = regionOf(lines, b)
    if region then
      table.insert(ranges, { b.first, region.first })
      table.insert(ranges, { region.last, region.last })
    end
  end
  return ranges
end

local function key(p)
  p = vim.fs.normalize(p)
  return vim.fn.has('win32') == 1 and p:lower() or p
end

--- Not in the templates or the trash.
local function allowed(path)
  local ok, zet = pcall(require, 'pure.zettelkasten')
  local vault = ok and zet.vaultPath() or nil
  if not vault then return true end
  local note = key(path)
  for _, folder in ipairs({ zet.templatesPath and zet.templatesPath() or (vault .. '/Templates'),
    vault .. '/' .. ((zet._destinations or {}).Delete or '0-Inbox/Trash') }) do
    local f = key(folder)
    if note:sub(1, #f + 1) == f .. '/' then return false end
  end
  return true
end

local WEEKDAYS = {
  monday = 1, tuesday = 2, wednesday = 3, thursday = 4, friday = 5, saturday = 6, sunday = 7,
  segunda = 1, terca = 2, ['terça'] = 2, quarta = 3, quinta = 4, sexta = 5, sabado = 6, ['sábado'] = 6, domingo = 7,
}

local function noonOf(y, m, d) return os.time({ year = y, month = m, day = d, hour = 12 }) end
local DAY = 86400

--- Monday (noon) of ISO week `w` of `y`.
local function isoMonday(y, w)
  local jan4 = noonOf(y, 1, 4)
  local wday = (os.date('*t', jan4).wday + 5) % 7 -- Monday = 0
  return jan4 - wday * DAY + (w - 1) * 7 * DAY
end

--- Whether a block may run now in the note `path`: { ok, why }.
local function due(path, block)
  if block.options.run == 'manual' then return false end
  local name = vim.fn.fnamemodify(path, ':t:r')
  local now = os.time()
  local today = noonOf(os.date('*t', now).year, os.date('*t', now).month, os.date('*t', now).day)
  local week_start
  local y, m, d = name:match('^(%d%d%d%d)%-(%d%d)%-(%d%d)$')
  if y then
    if os.date('%Y-%m-%d', now) ~= name then return false end
  end
  local wy, ww = name:match('^(%d%d%d%d)%-W(%d%d)$')
  if wy then
    week_start = isoMonday(tonumber(wy), tonumber(ww))
    if today < week_start or today >= week_start + 14 * DAY then return false end
  end
  local my, mm = name:match('^(%d%d%d%d)%-(%d%d)$')
  if my then
    local first = noonOf(tonumber(my), tonumber(mm), 1)
    local after_next = noonOf(tonumber(my), tonumber(mm) + 2, 1)
    if today < first or today >= after_next then return false end
  end
  local when = block.options.when and WEEKDAYS[block.options.when]
  if when then
    week_start = week_start or (today - ((os.date('*t', today).wday + 5) % 7) * DAY)
    if today < week_start + (when - 1) * DAY then return false end
  end
  return true
end

local BLOCK_RULES = 'You are called from inside Neovim for a request written in a note of an Obsidian vault '
  .. '(the current folder). Your answer is written into the note, right under the request, as markdown. '
  .. 'Write ONLY that content: no preamble, no code fence around it, no heading repeating the request. '
  .. 'Use the note\'s language. You may read the vault (other notes) to answer, never change it. '
  .. 'Link notes as [[wikilinks]].'

local block_running = {} -- note key .. ':' .. block row -> true

--- Hints about where the periodic notes live, for requests like
--- "yesterday's daily".
local function vaultHints()
  local ok, zet = pcall(require, 'pure.zettelkasten')
  local out = {}
  for _, period in ipairs({ 'Daily', 'Weekly', 'Monthly' }) do
    local p = ok and zet._periodic and zet._periodic[period]
    if p then table.insert(out, ('%s notes: %s/%s.md'):format(period, p.folder, p.name)) end
  end
  return #out > 0 and ('Periodic notes (os.date names): ' .. table.concat(out, '; ')) or ''
end

--- Run `block` of the note in `buf` and write the answer under it.
local function runBlock(buf, block)
  local path = vim.api.nvim_buf_get_name(buf)
  local id = key(path) .. ':' .. block.first
  if block_running[id] then return end
  if block.prompt == '' then return end
  if block.prompt:find('{{', 1, true) then return end -- an unfilled template
  block_running[id] = true

  local ok, zet = pcall(require, 'pure.zettelkasten')
  local vault = ok and zet.vaultPath() or nil
  local cwd = vault and vim.uv.fs_stat(vault) and vault or workdir(buf)
  local lines = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
  local shown = (vim.fs.relpath and vim.fs.relpath(cwd, path)) or path
  -- /name at the start: that persona's instructions and context (never its
  -- write permission: a block runs on its own).
  local p, request = persona.split(block.prompt)
  -- A block in a private note: marked, as fileText does (see privateReason).
  local prompt = (isPrivate(path) and (PRIVATE_MARK .. '\n') or '') .. BLOCK_RULES .. '\n\n'
    .. (p and (persona.prompt(p, false) .. '\n\n') or '')
    .. ('Note: %s\nToday: %s\n%s\n\n<note>\n%s\n</note>\n\nRequest: %s'):format(shown,
      os.date('%Y-%m-%d, %A'), vaultHints(), table.concat(lines, '\n'), p and request or block.prompt)

  local m_label = modelLabel(block.options.model)
  -- With the seconds going (statusMark), as <leader>aa's window shows them.
  local status = statusMark(buf, block.last, m_label .. ' is answering…')
  local tick = vim.b[buf].changedtick
  run({
    prompt = prompt,
    tools = READ_TOOLS,
    model = block.options.model,
    cwd = cwd,
    on_done = function(err, text)
      block_running[id] = nil
      if not vim.api.nvim_buf_is_valid(buf) then return status.stop() end
      local at = status.id and vim.api.nvim_buf_get_extmark_by_id(buf, ns, status.id, {}) or {}
      status.stop()
      if err then return vim.notify(m_label .. ' block: ' .. err, vim.log.levels.ERROR) end
      -- Find the block again (lines may have moved meanwhile).
      local now = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
      local target
      for _, b in ipairs(blocksIn(now)) do
        if b.last == at[1] or (not target and b.prompt == block.prompt) then target = b end
      end
      if not target then return end
      local region = regionOf(now, target)
      if region == false then return end
      local new = { block_begin }
      vim.list_extend(new, unfence(text))
      table.insert(new, block_end)
      local s, e = target.last + 1, target.last + 1
      if region then s, e = region.first, region.last + 1 end
      local was_saved = not vim.bo[buf].modified
      vim.api.nvim_buf_set_lines(buf, s, e, false, new)
      -- Saved only when nothing else was pending: never someone's half edit.
      if was_saved and vim.b[buf].changedtick ~= tick and vim.bo[buf].buftype == '' then
        vim.api.nvim_buf_call(buf, function() vim.cmd('silent noautocmd update') end)
      end
    end,
  })
end

--- Run the blocks of `buf` that have no answer yet and are due.
local function autoBlocks(buf)
  if vim.g.pure_llm_blocks == false or vim.g.pure_claude_blocks == false then return end
  -- Scheduled after the event: the buffer may be gone by then (a template
  -- that moves the note writes it, then wipes the buffer of its old name).
  if not vim.api.nvim_buf_is_valid(buf) then return end
  if vim.bo[buf].buftype ~= '' or vim.bo[buf].modified then return end
  local path = vim.api.nvim_buf_get_name(buf)
  if path == '' or not allowed(path) then return end
  local lines = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
  for _, b in ipairs(blocksIn(lines)) do
    if regionOf(lines, b) == nil and due(path, b) then runBlock(buf, b) end
  end
end

--- Run (again) the block under the cursor.
function M.runBlockAtCursor()
  local buf = vim.api.nvim_get_current_buf()
  local row = vim.api.nvim_win_get_cursor(0)[1] - 1
  local lines = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
  for _, b in ipairs(blocksIn(lines)) do
    local region = regionOf(lines, b)
    local stop = region and region.last or b.last
    if row >= b.first and row <= stop then
      if not allowed(vim.api.nvim_buf_get_name(buf)) then
        return vim.notify('LLM: blocks do not run in templates or the trash')
      end
      return runBlock(buf, b)
    end
  end
  vim.notify(modelLabel() .. ': no ```claude or ```llm block under the cursor')
end

vim.api.nvim_create_autocmd({ 'BufWinEnter', 'BufWritePost' }, {
  group = vim.api.nvim_create_augroup('PureClaudeBlocks', { clear = true }),
  pattern = { '*.md', '*.markdown' },
  callback = function(args) vim.schedule(function() autoBlocks(args.buf) end) end,
})

-- :LLMBlock / :LLMModel, with the :Claude* names kept as aliases.
for _, prefix in ipairs({ 'LLM', 'Claude' }) do
  vim.api.nvim_create_user_command(prefix .. 'Block', M.runBlockAtCursor, {
    desc = 'Run the ```llm (or ```claude) block under the cursor (again)',
  })
  vim.api.nvim_create_user_command(prefix .. 'Model', function(opts)
    if opts.args and vim.trim(opts.args) ~= '' then
      M.setModel(vim.trim(opts.args))
    else
      M.selectModel()
    end
  end, {
    nargs = '?',
    desc = 'Select or set the active LLM model (Ollama / Claude / agy)',
    complete = function()
      return {
        'claude:default', 'claude:sonnet', 'claude:haiku', 'claude:opus',
        'ollama:gemma4:e4b', 'ollama:qwen3.5:9b', 'ollama:JetBrains/mellum2-instruct-q4_k_m', 'agy:',
      }
    end,
  })
end

M._blocksIn, M._due, M._unfence, M._run, M._extraContext = blocksIn, due, unfence, run, extraContext
M._runTool = runTool

return M

end

-- lua/pure/manim.lua
package.preload["pure.manim"] = function(...)
-- =============================================================================
--  Manim preview
-- =============================================================================
--  A window that plays the Manim scene you are writing, and plays it again
--  each time the file is saved.
--
--    <leader>mm   start (or stop) the preview of the scene under the cursor
--                 (the class above it; asked when the cursor is on none)
--    <leader>ms   choose another scene of the file
--    <leader>mp   only a part: the selection, or the block the cursor is in
--                 (from the comment above it to the next one)
--    <leader>mf   a picture of the scene at the cursor line
--    <leader>mi   live: the scene at the cursor line in a window where the
--                 mouse moves the camera (3D), with a Python shell below
--
--  Each keeps going on every save: the same part, the same line.
--
--  On every :w of that file, Manim renders the scene in the background
--  (`manim -ql`, low quality: fast) and the video replaces the one in the
--  window, looping. A render still running when you save again is dropped
--  for the new one. An error shows the end of the traceback, and its lines
--  go to the quickfix list (:copen).
--
--  The window is mpv (Linux, macOS and Windows), driven through its IPC
--  socket so it stays open and just loads the new video. Without mpv the
--  video opens in the system's player after each render.
--
--    vim.g.pure_manim_cmd = 'manim'   or { 'python', '-m', 'manim' }
--    vim.g.pure_manim_quality = 'l'   l (480p15), m (720p30), h (1080p60)
--    vim.g.pure_manim_args = {}       more arguments for manim
--    vim.g.pure_manim_viewer_args = {}  more for mpv ({ '--geometry=40%-0-0' }:
--                                     smaller, bottom right; '--ontop')
--
--  Videos are rendered under stdpath('cache')/manim, never next to the
--  project.
-- =============================================================================

local M = {}

local is_win = vim.fn.has('win32') == 1
local active = {}   -- buf -> { scene, job, count }
local viewer = {}   -- { proc, socket }

local function notify(msg, level) vim.notify('Manim: ' .. msg, level) end

--- Stop a process. On Windows its whole tree: pip's manim.exe is a
--- launcher, and killing it alone left Python rendering.
local function kill(obj)
  if not obj then return end
  if is_win and obj.pid then
    pcall(vim.system, { 'taskkill', '/T', '/F', '/PID', tostring(obj.pid) })
  else
    pcall(function() obj:kill(15) end)
  end
end

-- -----------------------------------------------------------------------------
--  Scenes
-- -----------------------------------------------------------------------------

--- Every scene class of the buffer: { name, row } (row 1-based).
local function scenes(buf)
  local out = {}
  for i, line in ipairs(vim.api.nvim_buf_get_lines(buf, 0, -1, false)) do
    local name, bases = line:match('^class%s+([%w_]+)%s*%((.-)%)%s*:')
    if name and bases:find('Scene', 1, true) then table.insert(out, { name = name, row = i }) end
  end
  return out
end

--- The scene the cursor is in (the last class at or above it), or nil.
local function sceneAtCursor(buf)
  local row = vim.api.nvim_win_get_cursor(0)[1]
  local found
  for _, s in ipairs(scenes(buf)) do
    if s.row <= row then found = s.name end
  end
  return found
end

local function chooseScene(buf, cb)
  local list = scenes(buf)
  if #list == 0 then return notify('no Scene class in this file', vim.log.levels.WARN) end
  if #list == 1 then return cb(list[1].name) end
  vim.ui.select(vim.tbl_map(function(s) return s.name end, list), { prompt = 'Manim scene' }, function(name)
    if name then cb(name) end
  end)
end

-- -----------------------------------------------------------------------------
--  Parts of a scene
-- -----------------------------------------------------------------------------
--  Manim numbers the animations of a scene as it plays them: every
--  self.play(...) and self.wait(...), from 0. `manim -n A,B` renders only
--  animations A to B; the ones before are applied without being rendered,
--  so the part starts from the right state, and the scene stops after B.
--  Lines are turned into those numbers by counting the calls written in
--  construct() above them: a play inside a loop or in another method
--  counts once here, so there the numbers can be off (the notification
--  says which ones were rendered).

local ns = vim.api.nvim_create_namespace('pure_manim')

--- construct() of `scene`: first and last line (1-based), and the indent of
--- its body. nil when not found.
local function constructOf(buf, scene)
  local lines = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
  local class_row, def_row, class_indent
  for i, l in ipairs(lines) do
    local ind, name = l:match('^(%s*)class%s+([%w_]+)')
    if name == scene then class_row, class_indent = i, #ind end
    if class_row and i > class_row and l:match('^%s*def%s+construct%s*%(') then def_row = i break end
  end
  if not def_row then return nil end
  local def_indent = #lines[def_row]:match('^%s*')
  local body_indent, last = nil, def_row
  for i = def_row + 1, #lines do
    local l = lines[i]
    if l:match('%S') then
      local ind = #l:match('^%s*')
      if ind <= def_indent or (class_indent and ind <= class_indent) then break end
      body_indent = body_indent or ind
      last = i
    end
  end
  return { first = def_row + 1, last = last, indent = body_indent or def_indent + 4 }
end

--- How many animations the lines `from`..`to` of the buffer start.
local function countAnims(buf, from, to)
  local n = 0
  for _, l in ipairs(vim.api.nvim_buf_get_lines(buf, from - 1, to, false)) do
    if not l:match('^%s*#') then
      for _ in l:gmatch('self%.play%s*%(') do n = n + 1 end
      for _ in l:gmatch('self%.wait%s*%(') do n = n + 1 end
    end
  end
  return n
end

--- The block the cursor is in: from the comment line above it (in the
--- body of construct) to the line before the next one, as in a notebook
--- cell. Without such comments, the whole construct.
local function blockAt(buf, c, row)
  local lines = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
  local function isMark(i)
    local l = lines[i] or ''
    return #l:match('^%s*') == c.indent and l:match('^%s*#') ~= nil
  end
  local first, last = c.first, c.last
  for i = math.min(row, c.last), c.first, -1 do
    if isMark(i) then first = i break end
  end
  for i = math.max(row, first) + 1, c.last do
    if isMark(i) then last = i - 1 break end
  end
  while last > first and not (lines[last] or ''):match('%S') do last = last - 1 end
  return first, last
end

-- -----------------------------------------------------------------------------
--  The window (mpv)
-- -----------------------------------------------------------------------------

local function socketPath()
  if is_win then return ([[\\.\pipe\pure-manim-%d]]):format(vim.uv.os_getpid()) end
  return ('%s/pure-manim-%d.sock'):format(vim.fn.stdpath('run'), vim.uv.os_getpid())
end

--- Send one command to the running mpv; `cb(ok)`.
local function send(command, cb)
  local pipe = vim.uv.new_pipe(false)
  pipe:connect(viewer.socket, function(err)
    if err then
      pipe:close()
      return cb and vim.schedule(function() cb(false) end)
    end
    pipe:write(vim.json.encode({ command = command }) .. '\n', function()
      pipe:close()
      if cb then vim.schedule(function() cb(true) end) end
    end)
  end)
end

local function startViewer(path)
  viewer.socket = socketPath()
  if not is_win then os.remove(viewer.socket) end
  local cmd = { 'mpv', '--loop-file=inf', '--keep-open=yes', '--force-window=yes', '--no-terminal',
    '--image-display-duration=inf',
    '--title=Manim preview', '--input-ipc-server=' .. viewer.socket }
  vim.list_extend(cmd, vim.g.pure_manim_viewer_args or {})
  table.insert(cmd, path)
  local ok, proc = pcall(vim.system, cmd, {}, function()
    vim.schedule(function() viewer.proc = nil end)
  end)
  if not ok then
    viewer.proc = nil
    return notify('could not start mpv: ' .. tostring(proc), vim.log.levels.ERROR)
  end
  viewer.proc = proc
end

--- Show `path` in the window, starting it if needed.
local function show(path)
  if vim.fn.executable('mpv') == 0 then
    -- No mpv: the system's player, once per render.
    return vim.ui.open(path)
  end
  if not viewer.proc then return startViewer(path) end
  send({ 'loadfile', path, 'replace' }, function(sent)
    -- The window was closed by hand (and the socket with it): a new one.
    if not sent then startViewer(path) end
  end)
end

function M.closeViewer()
  if viewer.proc then
    kill(viewer.proc)
    viewer.proc = nil
  end
  if viewer.socket and not is_win then os.remove(viewer.socket) end
end

-- -----------------------------------------------------------------------------
--  Rendering
-- -----------------------------------------------------------------------------

local function manimCmd()
  local cmd = vim.g.pure_manim_cmd or 'manim'
  if type(cmd) == 'table' then return vim.deepcopy(cmd) end
  if vim.fn.executable(cmd) == 1 then return { cmd } end
  -- Installed with pip but not on the PATH: through Python.
  for _, py in ipairs(is_win and { 'py', 'python' } or { 'python3', 'python' }) do
    if vim.fn.executable(py) == 1 then return { py, '-m', 'manim' } end
  end
  return nil
end

--- The rendered file: the newest `name`.`ext` under `dir`.
local function findOutput(dir, name, ext)
  local best, best_time
  for _, p in ipairs(vim.fn.globpath(dir, '**/' .. name .. '.' .. ext, false, true)) do
    local st = vim.uv.fs_stat(p)
    if st and (not best_time or st.mtime.sec > best_time) then best, best_time = p, st.mtime.sec end
  end
  return best
end

--- Where the error is, as quickfix items, and its message. Manim prints
--- tracebacks in boxes (rich), with long paths wrapped across lines, so
--- the frames are found by the file's own name ("cena.py:6 in construct");
--- plain Python tracebacks ('File "x", line 6') are read too.
local function parseError(output, file)
  local items = {}
  local base = vim.pesc(vim.fs.basename(file))
  for lnum, where in output:gmatch(base .. ':(%d+) in ([%w_]+)') do
    table.insert(items, { filename = file, lnum = tonumber(lnum), text = 'in ' .. where })
  end
  for path, lnum in output:gmatch('File "([^"]+)", line (%d+)') do
    table.insert(items, { filename = path, lnum = tonumber(lnum) })
  end
  -- The message: the last line that is not part of a box.
  local message
  for line in output:gmatch('[^\n]+') do
    if not line:match('^%s*[│╭╰]') and line:match('%S') and not line:match('^%s*INFO') then
      message = vim.trim(line)
    end
  end
  for _, it in ipairs(items) do it.text = (it.text and (it.text .. ': ') or '') .. (message or '') end
  return items, message
end

local function render(buf)
  local st = active[buf]
  if not st then return end
  local file = vim.api.nvim_buf_get_name(buf)
  local cmd = manimCmd()
  if not cmd then return notify('manim is not installed (pip install manim)', vim.log.levels.ERROR) end

  -- A render still running is replaced by this one.
  if st.job then kill(st.job) end

  -- A new name each time: on Windows the video mpv is playing is locked
  -- and could not be written over.
  st.count = (st.count or 0) + 1
  local name = ('%s-%d'):format(st.scene, st.count)
  local dir = vim.fn.stdpath('cache') .. '/manim/' .. vim.fn.sha256(file):sub(1, 12)
  vim.list_extend(cmd, { '-q' .. (vim.g.pure_manim_quality or 'l'), '--media_dir', dir, '-o', name,
    '--progress_bar', 'none' })
  vim.list_extend(cmd, vim.g.pure_manim_args or {})

  -- A part or a frame: which animations, from the marked lines as they are
  -- now (edits above them move the marks along).
  local what, ext = st.scene, 'mp4'
  if st.mode ~= 'scene' then
    local c = constructOf(buf, st.scene)
    if not c then return notify('no construct() in ' .. st.scene, vim.log.levels.WARN) end
    local a = vim.api.nvim_buf_get_extmark_by_id(buf, ns, st.marks[1], {})[1] + 1
    local b = vim.api.nvim_buf_get_extmark_by_id(buf, ns, st.marks[2], {})[1] + 1
    local before = countAnims(buf, c.first, a - 1)
    if st.mode == 'part' then
      local inside = countAnims(buf, a, b)
      if inside == 0 then
        return notify(('lines %d-%d play no animation (no self.play / self.wait)'):format(a, b), vim.log.levels.WARN)
      end
      vim.list_extend(cmd, { '-n', ('%d,%d'):format(before, before + inside - 1) })
      what = inside == 1 and ('%s, animation %d'):format(st.scene, before)
        or ('%s, animations %d-%d'):format(st.scene, before, before + inside - 1)
    else
      -- frame: the scene as it is after the animations up to this line.
      local upto = before + countAnims(buf, a, a) - 1
      if upto < 0 then return notify('no animation before line ' .. a .. ' yet', vim.log.levels.WARN) end
      vim.list_extend(cmd, { '-s', '-n', ('0,%d'):format(upto) })
      what, ext = ('%s after animation %d (line %d)'):format(st.scene, upto, a), 'png'
    end
  end
  vim.list_extend(cmd, { file, st.scene })

  local started = vim.uv.hrtime()
  notify(('rendering %s…'):format(what))
  local job
  local ok, obj = pcall(vim.system, cmd, {
    cwd = vim.fs.dirname(file),
    text = true,
    env = { NO_COLOR = '1', TERM = 'dumb' },
  }, vim.schedule_wrap(function(res)
    if not active[buf] or active[buf].job ~= job then return end -- stopped or replaced
    st.job = nil
    if res.signal ~= 0 then return end
    local secs = (vim.uv.hrtime() - started) / 1e9
    local output = (res.stdout or '') .. '\n' .. (res.stderr or '')
    M.last_output = output
    if res.code ~= 0 then
      local items, message = parseError(output, file)
      vim.fn.setqflist({}, 'r', { title = 'Manim ' .. st.scene, items = items })
      local here = items[1] and items[1].filename == file and (' (line ' .. items[1].lnum .. ')') or ''
      return notify(('%s failed%s: %s\n:copen for the place, :ManimLog for the whole output'):format(
        what, here, message or ('exit code ' .. res.code)), vim.log.levels.ERROR)
    end
    local out = findOutput(dir, name, ext)
    if not out then return notify('rendered, but nothing found in ' .. dir, vim.log.levels.WARN) end
    notify(('%s ready (%.1fs)'):format(what, secs))
    show(out)
    -- The ones shown before: removed once the new one is showing (a moment
    -- later, as Windows keeps the one mpv still has open locked). Only
    -- those: a render that finishes meanwhile keeps its file.
    local old = st.shown or {}
    st.shown = { out }
    vim.defer_fn(function()
      for _, p in ipairs(old) do pcall(os.remove, p) end
    end, 2000)
  end))
  if not ok then return notify('could not run manim: ' .. tostring(obj), vim.log.levels.ERROR) end
  job = obj
  st.job = obj
end

-- -----------------------------------------------------------------------------
--  Live window (OpenGL renderer)
-- -----------------------------------------------------------------------------
--  <leader>mi runs the scene up to the cursor line in Manim's OpenGL
--  renderer: a live window, where the mouse moves the camera (drag:
--  orbit, middle drag: pan, wheel: zoom, r: reset), and an IPython shell
--  in a terminal below, with the scene as it is at that line (`self`,
--  play(), add(), remove(), wait()). `exit` in the shell lets the scene
--  play on to the end and closes the window.
--
--  It runs a copy of the file (in stdpath('cache')) with
--  self.interactive_embed() inserted after the statement at the cursor;
--  the file itself is not touched. The animations before it are applied
--  without being played (-n), so the window opens at that point at once.
--  Needs IPython (pip install ipython) and OpenGL 3.3.

local live -- { chan, buf, win }

--- Code of a line without strings and comments, to count brackets.
local function bare(line)
  return (line:gsub('\\.', ''):gsub('"[^"]*"', ''):gsub("'[^']*'", ''):gsub('#.*$', ''))
end

--- Where to insert the embed for the cursor at `row` in construct `c`:
--- the line to insert after (1-based) and the indent. After the whole
--- statement the cursor is on (not inside a call spanning lines), and
--- inside the block when that statement opens one (`for ...:`).
local function embedPoint(lines, c, row)
  row = math.max(math.min(row, c.last), c.first)
  -- Bracket depth at the start of every line of construct.
  local depth, at_start = 0, {}
  for i = c.first, c.last do
    at_start[i] = depth
    for ch in bare(lines[i]):gmatch('[%(%)%[%]{}]') do
      depth = depth + (ch:match('[%(%[{]') and 1 or -1)
    end
    depth = math.max(depth, 0)
  end
  local function code(i) local l = lines[i] or '' return l:match('%S') and not l:match('^%s*#') end
  -- The statement holding the cursor: its first line...
  local start = row
  while start > c.first and (not code(start) or at_start[start] > 0) do start = start - 1 end
  if not code(start) then return c.first - 1, c.indent end -- before any code
  -- ...and its last.
  local last = start
  for i = start, c.last do
    local after = at_start[i + 1] or 0
    last = i
    if i >= row and after == 0 and not bare(lines[i]):match('\\%s*$') then break end
  end
  local indent = lines[start]:match('^%s*')
  if bare(lines[last]):match(':%s*$') then
    -- A block header: the embed goes first thing in its body.
    for i = last + 1, c.last do
      if code(i) then indent = lines[i]:match('^%s*') break end
    end
  end
  return last, indent
end

function M.closeLive()
  if not live then return end
  pcall(vim.fn.jobstop, live.chan)
  if vim.api.nvim_win_is_valid(live.win) then pcall(vim.api.nvim_win_close, live.win, true) end
  live = nil
end

--- The scene at the cursor line, live: camera with the mouse, a shell.
--- Again: close it.
function M.interactive()
  if live then return M.closeLive() end
  local buf = vim.api.nvim_get_current_buf()
  local file = vim.api.nvim_buf_get_name(buf)
  local scene = sceneAtCursor(buf)
  if not scene then return notify('put the cursor inside a scene', vim.log.levels.WARN) end
  local c = constructOf(buf, scene)
  if not c then return notify('no construct() in ' .. scene, vim.log.levels.WARN) end
  local cmd = manimCmd()
  if not cmd then return notify('manim is not installed (pip install manim)', vim.log.levels.ERROR) end
  if vim.bo[buf].modified then vim.cmd('silent write') end

  local lines = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
  local after, indent = embedPoint(lines, c, vim.api.nvim_win_get_cursor(0)[1])
  table.insert(lines, after + 1, indent .. 'self.interactive_embed()  # added by pure/manim.lua')
  local before = countAnims(buf, c.first, after)

  -- The copy keeps the file's name (Manim names things after it) and runs
  -- in the file's folder, so its imports and asset paths still work.
  local dir = vim.fn.stdpath('cache') .. '/manim/live'
  vim.fn.mkdir(dir, 'p')
  local copy = dir .. '/' .. vim.fs.basename(file)
  vim.fn.writefile(lines, copy)
  local here = vim.fs.dirname(file)
  local sep = is_win and ';' or ':'
  vim.list_extend(cmd, { '-ql', '--renderer=opengl', '-p', '--media_dir', dir .. '/media' })
  if before > 0 then vim.list_extend(cmd, { '-n', tostring(before) }) end
  vim.list_extend(cmd, vim.g.pure_manim_args or {})
  vim.list_extend(cmd, { copy, scene })

  vim.cmd('botright ' .. (vim.g.pure_manim_shell_height or 12) .. 'new')
  local tbuf, twin = vim.api.nvim_get_current_buf(), vim.api.nvim_get_current_win()
  local chan = vim.fn.jobstart(cmd, {
    term = true,
    cwd = here,
    env = { PYTHONPATH = here .. (vim.env.PYTHONPATH and (sep .. vim.env.PYTHONPATH) or '') },
    on_exit = function(_, code)
      vim.schedule(function()
        local was = live
        if was and was.buf == tbuf then live = nil end
        if code == 0 then
          if vim.api.nvim_win_is_valid(twin) then pcall(vim.api.nvim_win_close, twin, true) end
          return
        end
        -- Kept open to read; the usual cause, said plainly.
        local text = table.concat(vim.api.nvim_buf_get_lines(tbuf, 0, -1, false), '\n')
        if text:find("No module named 'IPython'", 1, true) then
          notify('the live window needs IPython: pip install ipython', vim.log.levels.ERROR)
        elseif was then
          notify(('%s stopped (exit %d): the terminal below has the details'):format(scene, code),
            vim.log.levels.WARN)
        end
      end)
    end,
  })
  if chan <= 0 then
    pcall(vim.api.nvim_win_close, twin, true)
    return notify('could not start manim', vim.log.levels.ERROR)
  end
  live = { chan = chan, buf = tbuf, win = twin }
  notify(('%s live at line %d%s: drag to orbit, wheel to zoom, r to reset; exit in the shell to finish'):format(
    scene, after, before > 0 and (' (animations 0-' .. (before - 1) .. ' applied)') or ''))
  vim.cmd('startinsert')
end

-- -----------------------------------------------------------------------------
--  Commands
-- -----------------------------------------------------------------------------

--- Start previewing `scene`: the whole of it, or (`range`: { first, last }
--- lines) only a part or the frame at a line.
local function start(buf, scene, mode, range)
  local old = active[buf]
  if old and old.job then kill(old.job) end
  vim.api.nvim_buf_clear_namespace(buf, ns, 0, -1)
  local st = { scene = scene, mode = mode or 'scene', count = old and old.count, shown = old and old.shown }
  if range then
    st.marks = {
      vim.api.nvim_buf_set_extmark(buf, ns, range[1] - 1, 0, {}),
      vim.api.nvim_buf_set_extmark(buf, ns, range[2] - 1, 0, {}),
    }
  end
  active[buf] = st
  if vim.bo[buf].modified then vim.cmd('silent write') else render(buf) end
end

--- The visual selection as lines, leaving visual mode; nil outside it.
local function selection()
  if not vim.fn.mode():match('^[vV\22]') then return nil end
  local a, b = vim.fn.line('v'), vim.fn.line('.')
  vim.api.nvim_feedkeys(vim.keycode('<Esc>'), 'nx', false)
  return { math.min(a, b), math.max(a, b) }
end

--- Preview only part of the scene: the selection, or the block the cursor
--- is in (from the comment above it to the next). Saving renders that part
--- again.
function M.part()
  local buf = vim.api.nvim_get_current_buf()
  local range = selection()
  local scene = sceneAtCursor(buf)
  if not scene then return notify('put the cursor inside a scene', vim.log.levels.WARN) end
  local c = constructOf(buf, scene)
  if not c then return notify('no construct() in ' .. scene, vim.log.levels.WARN) end
  if not range then
    local first, last = blockAt(buf, c, vim.api.nvim_win_get_cursor(0)[1])
    range = { first, last }
  end
  start(buf, scene, 'part', range)
end

--- The scene as it is at the cursor line, as a picture. Saving draws it
--- again.
function M.frame()
  local buf = vim.api.nvim_get_current_buf()
  local scene = sceneAtCursor(buf)
  if not scene then return notify('put the cursor inside a scene', vim.log.levels.WARN) end
  local row = vim.api.nvim_win_get_cursor(0)[1]
  start(buf, scene, 'frame', { row, row })
end

--- Start the preview of the scene under the cursor, or stop it.
function M.toggle()
  local buf = vim.api.nvim_get_current_buf()
  if active[buf] and active[buf].mode == 'scene' then return M.stop(buf) end
  if vim.api.nvim_buf_get_name(buf) == '' then return notify('save the file first', vim.log.levels.WARN) end
  local scene = sceneAtCursor(buf)
  if scene then return start(buf, scene) end
  chooseScene(buf, function(name) start(buf, name) end)
end

--- Choose another scene for the preview (and start it).
function M.pick()
  local buf = vim.api.nvim_get_current_buf()
  chooseScene(buf, function(name)
    if active[buf] and active[buf].job then kill(active[buf].job) end
    start(buf, name)
  end)
end

function M.stop(buf)
  buf = buf or vim.api.nvim_get_current_buf()
  local st = active[buf]
  if st and st.job then kill(st.job) end
  active[buf] = nil
  pcall(vim.api.nvim_buf_clear_namespace, buf, ns, 0, -1)
  if next(active) == nil then M.closeViewer() end
  notify('preview stopped')
end

local group = vim.api.nvim_create_augroup('PureManim', { clear = true })
vim.api.nvim_create_autocmd('BufWritePost', {
  group = group,
  pattern = '*.py',
  callback = function(args) if active[args.buf] then render(args.buf) end end,
})
vim.api.nvim_create_autocmd('BufWipeout', {
  group = group,
  callback = function(args)
    if active[args.buf] then M.stop(args.buf) end
  end,
})
vim.api.nvim_create_autocmd('VimLeavePre', { group = group, callback = function()
  M.closeViewer()
  M.closeLive()
end })

vim.api.nvim_create_user_command('ManimPreview', function(o)
  local buf = vim.api.nvim_get_current_buf()
  if o.args ~= '' then return start(buf, o.args) end
  M.toggle()
end, {
  nargs = '?',
  complete = function() return vim.tbl_map(function(s) return s.name end, scenes(0)) end,
  desc = 'Preview a Manim scene, again on every save',
})
vim.api.nvim_create_user_command('ManimLog', function()
  if not M.last_output then return notify('nothing rendered yet') end
  local _, buf = require('configs.functions').createWindow(' Manim output ', 0.8)
  vim.api.nvim_buf_set_lines(buf, 0, -1, false, vim.split(M.last_output, '\n'))
  vim.bo[buf].bufhidden = 'wipe'
  vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = buf, nowait = true })
end, { desc = 'The output of the last Manim render' })
vim.api.nvim_create_user_command('ManimStop', function() M.stop() end, { desc = 'Stop the Manim preview' })

M._scenes, M._sceneAtCursor, M._constructOf, M._countAnims, M._blockAt, M._embedPoint =
  scenes, sceneAtCursor, constructOf, countAnims, blockAt, embedPoint

return M

end

-- lua/pure/mdview.lua
package.preload["pure.mdview"] = function(...)
-- =============================================================================
--  Markdown view
-- =============================================================================
--  Renders markdown in place, the way render-markdown.nvim does: the text is
--  never changed, extmarks draw over it (the same mechanism as the git diff
--  toggle in configs/functions.lua). Treesitter says what each piece is, so a
--  '-' inside a code block is never mistaken for a bullet.
--
--    # Heading         icon over the #s, coloured band across the line
--    - item            bullet per nesting level (• ◦ ▪ ▫, vim.g.pure_md_bullets)
--    - [ ] / - [x]     checkbox icons; done items are dimmed
--    > quote           bar instead of '>'
--    ---               full-width line
--    | tables |        box-drawing borders
--    ```lang           shaded block with the language as a label
--    `code`            shaded background
--    ---               the frontmatter (Obsidian's properties) is hidden
--    key: value
--    ---
--    [^1]: note        footnote definitions are hidden
--    text[^1]          footnote references show as a superscript: text¹
--    [[path/note|Text]]  wikilinks show only their text: Text
--    [[note#Section]]    ... or the note (and section): note > Section
--    ![[image.png]]      embeds get an icon: image or file
--    ```todoist          the query is hidden; pure/todoist.lua draws the tasks
--
--  Everything is drawn with 'overlay' virtual text of the same width as what
--  it covers, so columns never shift and the cursor lands where the real
--  characters are. The one exception is the bullet of a task item, which is
--  concealed so the checkbox sits where the bullet was.
--
--  The line under the cursor shows the raw markdown in insert and visual mode,
--  to edit it; in normal mode it stays rendered, like concealcursor=nc.
--  Hidden lines (frontmatter, footnotes, todoist queries) come back while the
--  cursor is on them: gg shows the frontmatter, and moving onto a footnote
--  shows it. A wikilink shows raw while the cursor is inside it, as in
--  Obsidian's live preview, so it can be edited and followed (<CR>).
--
--    <leader>om  toggle rendering
-- =============================================================================

local M = {}

local ns = vim.api.nvim_create_namespace('pure_mdview')
local enabled = true

local heading_icons = { '󰲡 ', '󰲣 ', '󰲥 ', '󰲧 ', '󰲩 ', '󰲫 ' }
-- Smaller glyphs than the old ● ○ ◆ ◇, which looked heavy next to the text
-- (asked for in the vault's Improvment.md). vim.g.pure_md_bullets overrides
-- them, one per nesting level, repeating after the last.
local bullets = vim.g.pure_md_bullets or { '•', '◦', '▪', '▫' }
local checkbox = { unchecked = '󰄱', checked = '󰄲' }
-- Obsidian's extra states. Markdown does not know them ('- [~] x' is a plain
-- item whose text starts with '[~]'), so render.bullet finds them by text.
-- Box-shaped icons, like the two checkboxes, written as code points: pasted
-- private-use glyphs have been lost in copying before, leaving empty icons.
local extra_states = {
  ['~'] = { '\u{F0856}', 'PureMdTaskProgress' },  -- md-checkbox_intermediate: in progress
  ['!'] = { '\u{F0CE4}', 'PureMdTaskImportant' }, -- md-alert_box_outline: important
  ['>'] = { '\u{F0736}', 'PureMdTaskDeferred' },  -- md-arrow_right_bold_box_outline: deferred
  ['-'] = { '\u{F06F2}', 'PureMdTaskCancelled' }, -- md-minus_box_outline: cancelled
}

-- -----------------------------------------------------------------------------
--  Colours
-- -----------------------------------------------------------------------------
--  Themes rarely know these groups, so each one links to something every
--  theme has. The heading bands are computed: the heading colour mixed into
--  the CursorLine background, so they follow the theme instead of being fixed
--  colours that clash with it.

local function hexToRgb(n) return math.floor(n / 65536) % 256, math.floor(n / 256) % 256, n % 256 end

--- `fg` mixed into `bg` by `amount` (0..1), both as 0xRRGGBB integers.
local function blend(fg, bg, amount)
  local fr, fg_, fb = hexToRgb(fg)
  local br, bg_, bb = hexToRgb(bg)
  local function mix(a, b) return math.floor(a * amount + b * (1 - amount) + 0.5) end
  return mix(fr, br) * 65536 + mix(fg_, bg_) * 256 + mix(fb, bb)
end

local function resolved(name)
  return vim.api.nvim_get_hl(0, { name = name, link = false })
end

local function setHighlights()
  local set = function(name, val) vim.api.nvim_set_hl(0, name, vim.tbl_extend('force', val, { default = true })) end

  -- A transparent theme has no Normal background to shade against, so the
  -- base is CursorLine's (it always has one to be visible), else near black.
  local dark = vim.o.background == 'dark'
  local base = resolved('CursorLine').bg or resolved('Normal').bg or (dark and 0x101010 or 0xf0f0f0)

  for level = 1, 6 do
    set('PureMdH' .. level, { link = '@markup.heading.' .. level .. '.markdown' })
    local fg = resolved('PureMdH' .. level).fg or resolved('Title').fg
    -- Not `default`: recomputed on every call so it follows the heading colour
    -- that render-md.lua assigns per level.
    vim.api.nvim_set_hl(0, 'PureMdH' .. level .. 'Bg', { bg = fg and blend(fg, base, 0.2) or base })
  end

  set('PureMdCode', { bg = base })
  set('PureMdCodeLabel', { link = 'Comment' })
  set('PureMdInlineCode', { bg = base })
  set('PureMdBullet', { link = 'Special' })
  set('PureMdQuote', { link = 'Comment' })
  set('PureMdRule', { link = 'Comment' })
  set('PureMdTable', { link = 'Comment' })
  set('PureMdCheckedText', { link = 'Comment' })
  set('PureMdFootnote', { link = 'Special' })
  set('PureMdLink', { link = '@markup.link.label' })

  -- Checkbox icons: fixed colours, the same in every colorscheme, so a state
  -- always reads the same at a glance. Not `default` and re-applied on
  -- ColorScheme: a theme switch must not restyle them.
  local task_colours = {
    PureMdTaskTodo      = '#8b949e', -- [ ] grey
    PureMdTaskDone      = '#3fb950', -- [x] green
    PureMdTaskProgress  = '#58a6ff', -- [~] blue
    PureMdTaskImportant = '#f85149', -- [!] red
    PureMdTaskDeferred  = '#a371f7', -- [>] purple
    PureMdTaskCancelled = '#6e7681', -- [-] dark grey
  }
  for name, fg in pairs(task_colours) do
    vim.api.nvim_set_hl(0, name, { fg = fg })
  end
end

-- -----------------------------------------------------------------------------
--  Queries
-- -----------------------------------------------------------------------------
local block_query = vim.treesitter.query.parse('markdown', [[
  (atx_heading) @heading
  (fenced_code_block) @code
  [(list_marker_minus) (list_marker_plus) (list_marker_star)] @bullet
  (task_list_marker_unchecked) @unchecked
  (task_list_marker_checked) @checked
  (block_quote) @quote
  (thematic_break) @rule
  (pipe_table) @table
]])

local inline_query = vim.treesitter.query.parse('markdown_inline', [[
  (code_span) @code_span
]])

-- -----------------------------------------------------------------------------
--  Renderers, one per capture
-- -----------------------------------------------------------------------------
--  Each gets the buffer, the node and a `mark(row, col, opts)` helper that
--  skips the raw (cursor) line.

local function lineText(buf, row)
  return vim.api.nvim_buf_get_lines(buf, row, row + 1, false)[1] or ''
end

--- Last row a block node really covers. Blocks end at column 0 of the line
--- after them, which is not part of the block.
local function lastRow(node)
  local _, _, er, ec = node:range()
  return ec == 0 and er - 1 or er
end

local render = {}

function render.heading(buf, node, mark)
  local row = node:start()
  local marker = node:child(0)
  local level = tonumber(marker:type():match('atx_h(%d)_marker'))
  if not level then return end

  -- The #s plus the space after them; the icon is right-aligned in that width
  -- so the heading text does not move.
  local _, sc, _, ec = marker:range()
  local width = ec - sc + 1
  local icon = heading_icons[level]
  local pad = math.max(width - vim.fn.strdisplaywidth(icon), 0)
  mark(row, sc, {
    virt_text = { { string.rep(' ', pad) .. icon, 'PureMdH' .. level } },
    virt_text_pos = 'overlay',
  })
  mark(row, 0, { line_hl_group = 'PureMdH' .. level .. 'Bg' })
end

function render.code(buf, node, mark)
  local first, last = node:start(), lastRow(node)
  -- A calendar grid (pure/calendar.lua) is a code block only to keep it
  -- monospaced in Obsidian: no shading, no label.
  local ok, calendar = pcall(require, 'pure.calendar')
  if ok and calendar.isGrid(buf, first) then return end
  for row = first, last do
    mark(row, 0, { line_hl_group = 'PureMdCode' })
  end

  -- Fence lines: cover ```lang with the language as a label.
  local lang = ''
  for child in node:iter_children() do
    if child:type() == 'info_string' then
      lang = vim.treesitter.get_node_text(child, buf):match('^%S+') or ''
    end
  end
  for _, row in ipairs({ first, last }) do
    local text = lineText(buf, row)
    local indent = #text:match('^%s*')
    local label = row == first and lang ~= '' and (' ' .. lang) or ''
    local cover = vim.fn.strdisplaywidth(text) - indent
    mark(row, indent, {
      virt_text = { { label .. string.rep(' ', math.max(cover - vim.fn.strdisplaywidth(label), 0)), 'PureMdCodeLabel' } },
      virt_text_pos = 'overlay',
    })
  end
end

--- The list marker's range without the spaces the parser sometimes puts in
--- it: for a nested item under a task ("    - [ ] sub") the marker node
--- was "  - " from column 2, so concealing it hid half the indentation and
--- the subtask showed level with its parent (Improvment.md).
local function markerRange(buf, node)
  local row, sc, _, ec = node:range()
  local lead = #(lineText(buf, row):sub(sc + 1, ec):match('^%s*'))
  return row, sc + lead, ec
end

--- Bullets change with depth; a task item's bullet is hidden instead, since
--- the checkbox takes its place.
function render.bullet(buf, node, mark)
  local item = node:parent()
  for child in item:iter_children() do
    if child:type():match('^task_list_marker') then
      local row, sc, ec = markerRange(buf, node)
      mark(row, sc, { end_col = ec, conceal = '' })
      return
    end
  end

  -- '- [~] text' and the like: hide the bullet, draw the state's icon over
  -- the '[' and conceal the rest of the box, as for real task items.
  local row, sc, ec = markerRange(buf, node)
  local box_col, state = lineText(buf, row):match('()%[([^%]])%]', ec + 1)
  if box_col == ec + 1 and extra_states[state] then
    -- The whole '[~]' is concealed *into* the icon. Treesitter reads '[~]' as
    -- a shortcut link and conceals its brackets itself; an overlay plus a
    -- partial conceal fought with that and swallowed the space after it.
    local icon, hl = unpack(extra_states[state])
    mark(row, sc, { end_col = ec, conceal = '' })
    mark(row, ec, { end_col = ec + 3, conceal = icon, hl_group = hl, priority = 300 })
    return
  end

  local depth = 0
  local parent = item:parent()
  while parent do
    if parent:type() == 'list' then depth = depth + 1 end
    parent = parent:parent()
  end
  local _, col = markerRange(buf, node)
  mark(row, col, {
    virt_text = { { bullets[(depth - 1) % #bullets + 1], 'PureMdBullet' } },
    virt_text_pos = 'overlay',
  })
end

--- The icon covers the '[' and the rest of the box (' ]' / 'x]') is concealed,
--- so the icon sits where the concealed bullet was, level with the bullets of
--- ordinary items. Padding the icon to the box's width instead left a gap.
local function task(buf, node, mark, state)
  local row, sc, _, ec = node:range()
  mark(row, sc, {
    virt_text = { { checkbox[state], state == 'checked' and 'PureMdTaskDone' or 'PureMdTaskTodo' } },
    virt_text_pos = 'overlay',
  })
  mark(row, sc + 1, { end_col = ec, conceal = '' })
  if state == 'checked' then
    -- Dim the item's text, from after the box to the end of the line.
    mark(row, ec, { end_col = #lineText(buf, row), hl_group = 'PureMdCheckedText' })
  end
end

function render.unchecked(buf, node, mark) task(buf, node, mark, 'unchecked') end
function render.checked(buf, node, mark) task(buf, node, mark, 'checked') end

--- Every '>' at the start of the quote's lines, nested ones included. The
--- markers after the first line are not separate nodes, so the lines are
--- scanned instead.
function render.quote(buf, node, mark)
  -- A nested quote is also captured on its own; the outermost one already
  -- scans its lines, so drawing again would stack a second set of bars.
  local parent = node:parent()
  while parent do
    if parent:type() == 'block_quote' then return end
    parent = parent:parent()
  end
  for row = node:start(), lastRow(node) do
    local text = lineText(buf, row)
    local col = 0
    while true do
      local s = text:find('^%s*>', col + 1)
      if not s then break end
      local gt = text:find('>', s, true)
      mark(row, gt - 1, { virt_text = { { '▋', 'PureMdQuote' } }, virt_text_pos = 'overlay' })
      col = gt
    end
  end
end

function render.rule(buf, node, mark)
  local row = node:start()
  local width = vim.api.nvim_win_get_width(0) - vim.fn.getwininfo(vim.api.nvim_get_current_win())[1].textoff
  mark(row, 0, { virt_text = { { string.rep('─', width), 'PureMdRule' } }, virt_text_pos = 'overlay' })
end

--- Pipes become │; the delimiter row (|---|:-:|) becomes ├───┼───┤.
function render.table(buf, node, mark)
  for row = node:start(), lastRow(node) do
    local text = lineText(buf, row)
    local is_delimiter = text:match('^%s*|?[%s:%-|]+$') and text:find('-', 1, true)
    if is_delimiter then
      -- Built from the original (all ASCII) characters: substituting in place
      -- would shift byte offsets, since ─ ├ ┼ ┤ are three bytes each.
      local indent = #text:match('^%s*')
      local first = text:find('|', 1, true)
      local last_pipe = #text - (text:reverse():find('|', 1, true) or 0) + 1
      local out = {}
      for pos = indent + 1, #text do
        local ch = text:sub(pos, pos)
        if ch == '|' then
          table.insert(out, pos == first and '├' or pos == last_pipe and '┤' or '┼')
        elseif ch:match('%s') then
          table.insert(out, ch)
        else
          table.insert(out, '─')
        end
      end
      mark(row, indent, { virt_text = { { table.concat(out), 'PureMdTable' } }, virt_text_pos = 'overlay' })
    else
      local col = 0
      while true do
        local p = text:find('|', col + 1, true)
        if not p then break end
        -- A '\|' is a literal pipe inside a cell, not a border.
        if text:sub(p - 1, p - 1) ~= '\\' then
          mark(row, p - 1, { virt_text = { { '│', 'PureMdTable' } }, virt_text_pos = 'overlay' })
        end
        col = p
      end
      -- Checkboxes in cells. Markdown has no task items inside tables, so
      -- treesitter sees plain text; match the [ ] / [x] literally instead.
      for pos, mark_char in text:gmatch('()%[([ xX])%]') do
        local state = mark_char == ' ' and 'unchecked' or 'checked'
        local icon = checkbox[state]
        mark(row, pos - 1, {
          virt_text = { { icon .. string.rep(' ', 3 - vim.fn.strdisplaywidth(icon)),
            state == 'checked' and 'PureMdTaskDone' or 'PureMdTaskTodo' } },
          virt_text_pos = 'overlay',
        })
      end
    end
  end
end

function render.code_span(buf, node, mark)
  local row, sc, erow, ec = node:range()
  if row ~= erow then return end
  mark(row, sc, { end_col = ec, hl_group = 'PureMdInlineCode' })
end

-- -----------------------------------------------------------------------------
--  Hidden lines: frontmatter and footnotes
-- -----------------------------------------------------------------------------
--  Found by text rather than by treesitter: the markdown parser does not know
--  footnotes, and Obsidian's rule for the frontmatter is simply "the file
--  starts with a --- line".

local superscript = { ['0'] = '⁰', ['1'] = '¹', ['2'] = '²', ['3'] = '³', ['4'] = '⁴',
  ['5'] = '⁵', ['6'] = '⁶', ['7'] = '⁷', ['8'] = '⁸', ['9'] = '⁹' }

--- True when (row, col) is inside a code block or `code`, where [^1] and
--- --- are just text.
local function inCode(buf, row, col)
  local ok, node = pcall(vim.treesitter.get_node, { bufnr = buf, pos = { row, col }, ignore_injections = false })
  while ok and node do
    local t = node:type()
    if t == 'fenced_code_block' or t == 'indented_code_block' or t == 'code_span' then return true end
    node = node:parent()
  end
  return false
end

--- Rows (0-based, inclusive) of the frontmatter, or nil.
local function frontmatter(buf)
  if lineText(buf, 0) ~= '---' then return nil end
  local lines = vim.api.nvim_buf_get_lines(buf, 1, 200, false)
  for i, l in ipairs(lines) do
    if l == '---' or l == '...' then return { 0, i } end
  end
end

--- { first, last } row ranges of footnote definitions between top and bottom:
--- the "[^id]: text" line plus the indented lines that continue it.
local function footnotes(buf, top, bottom)
  local ranges = {}
  local lines = vim.api.nvim_buf_get_lines(buf, top, bottom + 1, false)
  local i = 1
  while i <= #lines do
    local row = top + i - 1
    if lines[i]:match('^ ? ? ?%[%^[^%]]+%]:') and not inCode(buf, row, #lines[i]:match('^%s*')) then
      local last = i
      while lines[last + 1] and lines[last + 1]:match('^\t') or (lines[last + 1] or ''):match('^    %S') do
        last = last + 1
      end
      table.insert(ranges, { row, top + last - 1 })
      i = last + 1
    else
      i = i + 1
    end
  end
  return ranges
end

--- Hide the frontmatter and footnote definitions, except the one the cursor
--- is in, and draw footnote references as superscripts.
--- Returns the hidden-able ranges, so cursor moves can tell when to redraw.
local function hideLines(buf, top, bottom, mark, place)
  local cursor = vim.fn.line('.') - 1
  local ranges = footnotes(buf, top, bottom)
  local fm = frontmatter(buf)
  if fm then table.insert(ranges, 1, fm) end
  for _, name in ipairs({ 'pure.todoist', 'pure.calendar', 'pure.llm' }) do
    local ok, mod = pcall(require, name)
    if ok and mod.hiddenBlocks then vim.list_extend(ranges, mod.hiddenBlocks(buf)) end
  end

  for _, r in ipairs(ranges) do
    if cursor < r[1] or cursor > r[2] then
      for row = r[1], r[2] do
        place(row, 0, { conceal_lines = '' })
      end
    end
  end

  local lines = vim.api.nvim_buf_get_lines(buf, top, bottom + 1, false)
  for i, text in ipairs(lines) do
    local row = top + i - 1
    for start, id, stop in text:gmatch('()%[%^([^%]]+)%]()') do
      -- Not the label that opens a definition line, and not inside code.
      local is_definition = text:sub(stop, stop) == ':' and not text:sub(1, start - 1):match('%S')
      if not is_definition and not inCode(buf, row, start - 1) then
        local label = id:match('^%d+$') and id:gsub('%d', superscript) or ('^' .. id)
        mark(row, start - 1, {
          end_col = stop - 1,
          conceal = '',
          virt_text = { { label, 'PureMdFootnote' } },
          virt_text_pos = 'inline',
        })
      end
    end
  end
  return ranges
end

local embed_icons = { image = '\u{F02E9}', file = '\u{F0219}' } -- md-image, md-file_document
local image_ext = { png = true, jpg = true, jpeg = true, gif = true, svg = true, webp = true, bmp = true }

--- What Obsidian shows for the inside of a [[wikilink]]: the alias after
--- '|' if there is one, else the target, with '#' sections as ' > '.
local function wikilinkText(inner)
  local alias = inner:match('|(.*)$')
  if alias and alias ~= '' then return alias end
  local target = inner:gsub('|.*$', '')
  local note, rest = target:match('^([^#]*)#(.*)$')
  if not note then return target end
  -- [[#Section]] links inside the same note show just the section.
  local parts = vim.tbl_filter(function(p) return p ~= '' end, vim.split(rest, '#', { plain = true }))
  local shown = table.concat(parts, ' > ')
  return note ~= '' and (note .. ' > ' .. shown) or shown
end

--- The [[wikilink]] (with its '!') under byte column `col` of `text`, as
--- "start:stop" (1-based, stop exclusive), or ''.
local function linkAt(text, col)
  for start, stop in text:gmatch('()%[%[[^%[%]]-%]%]()') do
    if text:sub(start - 1, start - 1) == '!' then start = start - 1 end
    if col + 1 >= start and col + 1 < stop then return start .. ':' .. stop end
  end
  return ''
end

--- The link under the cursor, as a key that changes when the cursor enters
--- or leaves one.
local function cursorLink()
  local row, col = unpack(vim.api.nvim_win_get_cursor(0))
  local key = linkAt(vim.api.nvim_get_current_line(), col)
  return key ~= '' and (row .. ':' .. key) or ''
end

--- [[target|alias]] drawn as its text. Obsidian's own syntax, which the
--- markdown parser does not know (it already hides the URL of [text](url)).
--- The link under the cursor is left raw.
local function wikilinks(buf, top, bottom, mark)
  local lines = vim.api.nvim_buf_get_lines(buf, top, bottom + 1, false)
  local cursor_row, cursor_col = unpack(vim.api.nvim_win_get_cursor(0))
  for i, text in ipairs(lines) do
    local row = top + i - 1
    local raw = row == cursor_row - 1 and linkAt(text, cursor_col) or ''
    for start, inner, stop in text:gmatch('()%[%[([^%[%]]-)%]%]()') do
      local key = (text:sub(start - 1, start - 1) == '!' and start - 1 or start) .. ':' .. stop
      if inner ~= '' and key ~= raw and not inCode(buf, row, start - 1) then
        local shown = wikilinkText(inner)
        -- ![[...]] embeds a note or a file: the '!' becomes an icon.
        if text:sub(start - 1, start - 1) == '!' then
          start = start - 1
          local is_image = inner:gsub('|.*$', ''):lower():match('%.(%a+)$')
          is_image = is_image and image_ext[is_image]
          shown = (is_image and embed_icons.image or embed_icons.file) .. ' ' .. shown
        end
        mark(row, start - 1, {
          end_col = stop - 1,
          conceal = '',
          virt_text = { { shown, 'PureMdLink' } },
          virt_text_pos = 'inline',
        })
      end
    end
  end
end

--- The range of `ranges` holding row `row`, as "first:last", or ''.
local function rangeAt(ranges, row)
  for _, r in ipairs(ranges or {}) do
    if row >= r[1] and row <= r[2] then return r[1] .. ':' .. r[2] end
  end
  return ''
end

-- -----------------------------------------------------------------------------
--  Code fences
-- -----------------------------------------------------------------------------
--  Neovim's own markdown highlights hide the whole ```lang line
--  (conceal_lines), which also hid the language label render.code draws
--  there. Load the same query without that directive; the backticks and
--  the language name are still concealed, the line itself stays.
do
  local parts = {}
  for _, file in ipairs(vim.treesitter.query.get_files('markdown', 'highlights')) do
    local text = table.concat(vim.fn.readfile(file), '\n')
    table.insert(parts, (text:gsub('%(#set! conceal_lines ""%)', '')))
  end
  pcall(vim.treesitter.query.set, 'markdown', 'highlights', table.concat(parts, '\n'))
end

-- -----------------------------------------------------------------------------
--  Driver
-- -----------------------------------------------------------------------------

--- True when `buf` should show rendered markdown.
--- Scratch buffers (buftype set) are skipped unless they opt in with
--- vim.b.pure_mdview = true, as the Todoist task list does.
local function active(buf)
  return enabled and vim.bo[buf].filetype == 'markdown'
    and (vim.bo[buf].buftype == '' or vim.b[buf].pure_mdview == true)
end

-- Marks drawn per buffer: extmark id -> the key of what it draws.
local drawn = {}
-- What the last refresh saw per buffer, to skip one that would change nothing.
local last_state = {}

--- Make the buffer's marks `want` ({ row, col, opts, key }), touching only
--- what differs from what is drawn. Clearing and redrawing every mark made
--- Neovim redraw the whole window on every key typed, several times: the
--- render flickered while typing, most of all on Windows terminals.
---
--- With `rows` ({ first, last }), only the marks on those rows are looked at;
--- the others stay as they are.
local function reconcile(buf, want, rows)
  local have = drawn[buf] or {}
  local keep = {}
  local from, to = 0, -1
  if rows then from, to = { rows[1], 0 }, { rows[2], -1 } end
  for _, m in ipairs(vim.api.nvim_buf_get_extmarks(buf, ns, from, to, {})) do
    local id = m[1]
    -- Keyed by where the mark is now: edits move marks with the text.
    local key = have[id] and (m[2] .. ':' .. m[3] .. ':' .. have[id])
    if key and not keep[key] then
      keep[key] = id
    else
      vim.api.nvim_buf_del_extmark(buf, ns, id)
      have[id] = nil
    end
  end
  -- A partial pass keeps what is drawn elsewhere.
  local now = {}
  if rows then
    now = have
    for _, id in pairs(keep) do now[id] = nil end
  end
  for _, w in ipairs(want) do
    local key = w.row .. ':' .. w.col .. ':' .. w.key
    local id = keep[key]
    if id then
      keep[key] = nil
      now[id] = w.key
    else
      local ok, new_id = pcall(vim.api.nvim_buf_set_extmark, buf, ns, w.row, w.col, w.opts)
      if ok then now[new_id] = w.key end
    end
  end
  for _, id in pairs(keep) do vim.api.nvim_buf_del_extmark(buf, ns, id) end
  drawn[buf] = now
end

-- -----------------------------------------------------------------------------
--  What changed
-- -----------------------------------------------------------------------------
--  Typing changes one line. Redrawing the whole screen for it (even when
--  reconcile() ends up touching nothing) cost a parse, a scan of every
--  block and a pass over each visible line per key, and the screen showed
--  it. So each buffer's edits are followed as they happen: the rows edited
--  (nvim_buf_attach) and the rows where the syntax tree changed (the
--  parser's on_changedtree). When both stay on one line, only that line
--  is drawn again; while typing on the cursor line in insert mode, which is
--  shown raw anyway, nothing is.

-- buf -> { first, last (0-based rows), shifted (lines added or removed),
--          tree_first, tree_last (rows where the syntax tree changed) }
local dirty = {}
local attached = {}  -- buf -> the parser the tree callback is on

local function note(buf, first, last)
  local d = dirty[buf]
  if not d then
    dirty[buf] = { first = first, last = last }
  else
    d.first, d.last = math.min(d.first, first), math.max(d.last, last)
  end
  return dirty[buf]
end

local function follow(buf, parser)
  if attached[buf] == parser then return end
  if attached[buf] == nil then
    vim.api.nvim_buf_attach(buf, false, {
      on_lines = function(_, b, _, first, last_old, last_new)
        local d = note(b, first, math.max(first, math.max(last_old, last_new) - 1))
        if last_old ~= last_new then d.shifted = true end
      end,
      on_reload = function(_, b) note(b, 0, 0).shifted = true end,
      on_detach = function(_, b) attached[b], dirty[b] = nil, nil end,
    })
  end
  attached[buf] = parser
  parser:register_cbs({
    on_changedtree = function(ranges)
      if attached[buf] ~= parser then return end
      local d = dirty[buf] or note(buf, math.huge, -1)
      for _, r in ipairs(ranges) do
        local sr, er = r[1], (#r == 6 and r[4] or r[3])
        d.tree_first = math.min(d.tree_first or sr, sr)
        d.tree_last = math.max(d.tree_last or er, er)
      end
    end,
  }, true)
end

-- A line that can change how other lines read: a code fence, a thematic
-- break or frontmatter fence, an HTML comment (the markers of the Todoist,
-- calendar and Claude blocks), a footnote definition.
local function structural(text)
  return text:match('^%s*```') or text:match('^%s*~~~') or text:match('^%-%-%-')
    or text:find('<!--', 1, true) or text:match('^ ? ? ?%[%^')
end

--- The one row the last edits touched, when they can be drawn alone; nil
--- when the screen has to be drawn again.
local function editedRow(buf, prev, now)
  local d = dirty[buf]
  if not (d and prev and now) or d.shifted or d.first ~= d.last then return nil end
  -- Anything but the text and the cursor column changed: view, mode, size.
  if prev.row ~= now.row or prev.view ~= now.view then return nil end
  if d.tree_first and (d.tree_first < d.first or d.tree_last > d.last) then return nil end
  if structural(lineText(buf, d.first)) then return nil end
  return d.first
end

--- Redraw the visible part of the current window's buffer. Skipped when
--- nothing it depends on changed since the last time (text, cursor, view,
--- mode): typing one key fires three or four events. `force` redraws anyway.
function M.refresh(force)
  local buf = vim.api.nvim_get_current_buf()
  if not active(buf) then
    vim.api.nvim_buf_clear_namespace(buf, ns, 0, -1)
    drawn[buf], last_state[buf], dirty[buf] = nil, nil, nil
    return
  end
  local cursor = vim.api.nvim_win_get_cursor(0)
  local mode = vim.fn.mode()
  local view = table.concat({ vim.fn.line('w0'), vim.fn.line('w$'), vim.api.nvim_win_get_width(0), mode }, ':')
  local state = { key = table.concat({ vim.b[buf].changedtick, cursor[1], cursor[2], view }, ':'),
    row = cursor[1], view = view }
  local prev = last_state[buf]
  if not force and prev and prev.key == state.key then return end
  last_state[buf] = state

  local ok, parser = pcall(vim.treesitter.get_parser, buf, 'markdown')
  if not ok or not parser then return end
  follow(buf, parser)

  -- Only the rows on screen, plus a margin so short scrolls look finished.
  local top = math.max(vim.fn.line('w0') - 1 - 20, 0)
  local bottom = vim.fn.line('w$') + 20
  parser:parse({ top, bottom })

  -- The cursor line is left raw while editing it.
  local raw_row = (mode:match('^[iRvV\22]')) and (cursor[1] - 1) or -1

  -- One line edited: draw that line only (nothing, if it is the raw one).
  local row = not force and editedRow(buf, prev, state)
  dirty[buf] = nil
  local partial = row ~= nil and row ~= false
  if partial then
    if row == raw_row then return end
    top, bottom = row, row
  end

  local want = {}
  -- Every mark goes through here; reconcile() below applies them.
  local function place(row_, col, opts)
    if partial and (row_ < top or row_ > bottom) then return end
    opts.priority = opts.priority or 200
    table.insert(want, { row = row_, col = col, opts = opts, key = vim.inspect(opts, { newline = '', indent = '' }) })
  end
  local function mark(row, col, opts)
    if row == raw_row or row < top or row > bottom then return end
    place(row, col, opts)
  end

  parser:for_each_tree(function(tree, ltree)
    local lang = ltree:lang()
    local query = lang == 'markdown' and block_query or lang == 'markdown_inline' and inline_query
    if not query then return end
    for id, node in query:iter_captures(tree:root(), buf, top, bottom + 1) do
      local fn = render[query.captures[id]]
      if fn then fn(buf, node, mark) end
    end
  end)

  local ranges = hideLines(buf, top, bottom, mark, place)
  wikilinks(buf, top, bottom, mark)
  reconcile(buf, want, partial and { top, bottom } or nil)
  if partial then return end
  vim.b[buf].pure_md_hidden = ranges
  vim.b[buf].pure_md_revealed = rangeAt(ranges, vim.fn.line('.') - 1)
  vim.b[buf].pure_md_link = cursorLink()
end

function M.toggle()
  enabled = not enabled
  M.refresh()
  vim.notify('Markdown rendering ' .. (enabled and 'on' or 'off'))
end

local group = vim.api.nvim_create_augroup('PureMdview', { clear = true })

vim.api.nvim_create_autocmd(
  { 'BufWinEnter', 'WinScrolled', 'TextChanged', 'TextChangedI', 'CursorMoved', 'CursorMovedI', 'ModeChanged', 'WinResized' }, {
    group = group,
    callback = function(args)
      if vim.bo[args.buf].filetype ~= 'markdown' then return end
      -- In normal mode the render does not depend on the cursor, so plain
      -- movement needs no redraw -- unless it enters or leaves a hidden block
      -- (frontmatter, footnote). In visual mode the raw line follows it.
      if args.event == 'CursorMoved' and vim.fn.mode() == 'n'
        and rangeAt(vim.b[args.buf].pure_md_hidden, vim.fn.line('.') - 1) == vim.b[args.buf].pure_md_revealed
        and cursorLink() == vim.b[args.buf].pure_md_link then
        return
      end
      -- A note opens on its first line, which would reveal the frontmatter:
      -- start just below it instead, as Obsidian does.
      if args.event == 'BufWinEnter' and vim.fn.line('.') == 1 and active(args.buf) then
        local fm = frontmatter(args.buf)
        if fm then pcall(vim.api.nvim_win_set_cursor, 0, { math.min(fm[2] + 2, vim.fn.line('$')), 0 }) end
      end
      M.refresh()
    end,
  })

-- Scheduled so it runs after render-md.lua's FileType handler, which assigns
-- the per-level heading colours the bands are computed from.
vim.api.nvim_create_autocmd('FileType', {
  group = group,
  pattern = 'markdown',
  callback = function() vim.schedule(function() setHighlights(); M.refresh(true) end) end,
})
vim.api.nvim_create_autocmd('ColorScheme', { group = group, callback = setHighlights })
setHighlights()

return M

end

-- lua/pure/notes.lua
package.preload["pure.notes"] = function(...)
-- =============================================================================
--  Notes
-- =============================================================================
--  The part of obsidian.nvim this configuration used, in the vault of
--  pure/zettelkasten.lua, with links Obsidian reads the same way:
--
--    <CR>, K      on a link: follow it ([[Note]], [[Note#Heading]],
--                 [[Note#^block]], [[Note|alias]], ![[embed]],
--                 [text](Note.md), https://...). A note that does not exist
--                 yet is created (asked first), where Obsidian would put it.
--                 On a checkbox: toggle it. On a heading: fold it. Inside a
--                 ```todoist block: open its tasks.
--    [[           lists the vault's notes as you type; after [[Note# its
--                 headings.
--    <leader>nr   rename the note, and fix every link to it (wikilinks,
--                 markdown links, canvases).
--    <leader>fl   the notes that link to this one (backlinks).
--
--  Moving or renaming notes in oil fixes the links too.
--
--  Works in any markdown buffer (the Todoist list too); links resolve in the
--  vault. Obsidian's rules: case does not matter, [[Note]] is any Note.md
--  in the vault (the one in the same folder first, else the shortest path),
--  [[folder/Note]] a path, and a file that is not markdown keeps its
--  extension ([[photo.png]]). New notes go where Obsidian's own setting says
--  (Settings > Files and links > Default location for new notes, read from
--  .obsidian/app.json): the vault root, the current note's folder, or a
--  given folder.
-- =============================================================================

local M = {}

local function zet() return require('pure.zettelkasten') end

local function vault()
  local ok, root = pcall(function() return zet().vaultPath() end)
  if not ok or not root or vim.fn.isdirectory(root) == 0 then return nil end
  return (vim.fs.normalize(root):gsub('/$', ''))
end

--- Obsidian ignores case in links (and so do Windows and macOS file names).
local function lower(s) return vim.fn.tolower(s) end

--- `path` relative to `root`, or nil when it is not inside it.
local function relTo(root, path)
  path = vim.fs.normalize(path)
  local r, p = lower(root) .. '/', lower(path)
  if p:sub(1, #r) ~= r then return nil end
  return path:sub(#r + 1)
end

--- Files of the vault used lately, as { [lowercased rel path] = rank },
--- 0 the most recent: the open buffers (last used first), then Neovim's
--- recent files (v:oldfiles). Not the current buffer: a note rarely links to
--- itself. Asked for in Improvment.md, so [[ offers what she was just
--- working on first; see RECENT_BONUS for how much that weighs once
--- something is typed.
local RECENT_BONUS = 40 -- added to the fuzzy score of the most recent match
local function recentRanks(root)
  local ranks, n = {}, 0
  local current = vim.api.nvim_get_current_buf()
  local function add(path)
    local rel = path ~= '' and relTo(root, path)
    if rel and ranks[lower(rel)] == nil and n < 30 then
      ranks[lower(rel)] = n
      n = n + 1
    end
  end
  local bufs = vim.tbl_filter(function(b) return b.bufnr ~= current end, vim.fn.getbufinfo({ buflisted = 1 }))
  table.sort(bufs, function(a, b) return a.lastused > b.lastused end)
  for _, b in ipairs(bufs) do add(b.name) end
  local here = vim.api.nvim_buf_get_name(current)
  for _, f in ipairs(vim.v.oldfiles or {}) do
    if vim.fs.normalize(f) ~= vim.fs.normalize(here) then add(f) end
  end
  return ranks
end

--- a/b/../c -> a/c, ./x -> x.
local function collapse(path)
  local out = {}
  for part in path:gmatch('[^/]+') do
    if part == '..' then
      if #out == 0 then return nil end
      table.remove(out)
    elseif part ~= '.' then
      table.insert(out, part)
    end
  end
  return table.concat(out, '/')
end

local function dirOf(rel)
  return rel:match('^(.*)/[^/]*$') or ''
end

local function stemOf(rel)
  local base = rel:match('[^/]*$')
  return (base:gsub('%.md$', ''))
end

-- -----------------------------------------------------------------------------
--  The vault's files
-- -----------------------------------------------------------------------------
--  Every file of the vault (not the hidden folders: .obsidian, .trash), as
--  paths relative to it. Listed again when older than a few seconds, or
--  after a note is written, created or renamed here.

local cache = { time = 0 }

--- An index of `files` (relative paths): by path and by link name.
local function indexOf(files)
  local idx = { files = files, by_path = {}, by_name = {} }
  for _, f in ipairs(files) do
    idx.by_path[lower(f)] = f
    -- Markdown notes are linked without ".md"; other files with their
    -- extension.
    local name = lower(f:match('[^/]*$'))
    for _, n in ipairs(f:match('%.md$') and { (name:gsub('%.md$', '')), name } or { name }) do
      idx.by_name[n] = idx.by_name[n] or {}
      table.insert(idx.by_name[n], f)
    end
  end
  return idx
end

--- Every file of the vault. --no-ignore-vcs (also in the rename and
--- backlinks searches below): the vault's .gitignore lists the private
--- folder, which is kept out of git, not out of the vault. Without it its
--- notes were missing from [[ completion, link resolution and backlinks.
--- Hidden folders (.obsidian, .trash) are still skipped.
local function listFiles(root)
  if vim.fn.executable('rg') == 1 then
    local res = vim.system({ 'rg', '--files', '--no-ignore-vcs', '--path-separator', '/' }, { cwd = root, text = true }):wait()
    if res.code == 0 or (res.stdout or '') ~= '' then
      return vim.split(vim.trim(res.stdout or ''), '\n', { trimempty = true })
    end
  end
  local files = {}
  for name, kind in vim.fs.dir(root, {
    depth = 20,
    skip = function(dir) return not dir:match('^%.') and not dir:match('/%.') end,
  }) do
    if kind == 'file' and not name:match('^%.') then table.insert(files, name) end
  end
  return files
end

--- The index of the vault's files now; nil without a vault.
function M.index(force)
  local root = vault()
  if not root then return nil end
  if force or cache.root ~= root or vim.uv.now() - cache.time > 5000 then
    cache = { root = root, time = vim.uv.now(), idx = indexOf(listFiles(root)) }
  end
  return cache.idx, root
end

local function invalidate() cache.time = 0 end

-- -----------------------------------------------------------------------------
--  Links
-- -----------------------------------------------------------------------------

--- Undo the %20 and friends of a markdown link's destination.
local function urldecode(s)
  return (s:gsub('%%(%x%x)', function(h) return string.char(tonumber(h, 16)) end))
end

--- Split the inside of a link into its parts: "Note#Head|Alias" ->
--- target "Note", sub "Head" (or "^block"), alias "Alias".
local function splitInner(inner)
  local target, alias = inner:match('^(.-)|(.*)$')
  target = target or inner
  local path, sub = target:match('^(.-)#(.*)$')
  return { target = vim.trim(path or target), sub = sub, alias = alias }
end

--- Every link on `line`: { kind = 'wiki' | 'md' | 'url', s, e (1-based,
--- inclusive), inner (wiki: inside the brackets; md: the destination) }.
local function linksIn(line)
  local out = {}
  for s, bang, inner, e in line:gmatch('()(!?)%[%[([^%[%]]-)%]%]()') do
    table.insert(out, { kind = 'wiki', s = s, e = e - 1, inner = inner, embed = bang == '!' })
  end
  for s, dest, e in line:gmatch('()%[[^%]]*%]%(([^%)]*)%)()') do
    local inside = false
    for _, w in ipairs(out) do
      if s >= w.s and s <= w.e then inside = true end
    end
    if not inside then
      dest = vim.trim(dest)
      local angle = dest:match('^<(.*)>$')
      dest = angle or dest
      local kind = dest:match('^%a[%w+.-]*:') and 'url' or 'md'
      table.insert(out, { kind = kind, s = s, e = e - 1, inner = dest, angle = angle ~= nil })
    end
  end
  for s, url, e in line:gmatch('()(https?://[^%s%)%]>]+)()') do
    local inside = false
    for _, l in ipairs(out) do
      if s >= l.s and s <= l.e then inside = true end
    end
    if not inside then table.insert(out, { kind = 'url', s = s, e = e - 1, inner = url }) end
  end
  table.sort(out, function(a, b) return a.s < b.s end)
  return out
end
M._linksIn = linksIn

--- The link under the cursor, or nil.
local function linkAtCursor()
  local line = vim.api.nvim_get_current_line()
  local col = vim.api.nvim_win_get_cursor(0)[2] + 1
  for _, l in ipairs(linksIn(line)) do
    if col >= l.s and col <= l.e then return l end
  end
end

--- Resolve a link target (as written, decoded) found in the note `from`
--- (relative path, or nil outside the vault) to a relative path of `idx`.
local function resolve(idx, target, from)
  if not idx or target == '' then return nil end
  target = target:gsub('\\', '/'):gsub('^/+', '')
  local t = lower(target)
  local function exists(p)
    p = p and lower(p)
    return p and (idx.by_path[p] or idx.by_path[p .. '.md'])
  end
  -- A path from the vault's root, then from the note's own folder.
  local hit = exists(t)
  if hit then return hit end
  if from then
    local rel = collapse(dirOf(from) .. '/' .. target)
    hit = rel and exists(rel)
    if hit then return hit end
  end
  -- Any file with that name ([[Note]]), or ending in that path
  -- ([[folder/Note]]).
  local name = t:match('[^/]*$')
  local found = {}
  for _, f in ipairs(idx.by_name[name] or idx.by_name[name:gsub('%.md$', '')] or {}) do
    local lf = lower(f)
    if not t:find('/', 1, true) or lf:sub(-#t - 1) == '/' .. t or lf:sub(-#t - 4) == '/' .. t .. '.md' then
      table.insert(found, f)
    end
  end
  if #found <= 1 then return found[1] end
  local here = from and lower(dirOf(from))
  table.sort(found, function(a, b)
    local ah, bh = lower(dirOf(a)) == here, lower(dirOf(b)) == here
    if ah ~= bh then return ah end
    if #a ~= #b then return #a < #b end
    return a < b
  end)
  return found[1]
end
M._resolve = function(files, target, from) return resolve(indexOf(files), target, from) end

--- The note name a link should use for `rel`: the bare name when no other
--- file has it, else the path; without ".md".
local function linkName(idx, rel)
  local stem = stemOf(rel)
  local key = rel:match('%.md$') and lower(stem) or lower(rel:match('[^/]*$'))
  local same = idx.by_name[key] or {}
  local name = rel:match('%.md$') and stem or rel:match('[^/]*$')
  if #same <= 1 then return name end
  return (rel:gsub('%.md$', ''))
end

--- The link text for `rel` seen from the note `from`: the bare name when
--- that already leads to it (Obsidian's rules above), else the path.
local function shortest(idx, rel, from)
  local name = rel:match('%.md$') and stemOf(rel) or rel:match('[^/]*$')
  if resolve(idx, name, from) == rel then return name end
  return (rel:gsub('%.md$', ''))
end

-- -----------------------------------------------------------------------------
--  Following links
-- -----------------------------------------------------------------------------

--- Heading text as a link names it: case, spaces and punctuation aside.
local function slug(s)
  return lower(s):gsub('[%p%s]+', ' '):gsub('^ ', ''):gsub(' $', '')
end

--- Put the cursor on `sub` (a heading, or ^block) of the current buffer.
local function jumpTo(sub)
  if not sub or sub == '' then return end
  local lines = vim.api.nvim_buf_get_lines(0, 0, -1, false)
  local block = sub:match('^%^(.+)$')
  -- [[Note#A#B]]: the last heading is the one to go to.
  local want = not block and slug(sub:match('([^#]*)$'))
  for i, l in ipairs(lines) do
    local hit
    if block then
      hit = l:match('%^' .. vim.pesc(block) .. '%s*$')
    else
      local text = l:match('^#+%s+(.-)%s*#*%s*$')
      hit = text and slug(text) == want
    end
    if hit then
      vim.api.nvim_win_set_cursor(0, { i, 0 })
      vim.cmd('normal! zvzz')
      return
    end
  end
  vim.notify('No ' .. (block and ('block ^' .. block) or ('heading "' .. sub .. '"')) .. ' in this note',
    vim.log.levels.WARN)
end

--- Obsidian's setting for where new notes go: the folder, relative to the
--- vault ('' is the root). `from` is the note the link is in.
local function newNoteFolder(root, from)
  local ok, conf = pcall(function()
    return vim.json.decode(table.concat(vim.fn.readfile(root .. '/.obsidian/app.json'), '\n'))
  end)
  conf = ok and type(conf) == 'table' and conf or {}
  if conf.newFileLocation == 'current' and from then return dirOf(from) end
  if conf.newFileLocation == 'folder' and type(conf.newFileFolderPath) == 'string' then
    return (conf.newFileFolderPath:gsub('^/+', ''):gsub('/+$', ''))
  end
  return ''
end

local function openFile(path)
  if path:match('%.md$') or not path:match('[^/]%.%w+$') then
    vim.cmd('edit ' .. vim.fn.fnameescape(path))
  else
    -- Pictures, PDFs, canvases...: the system's own program.
    vim.ui.open(path)
  end
end

--- Folders of the vault under `arglead`, for the "In another folder" prompt.
--- Hidden ones (.obsidian, .trash, .git) are left out.
function M._folders(arglead)
  local root = vault()
  if not root then return {} end
  arglead = (arglead or ''):gsub('\\', '/'):lower()
  local out = {}
  for name, kind in vim.fs.dir(root, {
    depth = 8,
    skip = function(dir) return not vim.fs.basename(dir):match('^%.') end,
  }) do
    if kind == 'directory' and not vim.fs.basename(name):match('^%.')
        and name:lower():sub(1, #arglead) == arglead then
      table.insert(out, name .. '/')
    end
  end
  table.sort(out)
  return out
end

--- Ask for a folder of the vault, starting from the current note's own.
--- nil when cancelled, empty, or pointing outside the vault.
local function askFolder(from)
  local here = from and dirOf(from) or ''
  local ok, input = pcall(vim.fn.input, {
    prompt = 'Folder: ',
    default = here ~= '' and (here .. '/') or '',
    completion = "customlist,v:lua.require'pure.notes'._folders",
  })
  input = ok and vim.trim((input or ''):gsub('\\', '/')) or ''
  input = input:gsub('^/+', ''):gsub('/+$', '')
  if input == '' then return nil end
  for step in input:gmatch('[^/]+') do
    if step == '.' or step == '..' then
      vim.notify('Not a folder inside the vault: ' .. input, vim.log.levels.WARN)
      return nil
    end
  end
  return input
end

--- Create the note a link names, after asking; then open it.
---
---   Yes                in the folder for new notes (Obsidian's setting), or
---                      the one the link names ([[Projects/New]])
---   With a template    the same, then the template is applied as <leader>nt
---                      applies it, moves included: the Project template
---                      sends the note to 1-Projects/<title>/
---   In another folder  asks which (made if missing)
---   Cancel             nothing
---
--- With a template the note is made only once one is picked, so cancelling
--- the pick leaves no empty note behind.
local function create(root, link, from)
  local target = link.target
  local folder, title = target:match('^(.*)/([^/]*)$')
  if not folder then folder, title = newNoteFolder(root, from), target end
  title = title:gsub('%.md$', '')
  local choice = vim.fn.confirm(('Create the note "%s"?'):format(title),
    '&Yes\nWith a &template\nIn another &folder\n&Cancel', 1)

  local function make(rel)
    local dir = root .. (rel ~= '' and ('/' .. rel) or '')
    vim.fn.mkdir(dir, 'p')
    local path = dir .. '/' .. zet().noteId(title, dir) .. '.md'
    vim.fn.writefile({}, path)
    invalidate()
    vim.cmd('edit ' .. vim.fn.fnameescape(path))
  end

  if choice == 1 then
    make(folder)
  elseif choice == 2 then
    zet().pickTemplate(function(selected)
      if not selected then return end
      make(folder)
      zet().applyTemplate(selected)
      invalidate() -- the template may have moved it
    end)
  elseif choice == 3 then
    local chosen = askFolder(from)
    if chosen then make(chosen) end
  end
end

--- Follow the link under the cursor. False when there is none.
--- `urls_only`: only web links (for code, where [[x]] is not a note).
function M.follow(urls_only)
  local link = linkAtCursor()
  if not link or (urls_only and link.kind ~= 'url') then return false end
  if link.kind == 'url' then
    vim.ui.open(link.inner)
    return true
  end

  local parts = link.kind == 'wiki' and splitInner(link.inner) or splitInner(urldecode(link.inner))
  local idx, root = M.index()
  local here = vim.api.nvim_buf_get_name(0)
  local from = root and here ~= '' and relTo(root, here) or nil

  -- [[#Heading]]: in this same note.
  if parts.target == '' then
    jumpTo(parts.sub)
    return true
  end

  -- A markdown link relative to a file outside the vault.
  if link.kind == 'md' and not from and here ~= '' then
    local p = vim.fs.normalize(vim.fs.dirname(here) .. '/' .. parts.target)
    for _, c in ipairs({ p, p .. '.md' }) do
      if vim.uv.fs_stat(c) then
        openFile(c)
        jumpTo(parts.sub)
        return true
      end
    end
  end

  if not root then
    vim.notify('No vault set: run :ZettelVault', vim.log.levels.WARN)
    return true
  end
  local rel = resolve(idx, parts.target, from) or resolve(M.index(true), parts.target, from)
  if not rel then
    create(root, parts, from)
    return true
  end
  vim.cmd("normal! m'")
  openFile(root .. '/' .. rel)
  if rel:match('%.md$') then jumpTo(parts.sub) end
  return true
end

--- <CR> in markdown: follow a link, open a ```todoist block, toggle a
--- checkbox, fold a heading; else a plain <CR>.
function M.enter()
  local ok, todoist = pcall(require, 'pure.todoist')
  if ok and todoist.openBlock and todoist.openBlock() then return end
  if M.follow() then return end
  local line = vim.api.nvim_get_current_line()
  if line:match('^%s*[-*+]%s+%[.%]') then
    return require('configs.functions').toggleCheckbox()
  end
  if line:match('^#+%s') and vim.fn.foldlevel('.') > 0 then
    return vim.cmd('normal! za')
  end
  vim.api.nvim_feedkeys(vim.keycode('<CR>'), 'n', false)
end

-- -----------------------------------------------------------------------------
--  Completion after [[
-- -----------------------------------------------------------------------------
--  An 'omnifunc', which the 'autocomplete' of this configuration already
--  asks as you type (the 'o' in 'complete'). Outside a [[link it hands the
--  question to the buffer's language server, when there is one.

local pending -- what findstart saw, for the second call

function M.omnifunc(findstart, base)
  if findstart == 1 then
    pending = nil
    local line = vim.api.nvim_get_current_line()
    local col = vim.api.nvim_win_get_cursor(0)[2]
    local before, after = line:sub(1, col), line:sub(col + 1)
    local start, typed = before:match('.*()%[%[([^%[%]]*)$')
    if start and not typed:find('|', 1, true) then
      local closes = after:match('^%]%]') ~= nil
      local note, head = typed:match('^(.-)#([^#]*)$')
      if note then
        pending = { kind = 'heading', note = note, closes = closes }
        return col - #head
      end
      pending = { kind = 'note', closes = closes }
      return start + 1 -- 0-based column right after [[
    end
    if #vim.lsp.get_clients({ bufnr = 0, method = 'textDocument/completion' }) > 0 then
      pending = { kind = 'lsp' }
      return vim.lsp.omnifunc(findstart, base)
    end
    return -3
  end

  local p = pending or {}
  if p.kind == 'lsp' then return vim.lsp.omnifunc(findstart, base) end
  local idx, root = M.index()
  if not idx then return {} end
  local close = p.closes and '' or ']]'
  local items = {}

  if p.kind == 'heading' then
    local here = vim.api.nvim_buf_get_name(0)
    local from = here ~= '' and relTo(root, here) or nil
    local rel = p.note == '' and from or resolve(idx, p.note, from)
    if not rel then return {} end
    local path = root .. '/' .. rel
    local bufnr = vim.fn.bufnr(path)
    local lines = bufnr > 0 and vim.api.nvim_buf_is_loaded(bufnr)
      and vim.api.nvim_buf_get_lines(bufnr, 0, -1, false) or vim.fn.readfile(path)
    local heads = {}
    for _, l in ipairs(lines) do
      local text = l:match('^#+%s+(.-)%s*#*%s*$')
      if text and text ~= '' then table.insert(heads, text) end
    end
    if base ~= '' then heads = vim.fn.matchfuzzy(heads, base) end
    for _, h in ipairs(heads) do
      table.insert(items, { word = h .. close, abbr = h, menu = '#', equal = 1 })
    end
    return items
  end

  -- Improved for Improvment.md in the vault ("the [[links]] and folders
  -- completion"). It only offered notes by name, so:
  --   [[3-Zett/         a path: the folders and files inside that folder,
  --                     matched by what follows the last '/'
  --   [[zett            folders match too ("3-Zettelkasten/", no ]]: you
  --                     keep typing into it)
  --   ![[photo  [[doc   attachments (images, PDFs...) as well, after the
  --                     notes, with their extension, as Obsidian links them
  -- Each item says what it is in the menu's kind column: note, folder, file.
  local function isNote(f) return f:match('%.md$') or f:match('%.canvas$') end

  local folders, seen_dir = {}, {}
  for _, f in ipairs(idx.files) do
    local d = dirOf(f)
    while d ~= '' and not seen_dir[d] do
      seen_dir[d] = true
      table.insert(folders, d)
      d = dirOf(d)
    end
  end

  local dir_typed, rest = base:match('^(.*)/([^/]*)$')
  if dir_typed then
    -- By path: what sits directly in the typed folder (case-blind, as
    -- Obsidian resolves links).
    local want = lower(dir_typed)
    local cands, info = {}, {}
    for _, d in ipairs(folders) do
      if lower(dirOf(d)) == want then
        local label = d:match('[^/]*$') .. '/'
        table.insert(cands, label)
        info[label] = { word = d .. '/', kind = 'folder' }
      end
    end
    for _, f in ipairs(idx.files) do
      if lower(dirOf(f)) == want then
        local label = f:match('[^/]*$')
        local link = isNote(f) and f:match('%.md$') and (f:gsub('%.md$', '')) or f
        if isNote(f) then label = label:gsub('%.md$', '') end
        table.insert(cands, label)
        info[label] = { word = link .. close, kind = isNote(f) and 'note' or 'file' }
      end
    end
    cands = rest ~= '' and vim.fn.matchfuzzy(cands, rest) or cands
    if rest == '' then table.sort(cands) end
    for i, label in ipairs(cands) do
      if i > 200 then break end
      local it = info[label]
      table.insert(items, { word = it.word, abbr = label, kind = it.kind, menu = dir_typed, equal = 1 })
    end
    return items
  end

  -- By name: notes first, then folders, then other files.
  local groups = { note = {}, folder = {}, file = {} }
  local by = {}
  local recent = recentRanks(root)
  for _, f in ipairs(idx.files) do
    local kind = isNote(f) and 'note' or 'file'
    local name = linkName(idx, f)
    if not by[name] then
      by[name] = { word = name .. close, kind = kind, dir = dirOf(f), rank = recent[lower(f)] }
      table.insert(groups[kind], name)
    end
  end
  for _, d in ipairs(folders) do
    local name = d .. '/'
    if not by[name] then
      by[name] = { word = name, kind = 'folder', dir = dirOf(d) }
      table.insert(groups.folder, name)
    end
  end
  for _, kind in ipairs({ 'note', 'folder', 'file' }) do
    local names = groups[kind]
    if base ~= '' then
      -- What you type decides: only matches are listed. Among them, the
      -- recent ones go up by a bonus smaller than a clearly better match.
      local found = vim.fn.matchfuzzypos(names, base)
      local score = {}
      for i, name in ipairs(found[1]) do
        local rank = by[name].rank
        score[name] = found[3][i] + (rank and math.max(RECENT_BONUS - rank * 2, 0) or 0)
      end
      names = found[1]
      table.sort(names, function(a, b)
        if score[a] ~= score[b] then return score[a] > score[b] end
        return a < b
      end)
    else
      -- Nothing typed yet: the open buffers and recent files first.
      table.sort(names, function(a, b)
        local ra, rb = by[a].rank or math.huge, by[b].rank or math.huge
        if ra ~= rb then return ra < rb end
        return a < b
      end)
    end
    for _, name in ipairs(names) do
      if #items >= 200 then break end
      local it = by[name]
      local where = it.dir ~= '' and it.dir or '/'
      table.insert(items, { word = it.word, abbr = name, kind = it.kind,
        menu = it.rank and ('󰋚 ' .. where) or where, equal = 1 })
    end
  end
  return items
end

-- -----------------------------------------------------------------------------
--  Fixing links after notes move
-- -----------------------------------------------------------------------------
--  `moves`: { { old = rel, new = rel } }, files already moved. Every link
--  that pointed to an old path is rewritten to the new one, in the style it
--  was written in:
--    [[Note]]           the new name ([[folder/New]] if another file has it)
--    [[folder/Note]]    the new path
--    [x](folder/Note.md), [x](../Note.md)   the new path, from the vault's
--                       root or relative, as it was; spaces as %20 if so
--  plus the relative markdown links inside the moved notes themselves, and
--  the file cards of canvases ("file": "folder/Note.md").

local function urlencodeSpaces(s) return (s:gsub(' ', '%%20')) end

--- A relative path from folder `from_dir` to `to` (both vault-relative).
local function relative(from_dir, to)
  local a = from_dir == '' and {} or vim.split(from_dir, '/', { plain = true })
  local b = vim.split(to, '/', { plain = true })
  local i = 1
  while i <= #a and i < #b and lower(a[i]) == lower(b[i]) do i = i + 1 end
  local parts = {}
  for _ = i, #a do table.insert(parts, '..') end
  for k = i, #b do table.insert(parts, b[k]) end
  return table.concat(parts, '/')
end

--- The new text of one link, or nil to leave it.
--- `before`/`after`: indexes of the vault before and after the moves;
--- `src_old`/`src_new`: where the note holding the link was and is.
local function rewrite(link, before, after, moved, src_old, src_new)
  if link.kind == 'url' then return nil end
  local raw = link.kind == 'wiki' and link.inner or urldecode(link.inner)
  local parts = splitInner(raw)
  if parts.target == '' then return nil end
  local old_target = resolve(before, parts.target, src_old)
  if not old_target then return nil end
  local new_target = moved[old_target] or old_target
  local src_moved = src_old ~= src_new
  if new_target == old_target and not (src_moved and link.kind == 'md') then return nil end

  local tail = (parts.sub and ('#' .. parts.sub) or '')
  if link.kind == 'wiki' then
    if new_target == old_target then return nil end
    local keep_ext = parts.target:lower():match('%.md$')
    local text
    if parts.target:find('/', 1, true) then
      text = keep_ext and new_target or (new_target:gsub('%.md$', ''))
    else
      text = shortest(after, new_target, src_new)
      if keep_ext and not text:match('%.md$') then text = text .. '.md' end
    end
    return (link.embed and '!' or '') .. '[[' .. text .. tail .. (parts.alias and ('|' .. parts.alias) or '') .. ']]'
  end

  -- A markdown link: keep its form (from the root, relative, bare name).
  local dest = parts.target
  local had_ext = dest:lower():match('%.md$') or not new_target:match('%.md$')
  local target_text = had_ext and new_target or (new_target:gsub('%.md$', ''))
  local function known(p)
    p = p and lower(p)
    return p and (before.by_path[p] or before.by_path[p .. '.md'])
  end
  local new_dest
  if not dest:match('^%.') and known(dest) then
    new_dest = target_text                                  -- from the root
  elseif known(collapse(dirOf(src_old or '') .. '/' .. dest)) then
    new_dest = relative(dirOf(src_new or ''), target_text)  -- relative
    if dest:match('^%./') and not new_dest:match('^%.') then new_dest = './' .. new_dest end
  else
    new_dest = shortest(after, new_target, src_new)         -- a bare name
    if had_ext and new_target:match('%.md$') and not new_dest:match('%.md$') then new_dest = new_dest .. '.md' end
  end
  if new_dest == dest then return nil end
  if link.angle then
    new_dest = '<' .. new_dest .. '>'
  else
    -- Spaces break a markdown link unless written as %20.
    new_dest = urlencodeSpaces(new_dest)
  end
  -- Only the destination changes: [label](new).
  local line_link = link.text
  return (line_link:gsub('%((.*)%)$', function() return '(' .. new_dest .. ')' end))
end

--- The changed lines of `lines` (a note or a canvas) for these moves:
--- { [lnum] = new line }, count.
local function fixLines(lines, is_canvas, before, after, moved, src_old, src_new)
  local out, count = {}, 0
  local fence = false
  for i, line in ipairs(lines) do
    local new = line
    if is_canvas then
      new = line:gsub('("file"%s*:%s*")(.-)(")', function(a, path, c)
        local p = path:gsub('\\/', '/')
        if moved[p] then
          count = count + 1
          return a .. moved[p] .. c
        end
      end)
    else
      if line:match('^%s*```') or line:match('^%s*~~~') then fence = not fence end
      if not fence then
        local links = linksIn(line)
        -- Right to left, so the columns of the ones before stay valid.
        for k = #links, 1, -1 do
          local l = links[k]
          l.text = new:sub(l.s, l.e)
          local r = rewrite(l, before, after, moved, src_old, src_new)
          if r then
            new = new:sub(1, l.s - 1) .. r .. new:sub(l.e + 1)
            count = count + 1
          end
        end
      end
    end
    if new ~= line then out[i] = new end
  end
  return out, count
end

--- Read a file as lines, and whether it uses CRLF.
local function readLines(path)
  local ok, lines = pcall(vim.fn.readfile, path, 'b')
  if not ok then return nil end
  local crlf = lines[1] and lines[1]:sub(-1) == '\r'
  if crlf then
    for i, l in ipairs(lines) do lines[i] = l:gsub('\r$', '') end
  end
  return lines, crlf
end

--- Fix the links to `moves`. Asks first unless `quiet`.
function M.fixLinks(moves, quiet)
  local after, root = M.index(true)
  if not after or #moves == 0 then return end
  local moved, back = {}, {}
  for _, m in ipairs(moves) do
    moved[m.old] = m.new
    back[m.new] = m.old
  end
  -- The vault as it was: the moved files at their old paths.
  local old_files = {}
  for _, f in ipairs(after.files) do table.insert(old_files, back[f] or f) end
  local before = indexOf(old_files)

  -- The notes that may hold such a link: those that name one of the moved
  -- files (ripgrep), and the moved notes themselves. Ignoring .gitignore,
  -- as in listFiles: a private note linking to a moved one is fixed too.
  local args = { 'rg', '--files-with-matches', '--no-ignore-vcs', '--ignore-case', '--fixed-strings', '--path-separator', '/',
    '-g', '*.md', '-g', '*.canvas' }
  for _, m in ipairs(moves) do
    local stem = stemOf(m.old)
    vim.list_extend(args, { '-e', stem, '-e', urlencodeSpaces(stem) })
  end
  local candidates = {}
  local res = vim.fn.executable('rg') == 1 and vim.system(args, { cwd = root, text = true }):wait() or nil
  if res then
    for _, f in ipairs(vim.split(res.stdout or '', '\n', { trimempty = true })) do candidates[f] = true end
  else
    for _, f in ipairs(after.files) do
      if f:match('%.md$') or f:match('%.canvas$') then candidates[f] = true end
    end
  end
  for _, m in ipairs(moves) do
    if m.new:match('%.md$') then candidates[m.new] = true end
  end

  local edits, total = {}, 0
  for f in pairs(candidates) do
    local path = root .. '/' .. f
    local buf = vim.fn.bufnr(path)
    local loaded = buf > 0 and vim.api.nvim_buf_is_loaded(buf)
    local lines, crlf
    if loaded then
      lines = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
    else
      lines, crlf = readLines(path)
    end
    if lines then
      local changed, count = fixLines(lines, f:match('%.canvas$') ~= nil, before, after, moved, back[f] or f, f)
      if count > 0 then
        table.insert(edits, { file = f, path = path, buf = loaded and buf or nil, lines = lines,
          changed = changed, count = count, crlf = crlf })
        total = total + count
      end
    end
  end
  if total == 0 then return 0 end

  if not quiet then
    local names = {}
    for i, e in ipairs(edits) do
      if i > 8 then
        table.insert(names, ('… and %d more'):format(#edits - 8))
        break
      end
      table.insert(names, '  ' .. e.file .. ' (' .. e.count .. ')')
    end
    local choice = vim.fn.confirm(('Fix %d link%s in %d file%s?\n%s'):format(total, total == 1 and '' or 's',
      #edits, #edits == 1 and '' or 's', table.concat(names, '\n')), '&Yes\n&No', 1)
    if choice ~= 1 then return 0 end
  end

  local unsaved = {}
  for _, e in ipairs(edits) do
    if e.buf then
      local was_modified = vim.bo[e.buf].modified
      for lnum, text in pairs(e.changed) do
        vim.api.nvim_buf_set_lines(e.buf, lnum - 1, lnum, false, { text })
      end
      if was_modified then
        table.insert(unsaved, e.file)
      else
        vim.api.nvim_buf_call(e.buf, function() vim.cmd('silent noautocmd write') end)
      end
    else
      for lnum, text in pairs(e.changed) do e.lines[lnum] = text end
      if e.crlf then
        for i, l in ipairs(e.lines) do e.lines[i] = l .. '\r' end
      end
      vim.fn.writefile(e.lines, e.path, 'b')
    end
  end
  local msg = ('Fixed %d link%s in %d file%s'):format(total, total == 1 and '' or 's', #edits, #edits == 1 and '' or 's')
  if #unsaved > 0 then msg = msg .. '\nNot saved (they had unsaved changes): ' .. table.concat(unsaved, ', ') end
  vim.notify(msg)
  return total
end

-- -----------------------------------------------------------------------------
--  Renaming
-- -----------------------------------------------------------------------------

--- Rename (or move, with a '/') the current note and fix the links to it.
function M.rename(new_name)
  local _, root = M.index()
  local here = vim.api.nvim_buf_get_name(0)
  local rel = root and here ~= '' and relTo(root, here)
  if not rel then return vim.notify('Not a note of the vault', vim.log.levels.WARN) end
  local ext = rel:match('%.[^./]+$') or ''

  local function go(input)
    input = input and vim.trim(input) or ''
    if input == '' then return end
    input = input:gsub('\\', '/'):gsub('^/+', '')
    if ext ~= '' and input:sub(-#ext):lower() ~= ext:lower() then input = input .. ext end
    -- A bare name stays in the same folder; a path is from the vault's root.
    local new = input:find('/', 1, true) and input or ((dirOf(rel) ~= '' and (dirOf(rel) .. '/') or '') .. input)
    new = collapse(new)
    if not new or new == rel then return end
    local new_path = root .. '/' .. new
    -- A different case only is the same file on Windows and macOS: allowed.
    if vim.uv.fs_stat(new_path) and lower(new) ~= lower(rel) then
      return vim.notify(new .. ' already exists', vim.log.levels.ERROR)
    end
    vim.fn.mkdir(vim.fs.dirname(new_path), 'p')
    if vim.bo.modified then vim.cmd('silent write') end
    local ok, err = vim.uv.fs_rename(here, new_path)
    if not ok then return vim.notify('Could not rename: ' .. tostring(err), vim.log.levels.ERROR) end
    -- The buffer follows the file; the old name is not left behind as a buffer.
    local buf = vim.api.nvim_get_current_buf()
    vim.api.nvim_buf_set_name(buf, new_path)
    vim.cmd('silent! noautocmd write!')
    pcall(vim.cmd, 'bwipeout ' .. vim.fn.bufnr(here))
    invalidate()
    vim.notify(rel .. ' → ' .. new)
    M.fixLinks({ { old = rel, new = new } })
  end
  if new_name then return go(new_name) end
  vim.ui.input({ prompt = ' Rename note: ', default = rel:match('[^/]*$'):gsub('%.md$', '') }, go)
end

-- In oil, moving or renaming a note (or a folder of them) inside the vault
-- fixes the links to it, as Obsidian does.
local function oilPath(url)
  local path = url:match('^oil://(.*)$')
  if not path then return nil end
  local ok, fs = pcall(require, 'oil.fs')
  if ok and fs.posix_to_os_path then path = fs.posix_to_os_path(path) end
  return vim.fs.normalize(path)
end

vim.api.nvim_create_autocmd('User', {
  group = vim.api.nvim_create_augroup('PureNotesOil', { clear = true }),
  pattern = 'OilActionsPost',
  callback = function(args)
    local data = args.data or {}
    if data.err then return end
    local root = vault()
    if not root then return end
    invalidate()
    local idx = M.index(true)
    local moves = {}
    for _, a in ipairs(data.actions or {}) do
      if a.type == 'move' and a.src_url and a.dest_url then
        local src, dest = oilPath(a.src_url), oilPath(a.dest_url)
        local old, new = src and relTo(root, src), dest and relTo(root, dest)
        if old and new then
          if a.entry_type == 'directory' then
            for _, f in ipairs(idx.files) do
              if lower(f):sub(1, #new + 1) == lower(new) .. '/' then
                table.insert(moves, { old = old .. f:sub(#new + 1), new = f })
              end
            end
          else
            table.insert(moves, { old = old, new = new })
          end
        end
      end
    end
    if #moves > 0 then vim.schedule(function() M.fixLinks(moves) end) end
  end,
})

-- -----------------------------------------------------------------------------
--  Backlinks
-- -----------------------------------------------------------------------------

--- The lines of the vault that link to the current note, in a picker.
function M.backlinks()
  local idx, root = M.index()
  local here = vim.api.nvim_buf_get_name(0)
  local rel = root and here ~= '' and relTo(root, here)
  if not rel then return vim.notify('Not a note of the vault', vim.log.levels.WARN) end
  local stem = stemOf(rel)
  if vim.fn.executable('rg') == 0 then return vim.notify('Backlinks need ripgrep (rg)', vim.log.levels.WARN) end
  local res = vim.system({ 'rg', '--line-number', '--no-heading', '--no-ignore-vcs', '--ignore-case', '--fixed-strings',
    '--path-separator', '/', '-g', '*.md', '-e', stem, '-e', urlencodeSpaces(stem) }, { cwd = root, text = true }):wait()
  local hits = {}
  for _, l in ipairs(vim.split(res.stdout or '', '\n', { trimempty = true })) do
    local file, lnum, text = l:match('^(.-):(%d+):(.*)$')
    if file and file ~= rel then
      for _, link in ipairs(linksIn(text)) do
        if link.kind ~= 'url' then
          local parts = splitInner(link.kind == 'wiki' and link.inner or urldecode(link.inner))
          if parts.target ~= '' and resolve(idx, parts.target, file) == rel then
            table.insert(hits, ('%s:%s: %s'):format(file, lnum, vim.trim(text)))
            break
          end
        end
      end
    end
  end
  if #hits == 0 then return vim.notify('No note links to ' .. stem) end
  -- preview + cwd: the linking note is shown as you move, with the line of
  -- the link highlighted (asked for in Improvment.md, "like the grep").
  require('pure.fuzzyUtils').pickList(hits, { title = ' Links to ' .. stem .. ' ', fzf = "--nth=1,3..",
    preview = true, cwd = root },
    function(selection)
      local file, lnum = (selection or ''):match('^(.-):(%d+):')
      if not file then return end
      vim.cmd('edit ' .. vim.fn.fnameescape(root .. '/' .. file))
      pcall(vim.api.nvim_win_set_cursor, 0, { tonumber(lnum), 0 })
    end)
end

-- -----------------------------------------------------------------------------
--  Setup
-- -----------------------------------------------------------------------------

local group = vim.api.nvim_create_augroup('PureNotes', { clear = true })

vim.api.nvim_create_autocmd('FileType', {
  group = group,
  pattern = 'markdown',
  callback = function(args)
    local buf = args.buf
    vim.bo[buf].omnifunc = "v:lua.require'pure.notes'.omnifunc"
    -- The Todoist list maps <CR> to toggle a task; it asks M.follow first.
    if vim.bo[buf].buftype ~= '' then return end
    vim.keymap.set('n', '<CR>', M.enter, { buffer = buf, desc = 'Follow link / open block / toggle checkbox' })
  end,
})

-- A language server attaching later sets its own omnifunc: keep this one,
-- which hands it everything outside [[links.
vim.api.nvim_create_autocmd('LspAttach', {
  group = group,
  callback = function(args)
    if vim.bo[args.buf].filetype == 'markdown' then
      vim.bo[args.buf].omnifunc = "v:lua.require'pure.notes'.omnifunc"
    end
  end,
})

vim.api.nvim_create_autocmd({ 'BufWritePost', 'BufNewFile' }, {
  group = group,
  pattern = { '*.md', '*.canvas' },
  callback = invalidate,
})

vim.api.nvim_create_user_command('NoteRename', function(o) M.rename(o.args ~= '' and o.args or nil) end,
  { nargs = '?', desc = 'Rename the note and fix the links to it' })
vim.api.nvim_create_user_command('NoteBacklinks', M.backlinks, { desc = 'The notes that link to this one' })

return M

end

-- lua/pure/notify.lua
package.preload["pure.notify"] = function(...)
-- =============================================================================
--  Notifications
-- =============================================================================
--  Replaces mini.notify. Takes over vim.notify and shows each message in a
--  floating window in the top-right corner, newest at the bottom. A message
--  stays for a few seconds (longer for warnings and errors), then goes away;
--  all of them are kept in a history.
--
--    :Notifications        open the history in a split
--    require('pure.notify').get_all()   the history as a Lua list
--
--  Colours: PureNotifyNormal / PureNotifyBorder (link to NormalFloat /
--  FloatBorder); warnings and errors use DiagnosticWarn / DiagnosticError.
-- =============================================================================

local M = {}

local levels = vim.log.levels

--- How long a message stays on screen, per level (ms).
local duration = {
  [levels.ERROR] = 8000,
  [levels.WARN]  = 6000,
}
local default_duration = 4000
local max_width_share = 0.382 -- of the editor width, as mini.notify was set up

local level_hl = {
  [levels.ERROR] = 'DiagnosticError',
  [levels.WARN]  = 'DiagnosticWarn',
}

local level_name = {}
for name, value in pairs(levels) do level_name[value] = name end

vim.api.nvim_set_hl(0, 'PureNotifyNormal', { link = 'NormalFloat', default = true })
vim.api.nvim_set_hl(0, 'PureNotifyBorder', { link = 'FloatBorder', default = true })

local history = {} -- every message, oldest first: { id, msg, level, time }
local active = {}  -- the ones on screen now, in the same order
local next_id = 1

local ns = vim.api.nvim_create_namespace('pure_notify')
local buf, win

-- -----------------------------------------------------------------------------
--  Window
-- -----------------------------------------------------------------------------
local function close()
  if win and vim.api.nvim_win_is_valid(win) then
    vim.api.nvim_win_close(win, true)
  end
  win = nil
end

--- Rebuild the window from `active`: one block of lines per message.
local function render()
  if #active == 0 then return close() end

  if not (buf and vim.api.nvim_buf_is_valid(buf)) then
    buf = vim.api.nvim_create_buf(false, true)
    vim.bo[buf].filetype = 'pure-notify'
  end

  local lines, spans = {}, {}
  for _, item in ipairs(active) do
    local first = #lines
    for _, line in ipairs(vim.split(item.msg, '\n', { plain = true })) do
      table.insert(lines, line)
    end
    table.insert(spans, { first, #lines, level_hl[item.level] })
  end
  vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)

  vim.api.nvim_buf_clear_namespace(buf, ns, 0, -1)
  for _, span in ipairs(spans) do
    if span[3] then
      vim.api.nvim_buf_set_extmark(buf, ns, span[1], 0, { end_row = span[2], hl_group = span[3], hl_eol = true })
    end
  end

  -- Width is the longest line, capped; the height counts wrapped lines, so a
  -- long error is shown whole instead of cut at the window edge.
  local max_width = math.max(math.floor(vim.o.columns * max_width_share), 20)
  local width = 1
  for _, line in ipairs(lines) do
    width = math.max(width, vim.fn.strdisplaywidth(line))
  end
  width = math.min(width, max_width)
  local height = 0
  for _, line in ipairs(lines) do
    height = height + math.max(1, math.ceil(vim.fn.strdisplaywidth(line) / width))
  end
  height = math.min(height, math.max(vim.o.lines - 4, 1))

  local config = {
    relative = 'editor',
    anchor = 'NE',
    row = vim.o.showtabline == 2 and 1 or 0,
    col = vim.o.columns,
    width = width,
    height = height,
    style = 'minimal',
    border = 'rounded',
    focusable = false,
    zindex = 250,
  }

  if win and vim.api.nvim_win_is_valid(win) then
    vim.api.nvim_win_set_config(win, config)
  else
    config.noautocmd = true
    win = vim.api.nvim_open_win(buf, false, config)
    vim.wo[win].wrap = true
    vim.wo[win].winhighlight = 'NormalFloat:PureNotifyNormal,FloatBorder:PureNotifyBorder'
  end
end

local function remove(id)
  for i, item in ipairs(active) do
    if item.id == id then
      table.remove(active, i)
      break
    end
  end
  render()
end

-- -----------------------------------------------------------------------------
--  API
-- -----------------------------------------------------------------------------

--- Drop-in for vim.notify (same arguments; `opts` is accepted and ignored).
function M.notify(msg, level, opts)
  level = level or levels.INFO
  if level == levels.OFF then return end

  local item = { id = next_id, msg = tostring(msg), level = level, time = os.time() }
  next_id = next_id + 1
  table.insert(history, item)

  -- vim.notify may be called from a libuv callback (a job, an LSP handler)
  -- where windows cannot be touched, so the drawing always waits for the main
  -- loop. The history above is updated right away either way.
  vim.schedule(function()
    table.insert(active, item)
    render()
    vim.defer_fn(function() remove(item.id) end, duration[level] or default_duration)
  end)
end

--- Every message since startup, oldest first. Each entry is a copy.
function M.get_all()
  return vim.deepcopy(history)
end

--- Hide everything on screen now (the history is kept).
function M.clear()
  active = {}
  render()
end

--- Show the history in a scratch split, one line per message line.
function M.showHistory()
  local lines = {}
  for _, item in ipairs(history) do
    local prefix = os.date('%H:%M:%S', item.time) .. ' ' .. (level_name[item.level] or '?') .. ' '
    for i, line in ipairs(vim.split(item.msg, '\n', { plain = true })) do
      table.insert(lines, (i == 1 and prefix or string.rep(' ', #prefix)) .. line)
    end
  end
  if #lines == 0 then lines = { 'No notifications yet.' } end

  vim.cmd('botright new')
  local hbuf = vim.api.nvim_get_current_buf()
  vim.bo[hbuf].buftype = 'nofile'
  vim.bo[hbuf].bufhidden = 'wipe'
  vim.api.nvim_buf_set_lines(hbuf, 0, -1, false, lines)
  vim.bo[hbuf].modifiable = false
  -- pcall: the name is taken while an earlier history split is still open.
  pcall(vim.api.nvim_buf_set_name, hbuf, 'Notifications')
  vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = hbuf, desc = 'Close notification history' })
  vim.cmd('normal! G')
end

vim.api.nvim_create_user_command('Notifications', M.showHistory, { desc = 'Show notification history' })

-- Keep the window in the corner when the editor is resized.
vim.api.nvim_create_autocmd('VimResized', {
  group = vim.api.nvim_create_augroup('PureNotify', { clear = true }),
  callback = function() if #active > 0 then render() end end,
})

