end

local function hideTerminal(cmd)
  local term = terminals[cmd]
  if term and term.win and vim.api.nvim_win_is_valid(term.win) then
    vim.api.nvim_win_close(term.win, true)
    term.win = nil
  end
end

function M.toggleTerminal(cmd, ratio)
  cmd = cmd or "default"
  ratio = ratio or 0.8

  local term = terminals[cmd]

  -- If the window for this terminal is open, close it.
  if term and term.win and vim.api.nvim_win_is_valid(term.win) then
    vim.api.nvim_win_close(term.win, true)
    term.win = nil
    return
  end

  -- If a valid buffer for this command exists, re-open it in a new window.
  if term and term.buf and vim.api.nvim_buf_is_valid(term.buf) then
    local buf = term.buf
    local win, _ = func.createWindow(" ", 0.8)
    vim.api.nvim_win_set_buf(win, buf)
    term.win = win
    vim.api.nvim_set_current_win(win)
    vim.cmd("startinsert") -- Re-enter terminal-insert mode.
    return
  end

  -- If we get here, create a new terminal from scratch.
  local cwd
  local current_buf_name = vim.api.nvim_buf_get_name(0)
  if current_buf_name ~= "" and vim.fn.filereadable(current_buf_name) == 1 and vim.bo.buftype == "" then
    cwd = vim.fn.expand("%:p:h")
  else
    cwd = vim.fn.getcwd()
  end

  -- Create a floating window, then switch to it.
  local new_win, _ = func.createWindow(" ", ratio)
  vim.api.nvim_set_current_win(new_win)

  -- Set the working directory for this window only, then open the terminal.
  local escaped_cwd = vim.fn.fnameescape(cwd)
  vim.cmd('lcd ' .. escaped_cwd)

  -- Run the terminal, which will inherit the window-local CWD.
  local final_cmd = "terminal"
  if cmd and cmd ~= "default" then
    final_cmd = final_cmd .. " " .. cmd
  end
  -- 'shell' has no buffer-local form, so swap it just around this one call.
  -- :terminal resolves it when the job starts, so restoring it immediately
  -- afterwards leaves the fuzzy pickers on bash. Only the bare interactive
  -- terminal is switched: an explicit command keeps running under 'shell',
  -- where shellcmdflag is already known to match.
  local saved_shell = vim.o.shell
  if cmd == "default" then
    vim.o.shell = interactiveShell()
  end
  vim.cmd(final_cmd)
  vim.o.shell = saved_shell

  vim.cmd('startinsert')

  -- The :terminal command created a new buffer, so we store it.
  local term_buf = vim.api.nvim_get_current_buf()
  terminals[cmd] = { buf = term_buf, win = new_win }

  -- Keys that close the floating terminal.
  --
  -- This buffer only had a normal-mode <Esc>, but startinsert above leaves you
  -- in terminal-insert mode, so <Esc> went straight to the shell and there was
  -- no configured way out at all. <Esc> alone cannot be taken over in terminal
  -- mode -- the shell and any TUI inside it need it -- so the terminal-mode
  -- binding is <Esc><Esc>.
  for mode, lhs in pairs({ t = '<Esc><Esc>', n = '<Esc>' }) do
    vim.keymap.set(mode, lhs, function() hideTerminal(cmd) end,
      { silent = true, buffer = term_buf, desc = "Hide floating terminal" })
  end
end

return M


end

-- lua/pure/todoist.lua
package.preload["pure.todoist"] = function(...)
-- =============================================================================
--  Todoist
-- =============================================================================
--  Todoist tasks in an editable buffer, like oil.nvim does for files: edit
--  the list as text and :w applies the difference to Todoist. Talks to the
--  Todoist API v1 through curl.
--
--    :Todoist                 all active tasks
--    :Todoist today | overdue any Todoist filter query (as in the app)
--
--  The buffer is a markdown task list, one section per project:
--
--    ## Work
--    - [ ] Write the README due:today p1
--      - [ ] Sub step due:tomorrow
--    - [ ] Review PR
--
--    - text first, then due:<any Todoist date phrase, in English> and a
--      priority p1..p3 as the last word (no pN = normal priority)
--    - indenting a line makes it a subtask of the line above it
--    - the ## heading is the project: move a line under another to move it
--    - new line = new task, deleted line = deleted task, [x] = complete
--    - each task ends in a hidden id (concealed); a copied line becomes a
--      new task
--
--  :w shows what will change and asks before sending it. How often it asks is
--  set with vim.g.pure_todoist_confirm:
--    'all'     every save (default)
--    'delete'  only when the save would delete tasks
--    'never'   never
--  Also:
--    <CR> / x   toggle the checkbox on the cursor line (x does not delete here)
--    <leader>x  cycle [ ] [~] [!] [>] [-] [x]; only [x] (done) reaches Todoist,
--               the other states are kept locally and drawn back on reload
--    r          reload (asks first if there are unsaved edits)
--    q / <Esc>  close (same)
--
--  Token (Todoist > Settings > Integrations > Developer), never kept in this
--  repository. Either of:
--    - a file holding just the token: stdpath('data')/todoist_token
--      (~/.local/share/nvim/todoist_token, or %LOCALAPPDATA%\nvim-data\ on
--      Windows). :TodoistToken writes it for you.
--    - the TODOIST_API_TOKEN environment variable
--
--  Archive: set vim.g.pure_todoist_archive to a folder to keep tasks.md (the
--  full list), history.md (each change, with its time) and tasks.json there,
--  written in the background and only when something changed. A relative
--  folder is taken inside the Obsidian vault (pure/zettelkasten.lua), so it
--  follows the vault when that moves. See "Archive".
--
--  When neither exists, Neovim asks for it on startup, with the option to stop
--  asking. :TodoistToken sets the token later and turns the question back on.
-- =============================================================================

local M = {}

local api = 'https://api.todoist.com/api/v1'

-- Both live in the data directory, outside the config repository.
local token_file = vim.fn.stdpath('data') .. '/todoist_token'
local no_prompt_file = vim.fn.stdpath('data') .. '/todoist_no_prompt'

-- -----------------------------------------------------------------------------
--  HTTP
-- -----------------------------------------------------------------------------

local function token()
  local env = vim.env.TODOIST_API_TOKEN
  if env and env ~= '' then return env end
  local f = io.open(token_file, 'r')
  if not f then return nil end
  local t = vim.trim(f:read('*l') or '')
  f:close()
  -- An empty file counts as no token, so the startup question still comes up.
  return t ~= '' and t or nil
end

local function urlencode(s)
  return (s:gsub('[^%w%-_%.~]', function(c) return ('%%%02X'):format(c:byte()) end))
end

--- Call the API and hand the decoded JSON to `cb(err, data)` on the main loop.
---
--- The Authorization header is fed to curl on stdin (-H @-) rather than as an
--- argument, so the token never shows up in the process list.
---
--- `body`, when given, is sent as JSON. It is no secret, so it can go on the
--- command line; vim.system passes arguments without a shell, so its quotes
--- need no escaping on any platform.
local function request(method, path, cb, body)
  local tok = token()
  if not tok then
    return cb('No Todoist token: run :TodoistToken to set it')
  end

  local base = vim.g.pure_todoist_url or api
  local cmd = { 'curl', '-sS', '-X', method, '-H', '@-', '-w', '\n%{http_code}', base .. path }
  if body then
    vim.list_extend(cmd, { '-H', 'Content-Type: application/json', '--data-binary', vim.json.encode(body) })
  end
  local ok, err = pcall(vim.system, cmd, { stdin = 'Authorization: Bearer ' .. tok .. '\n', text = true },
    vim.schedule_wrap(function(res)
      if res.code ~= 0 then
        return cb('curl failed: ' .. vim.trim(res.stderr or ''))
      end
      local body, status = res.stdout:match('^(.*)\n(%d+)$')
      status = tonumber(status)
      if not status or status >= 300 then
        return cb(('Todoist API %s %s -> HTTP %s %s'):format(method, path, tostring(status), vim.trim(body or '')))
      end
      if body == '' then return cb(nil, nil) end
      local decoded_ok, data = pcall(vim.json.decode, body, { luanil = { object = true, array = true } })
      if not decoded_ok then return cb('Invalid JSON from Todoist: ' .. tostring(data)) end
      cb(nil, data)
    end))
  if not ok then cb('Could not run curl: ' .. tostring(err)) end
end

--- GET every page of a paginated list endpoint ({ results, next_cursor }).
local function getAll(path, cb)
  local items = {}
  local function page(cursor)
    local sep = path:find('?', 1, true) and '&' or '?'
    local url = path .. sep .. 'limit=200' .. (cursor and ('&cursor=' .. urlencode(cursor)) or '')
    request('GET', url, function(err, data)
      if err then return cb(err) end
      vim.list_extend(items, data.results or {})
      if data.next_cursor then return page(data.next_cursor) end
      cb(nil, items)
    end)
  end
  page(nil)
end

-- -----------------------------------------------------------------------------
--  Shared helpers
-- -----------------------------------------------------------------------------

--- Todoist stores priority 4 as the most urgent; the app shows that as P1.
local function priorityLabel(p)
  p = tonumber(p) or 1
  return p > 1 and ('P' .. (5 - p)) or ''
end

local function dueSortKey(task)
  -- No due date sorts last.
  return task.due and task.due.date or '9999-99-99'
end

--- Due date first (none last), then the most urgent priority.
local function sortTasks(tasks)
  table.sort(tasks, function(a, b)
    local da, db = dueSortKey(a), dueSortKey(b)
    if da ~= db then return da < db end
    return (tonumber(a.priority) or 1) > (tonumber(b.priority) or 1)
  end)
end

--- The due date as the buffer shows and edits it: Todoist's own phrase
--- ("every monday"), so an untouched recurring date is sent back unchanged.
local function dueText(t)
  return t.due and (t.due.string or t.due.date) or ''
end

-- -----------------------------------------------------------------------------
--  Task buffer
-- -----------------------------------------------------------------------------
--  Works like oil.nvim: the buffer is rendered from the API, `snapshot` keeps
--  what each task looked like, and on :w the parsed buffer is compared with it
--  to work out creates, updates, moves, completions and deletes.

local state = {
  buf = nil,
  filter = nil,
  snapshot = {}, -- id -> { content, due, priority, project_id, parent_id, checked }
  projects = { by_name = {}, by_id = {}, inbox = nil },
  saving = false,
  loaded = nil, -- filter key ('' = all) the buffer currently shows
}

local id_ns = vim.api.nvim_create_namespace('pure_todoist_ids')

-- Priorities in Todoist's own colours, which are clearly apart; the theme's
-- Diagnostic groups were pale pastels where p1 and p2 looked alike. The due
-- date is secondary information, so it is dimmed rather than coloured.
-- `default`: a theme may define these groups itself.
local function setTodoistHighlights()
  vim.api.nvim_set_hl(0, 'PureTodoistP1', { fg = '#d1453b', default = true })
  vim.api.nvim_set_hl(0, 'PureTodoistP2', { fg = '#eb8909', default = true })
  vim.api.nvim_set_hl(0, 'PureTodoistP3', { fg = '#246fe0', default = true })
  vim.api.nvim_set_hl(0, 'PureTodoistDue', { link = 'Comment', default = true })
end
setTodoistHighlights()
vim.api.nvim_create_autocmd('ColorScheme', { callback = setTodoistHighlights })
local hint_ns = vim.api.nvim_create_namespace('pure_todoist_hint')

local function oneLine(s)
  return (tostring(s or ''):gsub('\n', ' '):gsub('%s%s+', ' '))
end

--- Split a task's text from its metadata, which follows it after a single
--- space: 'due:<date phrase>' (spaces allowed: 'due:next monday 10:00') and a
--- priority 'p1'..'p4' as the last word, before or after the due date.
--- Returns content, due ('' if none), priority (API value, 4 = p1) and the
--- ranges of the metadata in `s` ({ from, to, kind }) for highlighting.
local function splitMeta(s)
  local ranges, priority = {}, 1

  -- A trailing ' pN' word; `offset` maps positions in `part` back to `s`.
  local function takePriority(part, offset)
    local head, n = part:match('^(.-)%s+[pP]([1-4])%s*$')
    if not head then return part end
    local at = part:find('[pP][1-4]%s*$', #head + 1)
    priority = 5 - tonumber(n)
    table.insert(ranges, { offset + at, offset + at + 1, 'p' .. n })
    return head
  end

  local due, content = '', s
  local at = s:find('%sdue:')
  if at then
    local tail = takePriority(s:sub(at + 1), at) -- 'due:...' without a trailing pN
    due = vim.trim(tail:sub(5))
    table.insert(ranges, { at + 1, at + #tail, 'due' })
    content = s:sub(1, at - 1)
  end
  content = takePriority(content, 0)
  return vim.trim(content), due, priority, ranges
end

-- Obsidian's extra checkbox states ([~] in progress, [!] important, [>]
-- deferred, [-] cancelled) have no field in Todoist, which only knows done or
-- not. They are kept on this machine, per task id, and drawn back into the
-- list; to Todoist those tasks are simply not done.
local states_file = vim.fn.stdpath('data') .. '/todoist_states.json'

local function readStates()
  local f = io.open(states_file, 'r')
  if not f then return {} end
  local ok, data = pcall(vim.json.decode, f:read('*a'))
  f:close()
  return ok and type(data) == 'table' and data or {}
end

--- Record the state of every parsed item (and forget completed and deleted
--- tasks). Returns true when the file changed.
local state_names = { ['~'] = 'in progress', ['!'] = 'important', ['>'] = 'deferred', ['-'] = 'cancelled' }

--- Also returns history entries for the marks that changed.
local function saveStates(items, deleted_ids)
  local store = readStates()
  local before = vim.json.encode(store)
  local entries = {}
  for _, item in ipairs(items) do
    if item.id then
      local mark = (not item.checked) and item.mark or nil
      if mark ~= store[item.id] and not item.checked then
        table.insert(entries, mark and ('marked [%s] %s · %s'):format(mark, state_names[mark] or '', item.content)
          or ('cleared mark · ' .. item.content))
      end
      store[item.id] = mark
    end
  end
  for _, id in ipairs(deleted_ids or {}) do store[id] = nil end
  local after = vim.json.encode(store)
  if after == before then return false, entries end
  vim.fn.mkdir(vim.fn.stdpath('data'), 'p')
  local f = io.open(states_file, 'w')
  if f then f:write(after) f:close() end
  return true, entries
end

--- `- [ ] text due:today p1 ‹id›` at the given depth; `mark` is a local state.
local function taskLine(t, depth, mark)
  local box = t.checked and 'x' or (mark or ' ')
  local parts = { ('%s- [%s] %s'):format(string.rep('  ', depth), box, oneLine(t.content)) }
  local due = dueText(t)
  if due ~= '' then table.insert(parts, 'due:' .. due) end
  local p = priorityLabel(t.priority):lower()
  if p ~= '' then table.insert(parts, p) end
  return table.concat(parts, ' ') .. ' ‹' .. t.id .. '›'
end

--- Parse one buffer line; nil when it is not a task.
--- Accepts '- text' without a box too, so a quickly typed line still counts.
local function parseLine(line)
  local indent, rest = line:match('^(%s*)[-*+]%s+(.*)$')
  if not indent then
    -- A bare line of text is a task too, as a bare name is a file in oil:
    -- typing "Buy bread" under a heading is enough. Headings and blank
    -- lines are not.
    if line:match('^%s*$') or line:match('^%s*#') then return nil end
    indent, rest = line:match('^(%s*)(.-)%s*$')
  end

  local body, id = rest:match('^(.-)%s*‹([%w_%-]+)›%s*$')
  body = body or rest

  -- Any one-character box: [x] is done; [~] [!] [>] [-] are local states.
  local checked, mark = false, nil
  local box, after = body:match('^%[(.)%]%s*(.*)$')
  if box then
    checked = box == 'x' or box == 'X'
    if not checked and box ~= ' ' then mark = box end
    body = after
  end

  local content, due, priority = splitMeta(body)
  if content == '' then return nil end

  local width = indent:gsub('\t', '  ')
  return { indent = #width, checked = checked, mark = mark, content = content, due = due, priority = priority, id = id }
end

--- Hide the ids and colour the metadata. Re-run on every change, since
--- editing moves the text the marks were placed on.
local function decorate(buf)
  vim.api.nvim_buf_clear_namespace(buf, id_ns, 0, -1)
  local priority_hl = { 'PureTodoistP1', 'PureTodoistP2', 'PureTodoistP3' }
  for row, line in ipairs(vim.api.nvim_buf_get_lines(buf, 0, -1, false)) do
    if parseLine(line) then
      local id_start, id_end = line:find('%s*‹[%w_%-]+›%s*$')
      if id_start then
        vim.api.nvim_buf_set_extmark(buf, id_ns, row - 1, id_start - 1, { end_col = id_end, conceal = '' })
      end

      -- The same split parseLine uses, run on the line minus its id.
      local _, _, _, ranges = splitMeta(line:sub(1, (id_start or #line + 1) - 1))
      for _, r in ipairs(ranges) do
        if r[3] == 'due' then
          vim.api.nvim_buf_set_extmark(buf, id_ns, row - 1, r[1] - 1, { end_col = r[2], hl_group = 'PureTodoistDue' })
        else
          -- 'pN' is concealed into a coloured flag (p4, normal priority, into
          -- nothing). Like the ids it shows as text again while the line is
          -- being edited, since the window's concealcursor is 'nc'.
          local n = tonumber(r[3]:sub(2))
          vim.api.nvim_buf_set_extmark(buf, id_ns, row - 1, r[1] - 1, {
            end_col = r[2],
            conceal = priority_hl[n] and '\u{F023B}' or '', -- md-flag
            hl_group = priority_hl[n],
          })
        end
      end
    end
  end
end

local function setLines(lines)
  local buf = state.buf
  vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)
  vim.bo[buf].modified = false
  decorate(buf)
end

-- -----------------------------------------------------------------------------
--  Archive
-- -----------------------------------------------------------------------------
--  With vim.g.pure_todoist_archive set to a folder, the plugin keeps there:
--
--    tasks.md    the full task list as the buffer shows it, without the ids
--    history.md  one timestamped line per change: those made here with :w,
--                and those made elsewhere (the app, the phone), noticed when
--                the full list is reloaded
--    tasks.json  the last full list, to tell what changed since
--
--  tasks.md and tasks.json hold no timestamp and are rewritten only when their
--  content differs, so reloading an unchanged list touches nothing. All disk
--  work goes through libuv's asynchronous calls, off the editing path; only
--  the text is prepared on the main loop.

local archive = { skip_external = false }
local uv = vim.uv

--- The archive folder (created on first use), or nil when archiving is off.
---
--- A relative path is inside the Obsidian vault. With an absolute one written
--- into the config, moving the vault left the setting behind, and the mkdir
--- below quietly recreated the old folder, which lived in iCloud.
local function archiveDir()
  local dir = vim.g.pure_todoist_archive
  if type(dir) ~= 'string' or dir == '' then return nil end
  dir = vim.fn.expand(dir)
  if vim.fn.isabsolutepath(dir) == 0 then
    local vault = require('pure.zettelkasten').vaultPath()
    if not vault then return nil end -- no vault set yet: nowhere to keep it
    dir = vault .. '/' .. dir
  end
  dir = vim.fs.normalize(dir)
  vim.fn.mkdir(dir, 'p')
  return dir
end

local function readAsync(path, cb)
  uv.fs_open(path, 'r', 438, function(err, fd)
    if err then return cb(nil) end
    uv.fs_fstat(fd, function(_, stat)
      uv.fs_read(fd, stat and stat.size or 0, 0, function(_, data)
        uv.fs_close(fd)
        cb(data)
      end)
    end)
  end)
end

--- `flags` 'w' replaces, 'a' appends. Errors are reported on the main loop.
local function writeAsync(path, data, flags)
  uv.fs_open(path, flags, 420, function(err, fd)
    if err then
      return vim.schedule(function()
        vim.notify('Todoist archive: cannot write ' .. path .. ': ' .. err, vim.log.levels.WARN)
      end)
    end
    uv.fs_write(fd, data, -1, function() uv.fs_close(fd) end)
  end)
end

--- Replace `path` with `data` only if it differs from what is there.
local function writeIfChanged(path, data)
  readAsync(path, function(old)
    if old ~= data then writeAsync(path, data, 'w') end
  end)
end

--- Append one line per entry to history.md, all with the same time.
local function logEntries(dir, entries)
  if not dir or #entries == 0 then return end
  local stamp = os.date('%Y-%m-%d %H:%M:%S')
  local out = {}
  for _, e in ipairs(entries) do table.insert(out, ('- %s · %s\n'):format(stamp, e)) end
  writeAsync(dir .. '/history.md', table.concat(out), 'a')
end

function archive.log(entries)
  logEntries(archiveDir(), entries)
end

--- One record per task, as a JSON array sorted by id: arrays keep their order,
--- so the same list always encodes to the same text (object key order does
--- not), and an unchanged list is recognised as such.
local function records(tasks, project_names)
  local list = {}
  for _, t in ipairs(tasks) do
    table.insert(list, { t.id, oneLine(t.content), dueText(t), tonumber(t.priority) or 1,
      project_names[t.project_id] or t.project_id or '' })
  end
  table.sort(list, function(a, b) return a[1] < b[1] end)
  return list
end

--- What changed between two record lists, as history entries.
local function externalChanges(old, new)
  local before, after, entries = {}, {}, {}
  for _, r in ipairs(old) do before[r[1]] = r end
  for _, r in ipairs(new) do after[r[1]] = r end
  for id, r in pairs(after) do
    local o = before[id]
    if not o then
      table.insert(entries, ('added elsewhere · %s (%s)'):format(r[2], r[5]))
    else
      local diffs = {}
      if o[2] ~= r[2] then table.insert(diffs, ('text: "%s" → "%s"'):format(o[2], r[2])) end
      if o[3] ~= r[3] then table.insert(diffs, ('due: %s → %s'):format(o[3] ~= '' and o[3] or 'none', r[3] ~= '' and r[3] or 'none')) end
      if o[4] ~= r[4] then table.insert(diffs, ('priority: p%d → p%d'):format(5 - o[4], 5 - r[4])) end
      if o[5] ~= r[5] then table.insert(diffs, ('project: %s → %s'):format(o[5], r[5])) end
      if #diffs > 0 then table.insert(entries, ('changed elsewhere · %s · %s'):format(r[2], table.concat(diffs, '; '))) end
    end
  end
  for id, o in pairs(before) do
    if not after[id] then table.insert(entries, ('gone elsewhere (completed or deleted) · %s'):format(o[2])) end
  end
  table.sort(entries)
  return entries
end

--- Archive the full task list: tasks.md and tasks.json when they changed, and
--- history lines for anything that changed outside Neovim since last time.
--- Only called with the unfiltered list; a filtered view is not the archive.
function archive.snapshot(tasks, projects)
  local dir = archiveDir()
  if not dir then return end

  local names, order = {}, {}
  for _, p in ipairs(projects) do
    names[p.id] = p.name
    table.insert(order, p.id)
  end

  -- tasks.md, grouped and nested like the buffer, local states included.
  local sorted = vim.deepcopy(tasks)
  sortTasks(sorted)
  local shown, children, top = {}, {}, {}
  for _, t in ipairs(sorted) do shown[t.id] = true end
  for _, t in ipairs(sorted) do
    if t.parent_id and shown[t.parent_id] then
      children[t.parent_id] = children[t.parent_id] or {}
      table.insert(children[t.parent_id], t)
    else
      top[t.project_id] = top[t.project_id] or {}
      table.insert(top[t.project_id], t)
    end
  end
  local marks = readStates()
  local md = { '# Todoist' }
  local function emit(t, depth)
    table.insert(md, (taskLine(t, depth, marks[t.id]):gsub('%s*‹[%w_%-]+›%s*$', '')))
    for _, c in ipairs(children[t.id] or {}) do emit(c, depth + 1) end
  end
  for pid in pairs(top) do
    if not names[pid] then table.insert(order, pid) end
  end
  for _, pid in ipairs(order) do
    if top[pid] then
      vim.list_extend(md, { '', '## ' .. (names[pid] or pid) })
      for _, t in ipairs(top[pid]) do emit(t, 0) end
    end
  end
  local md_text = table.concat(md, '\n') .. '\n'

  local new = records(tasks, names)
  local json_text = vim.json.encode(new) .. '\n'
  -- After a save the list differs from tasks.json by our own changes, which
  -- history.md already has; comparing now would log them again as external.
  local skip = archive.skip_external
  archive.skip_external = false

  writeIfChanged(dir .. '/tasks.md', md_text)
  readAsync(dir .. '/tasks.json', function(old_text)
    if old_text == json_text then return end
    local ok, old = pcall(vim.json.decode, old_text or '')
    local entries
    if not old_text or not ok or type(old) ~= 'table' then
      entries = { ('archive started · %d tasks'):format(#new) }
    elseif not skip then
      entries = externalChanges(old, new)
    end
    writeAsync(dir .. '/tasks.json', json_text, 'w')
    if entries then logEntries(dir, entries) end
  end)
end

--- Build the buffer: one ## section per project (in Todoist's order), tasks
--- nested under their parent. A subtask whose parent is not in this view
--- (filtered out) is shown at the top level.
local function render(tasks, projects)
  state.projects = { by_name = {}, by_id = {}, inbox = nil, order = {} }
  for _, p in ipairs(projects) do
    state.projects.by_id[p.id] = p.name
    if not state.projects.by_name[p.name] then state.projects.by_name[p.name] = p.id end
    if p.inbox_project or p.is_inbox_project then state.projects.inbox = p.id end
    table.insert(state.projects.order, p.id)
  end
  -- Lines above the first heading go to the Inbox, which Todoist lists first.
  state.projects.inbox = state.projects.inbox or state.projects.order[1]

  sortTasks(tasks)
  local shown = {}
  for _, t in ipairs(tasks) do shown[t.id] = true end

  local children, top = {}, {}
  for _, t in ipairs(tasks) do
    if t.parent_id and shown[t.parent_id] then
      children[t.parent_id] = children[t.parent_id] or {}
      table.insert(children[t.parent_id], t)
    else
      top[t.project_id] = top[t.project_id] or {}
      table.insert(top[t.project_id], t)
    end
  end

  local lines = { '# Todoist' .. (state.filter and (' — ' .. state.filter) or '') }
  state.snapshot = {}

  local marks = readStates()
  local function emit(t, depth, shown_parent)
    table.insert(lines, taskLine(t, depth, marks[t.id]))
    state.snapshot[t.id] = {
      content = oneLine(t.content), due = dueText(t), priority = tonumber(t.priority) or 1,
      project_id = t.project_id, parent_id = shown_parent, checked = t.checked and true or false,
    }
    for _, c in ipairs(children[t.id] or {}) do emit(c, depth + 1, t.id) end
  end

  -- Projects Todoist knows first, in its order; then any the list lacked.
  local order = vim.deepcopy(state.projects.order)
  for pid in pairs(top) do
    if not state.projects.by_id[pid] then table.insert(order, pid) end
  end
  for _, pid in ipairs(order) do
    if top[pid] then
      vim.list_extend(lines, { '', '## ' .. (state.projects.by_id[pid] or pid) })
      for _, t in ipairs(top[pid]) do emit(t, 0, nil) end
    end
  end
  -- Nothing to show: list every project as an empty section, so there is a
  -- heading to type new tasks under. (Not a line of prose: any text line
  -- would now be read as a task.)
  if #tasks == 0 then
    for _, pid in ipairs(state.projects.order) do
      vim.list_extend(lines, { '', '## ' .. state.projects.by_id[pid] })
    end
  end

  setLines(lines)
  if not state.filter then archive.snapshot(tasks, projects) end
  vim.api.nvim_buf_clear_namespace(state.buf, hint_ns, 0, -1)
  vim.api.nvim_buf_set_extmark(state.buf, hint_ns, 0, 0, {
    virt_lines = { { { ':w apply · <CR>/x toggle · r reload · q close · indent = subtask · due:…  p1-p3', 'Comment' } } },
  })
end

--- Tasks for `filter` plus the project list, as cb(err, tasks, projects).
local function fetch(filter, cb)
  local path = filter and ('/tasks/filter?query=' .. urlencode(filter)) or '/tasks'
  getAll(path, function(err, tasks)
    if err then return cb(err) end
    getAll('/projects', function(perr, projects)
      if perr then vim.notify(perr, vim.log.levels.WARN) end
      cb(nil, tasks, projects or {})
    end)
  end)
end

-- Tasks fetched in the background at startup, by filter key ('' = all), so
-- the first :Todoist draws at once instead of waiting on the network.
local prefetched = {}

--- Fetch from Todoist and redraw the buffer. Only runs on the first open of a
--- filter, after :w, and on r -- reopening the list reuses what is there.
--- `on_done(tasks)` runs after a successful redraw.
function M.reload(on_done)
  if not (state.buf and vim.api.nvim_buf_is_valid(state.buf)) then return end
  setLines({ '# Todoist', '', 'Loading…' })
  local key = state.filter or ''

  fetch(state.filter, function(err, tasks, projects)
    if not vim.api.nvim_buf_is_valid(state.buf) then return end
    if err then
      state.loaded = nil
      setLines({ '# Todoist', '', 'Error: ' .. err })
      return vim.notify(err, vim.log.levels.ERROR)
    end
    render(tasks, projects)
    state.loaded = key
    if type(on_done) == 'function' then on_done(tasks) end
  end)
end

-- -----------------------------------------------------------------------------
--  Saving: buffer -> list of API calls
-- -----------------------------------------------------------------------------

--- Parse the whole buffer into task items with their project and parent.
--- Returns items, or nil and an error message naming the line.
local function collect(buf)
  local items, seen = {}, {}
  local project = state.projects.inbox
  local stack = {} -- open ancestors: { indent, item }

  for lnum, line in ipairs(vim.api.nvim_buf_get_lines(buf, 0, -1, false)) do
    local heading = line:match('^##%s+(.-)%s*$')
    if heading then
      project = state.projects.by_name[heading]
      if not project then
        return nil, ('line %d: no Todoist project called "%s"'):format(lnum, heading)
      end
      stack = {}
    else
      local item = parseLine(line)
      if item then
        if not project then
          return nil, ('line %d: put the task under a ## Project heading'):format(lnum)
        end
        item.lnum, item.project_id = lnum, project
        while #stack > 0 and stack[#stack].indent >= item.indent do table.remove(stack) end
        item.parent = stack[#stack] and stack[#stack].item or nil
        table.insert(stack, { indent = item.indent, item = item })
        -- The same id twice means a copied line: the copy is a new task.
        if item.id and (seen[item.id] or not state.snapshot[item.id]) then item.id = nil end
        if item.id then seen[item.id] = true end
        table.insert(items, item)
      end
    end
  end
  return items, nil, seen
end

--- Work out the API calls, in an order that respects dependencies: creates
--- first and top-down (a new subtask needs its new parent's id), then edits,
--- moves, completions, and deletes last.
local function plan(items, seen)
  local ops = { create = {}, update = {}, move = {}, close = {}, reopen = {}, delete = {} }

  for _, item in ipairs(items) do
    local s = item.id and state.snapshot[item.id]
    if not s then
      table.insert(ops.create, item)
    else
      local changes = {}
      if item.content ~= s.content then changes.content = item.content end
      if item.due ~= s.due then changes.due_string = item.due ~= '' and item.due or 'no date' end
      if item.priority ~= s.priority then changes.priority = item.priority end
      if next(changes) then table.insert(ops.update, { item = item, body = changes }) end

      -- Compared with the parent as shown, so a subtask whose real parent is
      -- filtered out of this view is not "moved" to the top level.
      local parent_changed = (item.parent ~= nil) ~= (s.parent_id ~= nil)
        or (item.parent and item.parent.id ~= s.parent_id)
      if parent_changed or (not item.parent and item.project_id ~= s.project_id) then
        table.insert(ops.move, item)
      end

      if item.checked and not s.checked then table.insert(ops.close, item) end
      if not item.checked and s.checked then table.insert(ops.reopen, item) end
    end
  end

  -- Deleting a parent deletes its subtasks, so only the top of each deleted
  -- branch is sent; a separate call for a child would fail with 404.
  for id, s in pairs(state.snapshot) do
    if not seen[id] and not (s.parent_id and not seen[s.parent_id]) then
      table.insert(ops.delete, { id = id, content = s.content })
    end
  end
  return ops
end

local function summary(ops)
  local parts = {}
  for _, key in ipairs({ 'create', 'update', 'move', 'close', 'reopen', 'delete' }) do
    if #ops[key] > 0 then
      local label = ({ close = 'complete' })[key] or key
      table.insert(parts, ('%s %d'):format(label, #ops[key]))
    end
  end
  return parts
end

--- Run the calls one after another (each may need an id the previous one
--- returned), then reload. Failures are collected and reported together.
--- `log` collects a history entry for every call that succeeded.
local function apply(ops, done, log)
  local calls, errors = {}, {}
  local project_name = function(id) return state.projects.by_id[id] or id end
  local function add(fn) table.insert(calls, fn) end

  for _, item in ipairs(ops.create) do
    add(function(next_call)
      local body = { content = item.content, project_id = item.project_id, priority = item.priority }
      if item.parent then
        if not item.parent.id then
          table.insert(errors, ('line %d: parent was not created'):format(item.lnum))
          return next_call()
        end
        body.parent_id = item.parent.id
      end
      if item.due ~= '' then body.due_string = item.due end
      request('POST', '/tasks', function(err, task)
        if err then
          table.insert(errors, ('create "%s": %s'):format(item.content, err))
        else
          item.id = task and task.id
          local extra = (item.due ~= '' and (' due:' .. item.due) or '') .. (item.priority > 1 and (' p' .. (5 - item.priority)) or '')
          table.insert(log, ('created · %s (%s)%s'):format(item.content, project_name(item.project_id), extra))
          if item.checked and item.id then
            table.insert(log, 'completed · ' .. item.content)
            return request('POST', '/tasks/' .. item.id .. '/close', function() next_call() end)
          end
        end
        next_call()
      end, body)
    end)
  end
  for _, u in ipairs(ops.update) do
    add(function(next_call)
      local was = state.snapshot[u.item.id] or {}
      request('POST', '/tasks/' .. u.item.id, function(err)
        if err then
          table.insert(errors, ('update "%s": %s'):format(u.item.content, err))
        else
          local diffs = {}
          if u.body.content then table.insert(diffs, ('text: "%s" → "%s"'):format(was.content or '?', u.body.content)) end
          if u.body.due_string then
            table.insert(diffs, ('due: %s → %s'):format((was.due or '') ~= '' and was.due or 'none', u.item.due ~= '' and u.item.due or 'none'))
          end
          if u.body.priority then table.insert(diffs, ('priority: p%d → p%d'):format(5 - (was.priority or 1), 5 - u.body.priority)) end
          table.insert(log, ('edited · %s · %s'):format(u.item.content, table.concat(diffs, '; ')))
        end
        next_call()
      end, u.body)
    end)
  end
  for _, item in ipairs(ops.move) do
    add(function(next_call)
      local body = item.parent and { parent_id = item.parent.id } or { project_id = item.project_id }
      request('POST', '/tasks/' .. item.id .. '/move', function(err)
        if err then
          table.insert(errors, ('move "%s": %s'):format(item.content, err))
        else
          table.insert(log, item.parent and ('moved · %s → under "%s"'):format(item.content, item.parent.content)
            or ('moved · %s → %s'):format(item.content, project_name(item.project_id)))
        end
        next_call()
      end, body)
    end)
  end
  for key, action in pairs({ close = 'close', reopen = 'reopen' }) do
    for _, item in ipairs(ops[key]) do
      add(function(next_call)
        request('POST', '/tasks/' .. item.id .. '/' .. action, function(err)
          if err then
            table.insert(errors, ('%s "%s": %s'):format(action, item.content, err))
          else
            table.insert(log, (action == 'close' and 'completed · ' or 'reopened · ') .. item.content)
          end
          next_call()
        end)
      end)
    end
  end
  for _, d in ipairs(ops.delete) do
    add(function(next_call)
      request('DELETE', '/tasks/' .. d.id, function(err)
        if err then
          table.insert(errors, ('delete "%s": %s'):format(d.content, err))
        else
          table.insert(log, 'deleted · ' .. d.content)
        end
        next_call()
      end)
    end)
  end

  local i = 0
  local function next_call()
    i = i + 1
    if calls[i] then return calls[i](next_call) end
    done(errors)
  end
  next_call()
end

--- :w on the task buffer.
function M.save()
  local buf = state.buf
  if state.saving then return vim.notify('Still saving the previous changes', vim.log.levels.WARN) end

  local items, err, seen = collect(buf)
  if not items then return vim.notify('Todoist: ' .. err, vim.log.levels.ERROR) end

  local ops = plan(items, seen)
  local parts = summary(ops)
  if #parts == 0 then
    -- Nothing for Todoist, but a [~] / [!] / [>] / [-] may have changed.
    vim.bo[buf].modified = false
    local changed, entries = saveStates(items)
    archive.log(entries)
    return vim.notify(changed and 'Todoist: checkbox states saved (kept locally)' or 'Todoist: no changes')
  end

  -- vim.g.pure_todoist_confirm: 'all' (default) asks before every save,
  -- 'delete' only when tasks would be deleted, 'never' does not ask.
  local mode = vim.g.pure_todoist_confirm or 'all'
  if mode == 'all' or (mode == 'delete' and #ops.delete > 0) then
    -- Deletes are named: they are the one change that cannot be undone here.
    local question = 'Apply to Todoist: ' .. table.concat(parts, ', ') .. '?'
    if #ops.delete > 0 then
      local names = {}
      for _, d in ipairs(ops.delete) do table.insert(names, '  - ' .. d.content) end
      question = question .. '\n\nDeleting:\n' .. table.concat(names, '\n')
    end
    -- What <CR> answers: Yes for creates and edits, No when something would
    -- be deleted, so a reflexive Enter never deletes a task. (It used to be
    -- No always, and a save confirmed with Enter silently did nothing.)
    local default = #ops.delete > 0 and 2 or 1
    if vim.fn.confirm(question, '&Yes\n&No', default) ~= 1 then
      return vim.notify('Todoist: nothing sent; the edits are still in the buffer')
    end
  end

  state.saving = true
  vim.notify('Todoist: saving…')
  local log = {}
  apply(ops, function(errors)
    state.saving = false
    -- After apply, so new tasks have their ids; before the reload draws them.
    local deleted_ids = {}
    for _, d in ipairs(ops.delete) do table.insert(deleted_ids, d.id) end
    local _, mark_entries = saveStates(items, deleted_ids)
    vim.list_extend(log, mark_entries)
    archive.log(log)
    -- The reload below brings our own changes back; they are logged already.
    archive.skip_external = true
    if #errors > 0 then
      vim.notify('Todoist: some changes failed:\n' .. table.concat(errors, '\n'), vim.log.levels.ERROR)
    else
      local msg = 'Todoist: ' .. table.concat(parts, ', ')
      for _, item in ipairs(ops.create) do
        if item.id then msg = msg .. '\n  + ' .. item.content end
      end
      vim.notify(msg)
    end
    M.reload(function(tasks)
      -- A task created in a filtered view (say, with no date under "today")
      -- exists in Todoist but drops out on reload; say so, or it looks lost.
      local listed = {}
      for _, t in ipairs(tasks) do listed[t.id] = true end
      local hidden = {}
      for _, item in ipairs(ops.create) do
        if item.id and not listed[item.id] then table.insert(hidden, '  ' .. item.content) end
      end
      if #hidden > 0 then
        vim.notify(('Created in Todoist but not listed, as it does not match "%s":\n%s')
          :format(state.filter or '', table.concat(hidden, '\n')), vim.log.levels.WARN)
      end
    end)
    M.refreshBlocks()
  end, log)
end

--- Run `fn` now, or after confirming that unsaved edits may be dropped.
local function unlessModified(what, fn)
  return function()
    if vim.bo[state.buf].modified and vim.fn.confirm(
          'Discard unsaved Todoist changes and ' .. what .. '?', '&Discard\n&Cancel', 2) ~= 1 then
      return
    end
    fn()
  end
end

--- Open the task list for `filter`. `float` = { win, row, title } shows it
--- in a floating window over that row of `win` (a ```todoist block) instead
--- of a split.
function M.open(filter, float)
  filter = (filter and filter ~= '') and filter or nil
  local key = filter or ''

  -- Switching filter redraws the buffer; unsaved edits would be lost.
  if state.buf and vim.api.nvim_buf_is_valid(state.buf) and state.loaded ~= key
      and vim.bo[state.buf].modified
      and vim.fn.confirm('Discard unsaved Todoist changes and open "' .. (filter or 'all') .. '"?',
        '&Discard\n&Cancel', 2) ~= 1 then
    return
  end
  state.filter = filter

  if not (state.buf and vim.api.nvim_buf_is_valid(state.buf)) then
    local buf = vim.api.nvim_create_buf(false, false)
    state.buf = buf
    -- acwrite: :w runs BufWriteCmd below instead of writing a file.
    vim.bo[buf].buftype = 'acwrite'
    vim.bo[buf].bufhidden = 'hide'
    vim.bo[buf].swapfile = false
    pcall(vim.api.nvim_buf_set_name, buf, 'todoist://tasks')
    -- mdview only draws in normal file buffers; this one opts in explicitly.
    vim.b[buf].pure_mdview = true
    vim.bo[buf].filetype = 'markdown'
    -- render-md.lua sets a textwidth for markdown, which would wrap long task
    -- lines into two while typing -- and the second half would be a new task.
    vim.bo[buf].textwidth = 0

    vim.api.nvim_create_autocmd('BufWriteCmd', { buffer = buf, callback = M.save })
    vim.api.nvim_create_autocmd({ 'TextChanged', 'TextChangedI' }, {
      buffer = buf,
      callback = function() decorate(buf) end,
    })

    local map = function(lhs, fn, desc) vim.keymap.set('n', lhs, fn, { buffer = buf, desc = desc }) end
    local close = unlessModified('close', function()
      -- Discarded edits are still in the (hidden) buffer: draw it afresh
      -- next time rather than showing them again.
      if vim.bo[buf].modified then state.loaded = nil end
      vim.bo[buf].modified = false
      if #vim.api.nvim_list_wins() > 1 then vim.cmd('close') else vim.cmd('bprevious') end
      -- Opened from a block: redraw the blocks with what was just sent.
      if state.from_block then
        state.from_block = false
        M.refreshBlocks()
      end
    end)
    -- The same toggle as <leader>tx in notes; the change is sent on :w.
    -- On a [[link]] (in a task's text) follow it; else toggle the task.
    map('<CR>', function()
      if not require('pure.notes').follow() then require('configs.functions').toggleCheckbox() end
    end, 'Follow link / toggle task checkbox')
    -- In this buffer only, x ticks the box instead of deleting a character.
    map('x', require('configs.functions').toggleCheckbox, 'Toggle task checkbox')
    -- Obsidian's states, as in notes; only [x] reaches Todoist, the others
    -- are kept locally (see states_file).
    map('<leader>x', require('configs.functions').cycleCheckbox, 'Cycle checkbox state')
    map('r', unlessModified('reload', M.reload), 'Reload tasks')
    map('q', close, 'Close Todoist')
    map('<Esc>', close, 'Close Todoist')
  end

  local win = vim.fn.bufwinid(state.buf)
  state.from_block = float ~= nil
  if win ~= -1 then
    vim.api.nvim_set_current_win(win)
  elseif float then
    local width = vim.api.nvim_win_get_width(float.win)
    vim.api.nvim_open_win(state.buf, true, {
      relative = 'win',
      win = float.win,
      bufpos = { float.row, 0 },
      row = 0,
      col = 0,
      width = math.max(20, width - 4),
      height = math.max(5, math.floor(vim.api.nvim_win_get_height(float.win) * 0.6)),
      title = ' ' .. float.title .. ' ',
      title_pos = 'left',
      footer = ' x done · :w send · q close ',
      footer_pos = 'right',
    })
  else
    vim.cmd('botright split')
    vim.api.nvim_win_set_buf(0, state.buf)
  end
  -- Window options: render-md.lua turns spell on for markdown (task names are
  -- not prose worth underlining), and the ids need conceal to stay hidden.
  vim.wo.spell = false
  vim.wo.wrap = false
  vim.wo.conceallevel = 2
  vim.wo.concealcursor = 'nc'

  -- Same filter as what the buffer holds: just show it, no network.
  if state.loaded == key then return end
  local ready = prefetched[key]
  prefetched[key] = nil
  if ready then
    render(ready.tasks, ready.projects)
    state.loaded = key
  else
    M.reload()
  end
end

-- -----------------------------------------------------------------------------
--  Blocks in notes
-- -----------------------------------------------------------------------------
--  A fenced block in any markdown file, in the syntax of Obsidian's Todoist
--  plugin, so the same note works in both:
--
--    ```todoist
--    name: Today
--    filter: "today | overdue"
--    ```
--
--  The tasks are drawn in place of the block as virtual lines (mdview hides
--  the query until the cursor moves into it); the file keeps only the query.
--  They load when the note is shown and are cached for a few minutes;
--  :TodoistRefresh reloads them. <CR> (or :Todoist) with the cursor inside
--  a block opens that filter as the interactive list in a floating window
--  over it: go through the tasks, x to complete, :w to send, q to close.
--  The plugin's older JSON form ({"name": ..., "filter": ...}) is read too.

local block_ns = vim.api.nvim_create_namespace('pure_todoist_block')
local cache_ttl = 5 * 60 -- seconds
local cache = {}         -- filter ('' for all) -> { time, tasks?, err?, loading? }
local project_cache = { time = 0, names = {} }

--- `key: value` lines, values optionally quoted. Only name and filter are
--- used; the Obsidian plugin's other keys (sorting, groupBy, ...) are ignored.
local function parseBlockBody(lines)
  local text = vim.trim(table.concat(lines, '\n'))
  if text:sub(1, 1) == '{' then
    -- luanil: a JSON null must become nil, not vim.NIL (which is truthy).
    local ok, obj = pcall(vim.json.decode, text, { luanil = { object = true, array = true } })
    if ok and type(obj) == 'table' then
      local str = function(v) return type(v) == 'string' and v or nil end
      return { name = str(obj.name), filter = str(obj.filter) }
    end
  end
  local conf = {}
  for _, line in ipairs(lines) do
    local key, value = line:match('^%s*([%w_]+)%s*:%s*(.-)%s*$')
    if key then
      conf[key] = value:match('^"(.*)"$') or value:match("^'(.*)'$") or value
    end
  end
  return { name = conf.name, filter = conf.filter }
end

--- Every ```todoist block in `lines`: { first, last (0-based fence rows), name, filter }.
local function blocksIn(lines)
  local blocks, i = {}, 1
  while i <= #lines do
    if lines[i]:match('^%s*```%s*todoist%s*$') then
      local j = i + 1
      while j <= #lines and not lines[j]:match('^%s*```%s*$') do j = j + 1 end
      local conf = parseBlockBody(vim.list_slice(lines, i + 1, j - 1))
      conf.first, conf.last = i - 1, math.min(j, #lines) - 1
      table.insert(blocks, conf)
      i = j + 1
    else
      i = i + 1
    end
  end
  return blocks
end

local function findBlocks(buf)
  return blocksIn(vim.api.nvim_buf_get_lines(buf, 0, -1, false))
end

local function blockAt(buf, row)
  for _, b in ipairs(findBlocks(buf)) do
    if row >= b.first and row <= b.last then return b end
  end
end

--- Load `filter` into the cache unless it is fresh or already loading, then
--- call `on_done` (used to redraw).
local function load(filter, on_done)
  local key = filter or ''
  local entry = cache[key]
  if entry and (entry.loading or os.time() - entry.time < cache_ttl) then return end
  cache[key] = { time = os.time(), loading = true, tasks = entry and entry.tasks }

  local path = filter and ('/tasks/filter?query=' .. urlencode(filter)) or '/tasks'
  getAll(path, function(err, tasks)
    local function done()
      cache[key] = { time = os.time(), tasks = tasks, err = err }
      on_done()
    end
    if err or os.time() - project_cache.time < cache_ttl then return done() end
    getAll('/projects', function(_, projects)
      project_cache = { time = os.time(), names = {} }
      for _, p in ipairs(projects or {}) do project_cache.names[p.id] = p.name end
      done()
    end)
  end)
end

local priority_hl = { [4] = 'PureTodoistP1', [3] = 'PureTodoistP2', [2] = 'PureTodoistP3' }

--- The virtual lines for one block: a header, one line per task, a footer.
local function blockLines(block, entry, width)
  local title = block.name or block.filter or 'Todoist'
  local lines = {}
  local function add(chunks) table.insert(lines, chunks) end

  if not entry or (entry.loading and not entry.tasks) then
    add({ { '  󰔟 ' .. title .. ' · loading…', 'Comment' } })
    return lines
  end
  if entry.err then
    add({ { '  ' .. title .. ': ' .. entry.err, 'DiagnosticWarn' } })
    return lines
  end

  local tasks = vim.deepcopy(entry.tasks or {})
  sortTasks(tasks)
  add({ { '╭─ ', 'Comment' }, { title, 'Title' }, { (' (%d)'):format(#tasks), 'Comment' } })
  if #tasks == 0 then
    add({ { '│ ', 'Comment' }, { 'Nothing to do.', 'Comment' } })
  end

  -- Task text padded to a common width so project and due line up.
  local name_width = 10
  for _, t in ipairs(tasks) do
    name_width = math.max(name_width, vim.fn.strdisplaywidth((t.parent_id and '↳ ' or '') .. t.content))
  end
  name_width = math.min(name_width, math.max(width - 40, 20))

  for _, t in ipairs(tasks) do
    local text = (t.parent_id and '↳ ' or '') .. t.content:gsub('\n', ' ')
    if vim.fn.strdisplaywidth(text) > name_width then
      text = vim.fn.strcharpart(text, 0, name_width - 1) .. '…'
    end
    text = text .. string.rep(' ', name_width - vim.fn.strdisplaywidth(text))
    local chunks = {
      { '│ ', 'Comment' },
      { t.checked and '󰄲 ' or '󰄱 ', t.checked and 'PureMdTaskDone' or 'PureMdTaskTodo' },
      { text, t.checked and 'Comment' or 'Normal' },
    }
    local project = project_cache.names[t.project_id]
    if project then table.insert(chunks, { '  ' .. project, 'Comment' }) end
    if t.due then table.insert(chunks, { '  ' .. (t.due.string or t.due.date), 'PureTodoistDue' }) end
    local p = tonumber(t.priority) or 1
    if p > 1 then table.insert(chunks, { '  ' .. priorityLabel(p), priority_hl[p] }) end
    add(chunks)
  end
  add({ { '╰─ ', 'Comment' }, { 'move into the block and <CR> to go through the tasks', 'Comment' } })
  return lines
end

--- Draw every block of `buf` from the cache, starting loads as needed.
function M.renderBlocks(buf)
  buf = (buf and buf ~= 0) and buf or vim.api.nvim_get_current_buf()
  if not vim.api.nvim_buf_is_valid(buf) then return end
  -- Only when there is something to clear: this runs on every edit.
  if #vim.api.nvim_buf_get_extmarks(buf, block_ns, 0, -1, { limit = 1 }) > 0 then
    vim.api.nvim_buf_clear_namespace(buf, block_ns, 0, -1)
  end
  -- Written into the note as text instead (see "Sync into notes").
  if vim.g.pure_todoist_sync then return end

  local blocks = findBlocks(buf)
  if #blocks == 0 then return end

  local win = vim.fn.bufwinid(buf)
  local width = win ~= -1 and vim.api.nvim_win_get_width(win) or 80

  for _, block in ipairs(blocks) do
    if block.filter and block.filter:find('{{', 1, true) then
      -- A template's block ({{start-1:MMM D}}...): not a filter until the
      -- template is expanded into a note, and Todoist rejects it as it is.
      cache[block.filter] = { time = 0, err = 'template placeholders, filled in when a note is made from it' }
    elseif not token() then
      cache[block.filter or ''] = { time = 0, err = 'no token, run :TodoistToken' }
    else
      load(block.filter, function() M.renderBlocks(buf) end)
    end
    -- pure/mdview.lua hides the block's lines (see M.hiddenBlocks), and
    -- virtual lines hung on a hidden line are hidden with it: hang them above
    -- the line after the block, or below the one before it.
    local count = vim.api.nvim_buf_line_count(buf)
    local row, above = block.last, false
    if block.last + 1 < count then
      row, above = block.last + 1, true
    elseif block.first > 0 then
      row = block.first - 1
    end
    vim.api.nvim_buf_set_extmark(buf, block_ns, row, 0, {
      virt_lines = blockLines(block, cache[block.filter or ''], width),
      virt_lines_above = above,
    })
  end
end

--- { first, last } rows of the blocks pure/mdview.lua may hide: those with a
--- line before or after them to hang the tasks on.
local regionOf -- in "Sync into notes" below

--- With syncing on, the region's two markers are hidden too, leaving only the
--- tasks.
function M.hiddenBlocks(buf)
  local ranges = {}
  local lines = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
  local synced = vim.g.pure_todoist_sync and true or false
  for _, b in ipairs(blocksIn(lines)) do
    local region = synced and regionOf(lines, b)
    if region then
      table.insert(ranges, { b.first, region.first })
      table.insert(ranges, { region.last, region.last })
    elseif synced or b.last + 1 < #lines or b.first > 0 then
      table.insert(ranges, { b.first, b.last })
    end
  end
  return ranges
end

--- With the cursor in a ```todoist block, open its tasks in a floating
--- window over it, to go through them line by line. False elsewhere.
function M.openBlock()
  local buf = vim.api.nvim_get_current_buf()
  local block = blockAt(buf, vim.fn.line('.') - 1)
  if not block then return false end
  M.open(block.filter, {
    win = vim.api.nvim_get_current_win(),
    row = block.first,
    title = block.name or block.filter or 'Todoist',
  })
  return true
end

--- <CR> in notes: the block's tasks inside a block, else `fallback()`.
function M.enter(fallback)
  if M.openBlock() then return end
  fallback()
end

--- Reload every block in every loaded markdown buffer.
function M.refreshBlocks()
  cache = {}
  project_cache.time = 0
  for _, buf in ipairs(vim.api.nvim_list_bufs()) do
    if vim.api.nvim_buf_is_loaded(buf) and vim.bo[buf].filetype == 'markdown' then
      M.renderBlocks(buf)
    end
  end
end

local block_group = vim.api.nvim_create_augroup('PureTodoistBlocks', { clear = true })
vim.api.nvim_create_autocmd({ 'BufWinEnter', 'InsertLeave', 'TextChanged' }, {
  group = block_group,
  pattern = { '*.md', '*.markdown' },
  callback = function(args) M.renderBlocks(args.buf) end,
})

-- <CR> inside a block opens its tasks: pure/notes.lua maps <CR> in markdown
-- and asks M.openBlock first.

vim.api.nvim_create_user_command('TodoistRefresh', M.refreshBlocks, {
  desc = 'Reload the ```todoist blocks in open notes',
})


-- -----------------------------------------------------------------------------
--  Sync into notes
-- -----------------------------------------------------------------------------
--  With vim.g.pure_todoist_sync on, the tasks of each ```todoist block are
--  written into its note as a real task list, right under the block and
--  between two markers (HTML comments, which Obsidian does not show):
--
--    ```todoist
--    filter: "today | overdue"
--    ```
--    <!-- todoist -->
--    - [ ] [Write the README](https://app.todoist.com/app/task/123) · 2026-09-25 · P1 · Work
--      - [ ] [Sub step](https://app.todoist.com/app/task/124) · 2026-09-26 · Work
--    <!-- /todoist -->
--
--  Only the lines between the markers are ever rewritten, and only when they
--  would change; the rest of the note is never touched. Ticking a box there
--  ([x], in Neovim or in Obsidian) completes the task in Todoist on the next
--  sync. Any other edit between the markers is overwritten by the next sync.
--
--  When: at startup, every `interval` minutes, and when a note with a block
--  is opened or saved. Which notes: those of the vault that hold a block
--  (not the templates, the trash or hidden folders), and any other open note
--  with one. A note named after a date (a daily, 2026-09-24) is only updated
--  on that day, so past dailies keep the list they had. A note open with
--  unsaved changes is left alone until it is saved.
--
--    vim.g.pure_todoist_sync = { interval = 10 }  on, every 10 minutes
--    vim.g.pure_todoist_sync = true                on, every 10 minutes
--    vim.g.pure_todoist_sync = false (or unset)    off: the tasks are drawn
--                                                  as virtual lines instead

local sync_begin, sync_end = '<!-- todoist -->', '<!-- /todoist -->'
local task_url = 'https://app.todoist.com/app/task/'

--- The sync settings, or nil when syncing is off.
local function syncConfig()
  local c = vim.g.pure_todoist_sync
  if c == true then return { interval = 10 } end
  if type(c) == 'table' then return { interval = tonumber(c.interval) or 10 } end
end

--- The region under `block`: 0-based rows of its two markers. `false` when
--- the begin marker is there without an end marker (left alone, to never
--- eat the rest of the note), nil when there is none yet.
function regionOf(lines, block)
  local row = block.last + 1
  if vim.trim(lines[row + 1] or '') ~= sync_begin then return nil end
  for r = row + 1, #lines - 1 do
    local text = vim.trim(lines[r + 1])
    if text == sync_end then return { first = row, last = r } end
    if text == sync_begin or text:match('^```') then break end
  end
  return false
end

--- One task as a line of the region.
--- A task as the region shows it: text, due, priority (4 = P1), project
--- name. Also what the baseline remembers, to tell edits made in a note.
local function taskFields(t, projects)
  return {
    c = oneLine(t.content),
    -- The date itself: a phrase like "today" stops being true the next day.
    -- Recurring tasks keep theirs ("every monday").
    d = t.due and (t.due.is_recurring and t.due.string or t.due.date) or '',
    p = tonumber(t.priority) or 1,
    j = projects[t.project_id] or '',
  }
end

--- One task as a line of the region.
local function syncLine(t, depth, projects)
  local f = taskFields(t, projects)
  local parts
  if f.c:find('[[', 1, true) then
    -- A [[wikilink]] in the task: a link cannot sit inside another link's
    -- text, so the task is written as it is and the link to Todoist is an
    -- arrow after it. The [[note]] then works in Obsidian and with <CR>.
    parts = { ('%s- [ ] %s [↗](%s%s)'):format(string.rep('  ', depth), f.c, task_url, t.id) }
  else
    parts = { ('%s- [ ] [%s](%s%s)'):format(string.rep('  ', depth), (f.c:gsub('([%[%]])', '\\%1')), task_url, t.id) }
  end
  if f.d ~= '' then table.insert(parts, f.d) end
  if priorityLabel(f.p) ~= '' then table.insert(parts, priorityLabel(f.p)) end
  if f.j ~= '' then table.insert(parts, f.j) end
  return table.concat(parts, ' · ')
end

--- The region's lines, markers included: subtasks indented under their
--- parent when the parent is in the list too.
local function regionLines(tasks, projects)
  local list = vim.deepcopy(tasks or {})
  sortTasks(list)
  local present, children = {}, {}
  for _, t in ipairs(list) do present[t.id] = true end
  for _, t in ipairs(list) do
    if t.parent_id and present[t.parent_id] then
      children[t.parent_id] = children[t.parent_id] or {}
      table.insert(children[t.parent_id], t)
    end
  end

  local out = { sync_begin }
  local function add(t, depth)
    table.insert(out, syncLine(t, depth, projects))
    for _, c in ipairs(children[t.id] or {}) do add(c, depth + 1) end
  end
  for _, t in ipairs(list) do
    if not (t.parent_id and present[t.parent_id]) then add(t, 0) end
  end
  if #out == 1 then table.insert(out, '*Nothing to do.*') end
  table.insert(out, sync_end)
  return out
end

-- Baseline: what the last sync wrote into each region, kept in
-- stdpath('data')/todoist_sync.json. A line that differs from it was edited
-- in the note (in Neovim or Obsidian) and is sent to Todoist; a line that
-- still matches it just takes whatever Todoist now says.
local baseline_file = vim.fn.stdpath('data') .. '/todoist_sync.json'
local baseline

local function loadBaseline()
  if baseline then return baseline end
  local ok, data = pcall(function()
    return vim.json.decode(table.concat(vim.fn.readfile(baseline_file), '\n'))
  end)
  baseline = (ok and type(data) == 'table') and data or {}
  baseline.tasks = type(baseline.tasks) == 'table' and baseline.tasks or {}     -- id -> fields
  baseline.regions = type(baseline.regions) == 'table' and baseline.regions or {} -- key -> { ids }
  return baseline
end

--- Save, keeping only the tasks some region still lists.
local function saveBaseline()
  if not baseline then return end
  local used = {}
  for _, ids in pairs(baseline.regions) do
    for _, id in ipairs(ids) do used[id] = baseline.tasks[id] end
  end
  baseline.tasks = used
  pcall(vim.fn.writefile, { vim.json.encode(baseline) }, baseline_file)
end

local function regionKey(path, block)
  return vim.fs.normalize(path) .. '\n' .. (block.filter or '')
end

--- A task line of a region, parsed: { depth, checked, id?, c, d, p, j? }.
--- " · " parts after the text: P1..P3 is the priority, a project's name the
--- project, anything else the due date (any Todoist phrase: "tomorrow").
local function parseItem(line, by_name)
  local indent, mark, rest = line:match('^(%s*)[-*] %[(.)%] ?(.*)$')
  if not indent then return nil end
  local item = { depth = #(indent:gsub('\t', '  ')), checked = mark == 'x' or mark == 'X', d = '', p = 1 }
  local text, id, tail = rest:match('^%[(.-)%]%(' .. vim.pesc(task_url) .. '([%w_]+)%)(.*)$')
  local plain, pid, ptail = rest:match('^(.-)%s*%[↗%]%(' .. vim.pesc(task_url) .. '([%w_]+)%)(.*)$')
  if plain and (not text or plain:find('[[', 1, true)) then
    -- "text with [[links]] [↗](url)": see syncLine.
    item.id, item.c, tail = pid, vim.trim(plain), ptail
  elseif text then
    item.id, item.c = id, (text:gsub('\\([%[%]])', '%1'))
  else
    local cut = rest:find(' · ', 1, true)
    item.c = vim.trim(cut and rest:sub(1, cut - 1) or rest)
    tail = cut and rest:sub(cut) or ''
  end
  for _, part in ipairs(vim.split(tail, ' · ', { plain = true })) do
    part = vim.trim(part)
    local n = part:match('^[Pp]([1-3])$')
    if n then
      item.p = 5 - tonumber(n)
    elseif by_name[part] then
      item.j = part
    elseif part ~= '' and item.d == '' then
      item.d = part
    end
  end
  return item
end

--- What was changed in a region since the last sync, added to `ops`:
--- close (ticked), update (text, due, priority), move (project), create (new
--- lines, under the line above when indented) and `missing` (ids the last
--- sync wrote here that are gone: deleted, unless seen in another note).
local function regionOps(lines, region, key, by_name, ops)
  local base = loadBaseline()
  local here, stack = {}, {}
  for r = region.first + 1, region.last - 1 do
    local item = parseItem(lines[r + 1] or '', by_name)
    if item then
      while #stack > 0 and stack[#stack].depth >= item.depth do table.remove(stack) end
      local parent = stack[#stack]
      if item.id then
        here[item.id] = true
        ops.seen[item.id] = true
        local was = base.tasks[item.id]
        if item.checked then
          table.insert(ops.close, item)
        elseif was then
          local body = {}
          if item.c ~= '' and item.c ~= was.c then body.content = item.c end
          if item.d ~= was.d then body.due_string = item.d ~= '' and item.d or 'no date' end
          if item.p ~= was.p then body.priority = item.p end
          if next(body) then table.insert(ops.update, { item = item, body = body }) end
          if item.j and item.j ~= was.j then
            table.insert(ops.move, { item = item, project_id = by_name[item.j] })
          end
        end
      elseif item.c ~= '' and not item.checked then
        table.insert(ops.create, { item = item, parent_id = parent and parent.id })
      end
      table.insert(stack, item)
    end
  end
  for _, id in ipairs(base.regions[key] or {}) do
    if not here[id] then ops.missing[id] = true end
  end
end

--- A note named after a date other than today (a past or future daily).
local function frozen(path)
  local y, m, d = vim.fs.basename(path):match('(%d%d%d%d)%-(%d%d)%-(%d%d)')
  return y ~= nil and (y .. '-' .. m .. '-' .. d) ~= os.date('%Y-%m-%d')
end

local function bufferOf(path)
  path = vim.fs.normalize(path)
  for _, buf in ipairs(vim.api.nvim_list_bufs()) do
    if vim.api.nvim_buf_is_loaded(buf) and vim.fs.normalize(vim.api.nvim_buf_get_name(buf)) == path then
      return buf
    end
  end
end

--- Whether the note at `path` may be synced. Never the templates: their blocks
--- hold placeholders such as {{start-1:MMM D}} that only become a filter once
--- the template is expanded, and tasks written into a template are copied
--- into every note made from it afterwards. Never the trash either. This is
--- checked for every note, not only the vault search: opening or saving a
--- template in a window used to sync it too.
local function syncable(path)
  local ok_z, zet = pcall(require, 'pure.zettelkasten')
  local vault = ok_z and zet.vaultPath() or nil
  if not vault then return true end
  local function key(p)
    p = vim.fs.normalize(p)
    return vim.fn.has('win32') == 1 and p:lower() or p
  end
  local note = key(path)
  local folders = {
    zet.templatesPath and zet.templatesPath() or (vault .. '/' .. (vim.g.pure_templates or 'Templates')),
    vault .. '/' .. ((zet._destinations or {}).Delete or '0-Inbox/Trash'),
  }
  for _, folder in ipairs(folders) do
    local f = key(folder)
    if note:sub(1, #f + 1) == f .. '/' then return false end
  end
  return true
end

--- The note's lines and its buffer, if loaded. nil while it has unsaved
--- changes: those are never overwritten. The third value is true when the
--- note's lines end in CRLF.
local function noteLines(path)
  local buf = bufferOf(path)
  if buf then
    if vim.bo[buf].modified then return nil end
    return vim.api.nvim_buf_get_lines(buf, 0, -1, false), buf
  end
  -- 'b' keeps the file byte for byte, final newline or not. In a CRLF note
  -- every line then ends in '\r': it is taken off here and put back when the
  -- note is written. Before, the task lines went in without it, the note ended
  -- up mixing both endings, and Neovim showed ^M on all the other lines.
  local ok, lines = pcall(vim.fn.readfile, path, 'b')
  if not ok then return nil end
  local cr = 0
  for i = 1, #lines - 1 do
    if lines[i]:sub(-1) == '\r' then cr = cr + 1 end
  end
  for i, l in ipairs(lines) do
    if l:sub(-1) == '\r' then lines[i] = l:sub(1, -2) end
  end
  -- The ending most lines use wins, so a note that is already mixed comes out
  -- consistent the next time it is written.
  return lines, nil, cr > (#lines - 1) / 2
end

--- Rewrite the regions of one note that changed.
local function syncNote(path, fetched, projects)
  local lines, buf, crlf = noteLines(path)
  if not lines then return end
  local edits = {}
  local blocks = blocksIn(lines)
  -- Bottom up, so the rows of the blocks above stay valid while editing.
  for i = #blocks, 1, -1 do
    local b = blocks[i]
    local region = regionOf(lines, b)
    local new = fetched[b.filter or '']
    if region ~= false and new then
      -- Remember what this region now holds (see "Baseline").
      local base, ids = loadBaseline(), {}
      for _, t in ipairs(new) do
        base.tasks[t.id] = taskFields(t, projects)
        table.insert(ids, t.id)
      end
      base.regions[regionKey(path, b)] = ids
      local s, e = b.last + 1, b.last + 1
      if region then s, e = region.first, region.last + 1 end
      new = regionLines(new, projects)
      if not vim.deep_equal(vim.list_slice(lines, s + 1, e), new) then
        table.insert(edits, { s, e, new })
      end
    end
  end
  if #edits == 0 then return end

  if buf then
    for _, ed in ipairs(edits) do vim.api.nvim_buf_set_lines(buf, ed[1], ed[2], false, ed[3]) end
    -- noautocmd: this write must not trigger another sync.
    vim.api.nvim_buf_call(buf, function() vim.cmd('silent noautocmd update') end)
  else
    for _, ed in ipairs(edits) do
      for _ = ed[1] + 1, ed[2] do table.remove(lines, ed[1] + 1) end
      for k, l in ipairs(ed[3]) do table.insert(lines, ed[1] + k, l) end
    end
    if crlf then
      -- The last item is empty when the note ends in a newline: that one is
      -- the newline itself, not a line.
      for i, l in ipairs(lines) do
        if not (i == #lines and l == '') then lines[i] = l .. '\r' end
      end
    end
    vim.fn.writefile(lines, path, 'b')
  end
end

--- The notes to sync: `paths`, or every note of the vault with a block plus
--- the open ones that have one. `cb(paths)`.
local function notesToSync(paths, cb)
  if paths then return cb(paths) end
  local found, seen = {}, {}
  local function add(p)
    p = vim.fs.normalize(p)
    if not seen[p] then seen[p] = true table.insert(found, p) end
  end
  for _, buf in ipairs(vim.api.nvim_list_bufs()) do
    local name = vim.api.nvim_buf_get_name(buf)
    if vim.api.nvim_buf_is_loaded(buf) and name:match('%.md$') and #findBlocks(buf) > 0 then add(name) end
  end

  local ok_z, zet = pcall(require, 'pure.zettelkasten')
  local vault = ok_z and zet.vaultPath() or nil
  if not vault then return cb(found) end
  local templates = vim.g.pure_templates or 'Templates'
  local trash = (zet._destinations or {}).Delete or '0-Inbox/Trash'
  -- ripgrep skips hidden folders (.obsidian, .trash) on its own.
  local ok = pcall(vim.system, {
    'rg', '-l', '--glob', '*.md', '--glob', '!' .. templates .. '/**', '--glob', '!' .. trash .. '/**',
    '-e', [[^\s*```\s*todoist\s*$]], vault,
  }, { text = true }, vim.schedule_wrap(function(res)
    for p in (res.stdout or ''):gmatch('[^\r\n]+') do add(p) end
    cb(found)
  end))
  if not ok then cb(found) end
end

local syncing = false
-- Asked for while a sync was running (a :w during the timer's sync): run
-- once more when it ends. `true` means every note.
local pending = nil

local function queue(paths)
  if pending == true or not paths then pending = true return end
  pending = pending or {}
  vim.list_extend(pending, paths)
end

--- Sync the notes at `paths` (all of them when nil): complete the tasks
--- ticked there, fetch every block's filter, rewrite the regions.
function M.sync(paths)
  if not syncConfig() or not token() then return end
  if syncing then return queue(paths) end
  syncing = true

  -- Always releases the lock, even after an error, and runs what was queued.
  local function finish(err)
    syncing = false
    if err then vim.notify('Todoist sync: ' .. err, vim.log.levels.WARN) end
    if pending then
      local next_paths = pending ~= true and pending or nil
      pending = nil
      M.sync(next_paths)
    end
  end

  local function run(files)
    local notes, filters = {}, {}
    for _, path in ipairs(files) do
      local lines = not frozen(path) and syncable(path) and noteLines(path)
      if lines then
        local blocks = blocksIn(lines)
        if #blocks > 0 then table.insert(notes, path) end
        for _, b in ipairs(blocks) do
          -- Placeholders left in a note are not a filter Todoist accepts.
          if not (b.filter and b.filter:find('{{', 1, true)) then
            filters[b.filter or ''] = b.filter or false
          end
        end
      end
    end
    if #notes == 0 then return finish() end

    local keys = vim.tbl_keys(filters)
    local fetched, projects, by_name, errors = {}, {}, {}, {}

    local function write()
      for _, path in ipairs(notes) do
        local ok, err = pcall(syncNote, path, fetched, projects)
        if not ok then table.insert(errors, path .. ': ' .. tostring(err)) end
      end
      saveBaseline()
      finish(#errors > 0 and table.concat(errors, '\n') or nil)
    end
    local function fetchNext(i)
      if i > #keys then return write() end
      local filter = filters[keys[i]] or nil
      local path = filter and ('/tasks/filter?query=' .. urlencode(filter)) or '/tasks'
      getAll(path, function(err, tasks)
        if err then table.insert(errors, err) else fetched[keys[i]] = tasks end
        fetchNext(i + 1)
      end)
    end

    --- The calls for what was changed in the notes, one after the other.
    local function send(ops)
      local calls = {}
      local function call(method, path, body, what)
        table.insert(calls, function(done)
          request(method, path, function(err)
            -- Already done or deleted in Todoist: nothing to report.
            if err and not err:match('HTTP 404') then table.insert(errors, what .. ': ' .. err) end
            done()
          end, body)
        end)
      end
      for _, item in ipairs(ops.close) do
        call('POST', '/tasks/' .. item.id .. '/close', nil, 'complete "' .. item.c .. '"')
      end
      for _, u in ipairs(ops.update) do
        call('POST', '/tasks/' .. u.item.id, u.body, 'edit "' .. u.item.c .. '"')
      end
      for _, m in ipairs(ops.move) do
        call('POST', '/tasks/' .. m.item.id .. '/move', { project_id = m.project_id }, 'move "' .. m.item.c .. '"')
      end
      for _, c in ipairs(ops.create) do
        local body = { content = c.item.c }
        if c.item.d ~= '' then body.due_string = c.item.d end
        if c.item.p > 1 then body.priority = c.item.p end
        if c.parent_id then
          body.parent_id = c.parent_id
        elseif c.item.j then
          body.project_id = by_name[c.item.j]
        end
        call('POST', '/tasks', body, 'create "' .. c.item.c .. '"')
      end
      for _, d in ipairs(ops.delete) do
        call('DELETE', '/tasks/' .. d.id, nil, 'delete "' .. d.c .. '"')
      end
      local function nextCall(i)
        if i > #calls then return fetchNext(1) end
        calls[i](function() nextCall(i + 1) end)
      end
      nextCall(1)
    end

    -- Project names first: a note line names its project by name.
    getAll('/projects', function(perr, list)
      if perr then table.insert(errors, perr) end
      for _, p in ipairs(list or {}) do
        projects[p.id] = p.name
        by_name[p.name] = p.id
      end

      local ops = { close = {}, update = {}, move = {}, create = {}, delete = {}, seen = {}, missing = {} }
      for _, path in ipairs(notes) do
        local lines = noteLines(path)
        for _, b in ipairs(lines and blocksIn(lines) or {}) do
          local region = regionOf(lines, b)
          if region then regionOps(lines, region, regionKey(path, b), by_name, ops) end
        end
      end
      -- Gone from one note but still in another: not deleted.
      for id in pairs(ops.missing) do
        if not ops.seen[id] then
          table.insert(ops.delete, { id = id, c = (loadBaseline().tasks[id] or {}).c or id })
        end
      end

      local total = #ops.close + #ops.update + #ops.move + #ops.create + #ops.delete
      local mode = vim.g.pure_todoist_confirm or 'all'
      local ask = #vim.api.nvim_list_uis() > 0
        and ((mode == 'all' and total > 0) or (mode == 'delete' and #ops.delete > 0))
      if ask then
        local lines = {}
        for _, c in ipairs(ops.create) do table.insert(lines, '+ ' .. c.item.c) end
        for _, u in ipairs(ops.update) do table.insert(lines, '~ ' .. u.item.c) end
        for _, m in ipairs(ops.move) do table.insert(lines, '→ ' .. m.item.c .. ' (' .. m.item.j .. ')') end
        for _, c in ipairs(ops.close) do table.insert(lines, '✓ ' .. c.c) end
        for _, d in ipairs(ops.delete) do table.insert(lines, '✗ ' .. d.c) end
        -- Enter is No when something would be deleted, as in the task list.
        local choice = vim.fn.confirm('Send these note edits to Todoist?\n' .. table.concat(lines, '\n'),
          '&Yes\n&No', #ops.delete > 0 and 2 or 1)
        -- Declined: the notes are rewritten from Todoist, undoing the edits.
        if choice ~= 1 then return fetchNext(1) end
      end
      send(ops)
    end)
  end

  notesToSync(paths, function(files)
    local ok, err = pcall(run, files)
    if not ok then finish(tostring(err)) end
  end)
end

do
  local group = vim.api.nvim_create_augroup('PureTodoistSync', { clear = true })
  local timer

  local function start()
    local config = syncConfig()
    if not config or timer then return end
    timer = vim.uv.new_timer()
    timer:start(3000, config.interval * 60 * 1000, vim.schedule_wrap(function() M.sync() end))
  end
  vim.api.nvim_create_autocmd('VimEnter', { group = group, callback = start })
  if vim.v.vim_did_enter == 1 then start() end

  vim.api.nvim_create_autocmd({ 'BufWinEnter', 'BufWritePost' }, {
    group = group,
    pattern = { '*.md', '*.markdown' },
    callback = function(args)
      if syncConfig() and #findBlocks(args.buf) > 0 then
        M.sync({ vim.api.nvim_buf_get_name(args.buf) })
      end
    end,
  })
  vim.api.nvim_create_user_command('TodoistSync', function() M.sync() end, {
    desc = 'Write the tasks of every ```todoist block into its note now',
  })
end

-- -----------------------------------------------------------------------------
--  Folds in the synced lists
-- -----------------------------------------------------------------------------
--  When a note with a synced list is shown in a window, the list starts
--  folded (the markdown folds of treesitter: a task with subtasks, and the
--  whole list):
--
--    vim.g.pure_todoist_fold = 'subtasks'  (default) each task with subtasks
--                                          shows as one line
--    vim.g.pure_todoist_fold = 'list'      the whole list shows as one line
--    vim.g.pure_todoist_fold = false       nothing is folded
--
--  Only once per window and note: folds opened by hand stay open, also
--  after a sync rewrites the list.

--- Close the folds of the synced lists of `buf` in `win`.
local function closeListFolds(win, buf)
  local mode = vim.g.pure_todoist_fold
  if mode == nil then mode = 'subtasks' end
  if not mode then return end
  local lines = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
  local indent = function(l) return #(l:match('^%s*')) end
  vim.api.nvim_win_call(win, function()
    for _, b in ipairs(blocksIn(lines)) do
      local region = regionOf(lines, b)
      if region and region.last - region.first > 1 then
        -- 1-based rows of the tasks; bottom up so the deepest close first.
        for row = region.last - 1, region.first + 2, -1 do
          local here, next_line = lines[row], lines[row + 1]
          if row + 1 < region.last + 1 and indent(next_line) > indent(here)
            and vim.fn.foldlevel(row) > 0 and vim.fn.foldclosed(row) == -1 then
            vim.cmd(row .. 'foldclose')
          end
        end
        local top = region.first + 2
        if mode == 'list' and vim.fn.foldlevel(top) > 0 then
          -- Closing inside a closed fold closes the one around it: the list.
          vim.cmd(top .. 'foldclose')
          if vim.fn.foldclosedend(top) < region.last then vim.cmd(top .. 'foldclose') end
        end
      end
    end
  end)
end

vim.api.nvim_create_autocmd('BufWinEnter', {
  group = vim.api.nvim_create_augroup('PureTodoistFolds', { clear = true }),
  pattern = { '*.md', '*.markdown' },
  callback = function(args)
    local win, buf = vim.api.nvim_get_current_win(), args.buf
    local seen = vim.w[win].pure_todoist_folded or {}
    if seen[tostring(buf)] then return end
    -- The treesitter folds are computed after the window shows the buffer:
    -- wait for them (a few tries) before closing.
    local tries = 0
    local function attempt()
      if not (vim.api.nvim_win_is_valid(win) and vim.api.nvim_win_get_buf(win) == buf) then return end
      local lines = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
      local has, ready = false, false
      for _, b in ipairs(blocksIn(lines)) do
        local region = regionOf(lines, b)
        if region and region.last - region.first > 1 then
          has = true
          ready = ready or vim.api.nvim_win_call(win, function()
            return vim.fn.foldlevel(region.first + 2) > 0
          end)
        end
      end
      if not has then return end
      tries = tries + 1
      if not ready and tries < 10 then return vim.defer_fn(attempt, 50) end
      closeListFolds(win, buf)
      seen[tostring(buf)] = true
      vim.w[win].pure_todoist_folded = seen
    end
    vim.schedule(attempt)
  end,
})

-- -----------------------------------------------------------------------------
--  Token setup
-- -----------------------------------------------------------------------------

--- Ask for the token with hidden input, save it to `token_file` and check it
--- against the API. Also turns the startup question back on.
function M.setToken()
  -- inputsecret shows '*' while typing and keeps the answer out of the
  -- command-line history, unlike input() or a :let.
  local ok, input = pcall(vim.fn.inputsecret, 'Todoist API token (empty to cancel): ')
  input = ok and vim.trim(input or '') or ''
  if input == '' then
    return vim.notify('Todoist token not changed')
  end
  if input:find('%s') then
    return vim.notify('That does not look like a token (it has spaces); nothing saved', vim.log.levels.WARN)
  end

  vim.fn.mkdir(vim.fn.stdpath('data'), 'p')
  local f, err = io.open(token_file, 'w')
  if not f then
    return vim.notify('Could not write ' .. token_file .. ': ' .. tostring(err), vim.log.levels.ERROR)
  end
  f:write(input, '\n')
  f:close()
  -- Owner read/write only (0600). Windows ignores the mode; its per-user
  -- AppData folder already keeps the file private.
  pcall(vim.uv.fs_chmod, token_file, tonumber('600', 8))
  os.remove(no_prompt_file)

  if vim.env.TODOIST_API_TOKEN and vim.env.TODOIST_API_TOKEN ~= '' then
    vim.notify('Saved, but TODOIST_API_TOKEN is set and takes precedence over the file', vim.log.levels.WARN)
  end

  -- One cheap request to tell a typo apart from a working token now, rather
  -- than on the first :Todoist.
  vim.notify('Todoist token saved, checking it…')
  request('GET', '/projects?limit=1', function(req_err)
    if req_err then
      vim.notify('Todoist rejected the token: ' .. req_err .. '\nRun :TodoistToken to try again.',
        vim.log.levels.WARN)
    else
      vim.notify('Todoist token works')
      M.refreshBlocks() -- open notes were showing "no token"
    end
  end)
end

--- Startup question, only when there is no token, the user did not opt out,
--- and a real UI is attached (never in headless runs or scripts).
local function askOnStartup()
  if token() or vim.uv.fs_stat(no_prompt_file) or #vim.api.nvim_list_uis() == 0 then return end

  -- confirm(), not vim.ui.select: here vim.ui.select is the fzf picker from
  -- fuzzyUtils, and the token prompt opened from its callback was cancelled at
  -- once while the picker's terminal closed -- the token then went into the
  -- buffer as typed text. confirm() is a plain command-line question.
  local choice = vim.fn.confirm('No Todoist API token found (needed by :Todoist).',
    "&Enter it now\n&Ask me next time\n&Don't ask again", 2)
  if choice == 1 then
    M.setToken()
  elseif choice == 3 then
    local f = io.open(no_prompt_file, 'w')
    if f then f:close() end
    vim.notify("Won't ask again. Run :TodoistToken whenever you want to set it.")
  end
end

vim.api.nvim_create_autocmd('VimEnter', {
  group = vim.api.nvim_create_augroup('PureTodoist', { clear = true }),
  once = true,
  -- Scheduled so the dashboard and the first screen are drawn before the
  -- question takes the command line.
  callback = function()
    vim.schedule(askOnStartup)
    -- Warm the default list in the background, a moment after startup so it
    -- never competes with drawing the first screen.
    vim.defer_fn(function()
      if not token() or #vim.api.nvim_list_uis() == 0 or state.loaded then return end
      fetch(nil, function(err, tasks, projects)
        if err then return end
        -- Archive in the background too, so it stays current even on days
        -- the list is never opened.
        archive.snapshot(tasks, projects)
        if not state.loaded then prefetched[''] = { tasks = tasks, projects = projects } end
      end)
    end, 1000)
  end,
})

vim.api.nvim_create_user_command('TodoistToken', M.setToken, {
  desc = 'Set the Todoist API token (hidden input)',
})

vim.api.nvim_create_user_command('Todoist', function(opts)
  -- Without a filter, inside a ```todoist block, open that block's filter.
  if opts.args == '' then
    local block = blockAt(vim.api.nvim_get_current_buf(), vim.fn.line('.') - 1)
    if block then return M.open(block.filter) end
  end
  M.open(opts.args)
end, {
  nargs = '*',
  desc = 'Todoist tasks as a checkbox table (optional filter, e.g. :Todoist today)',
})

-- -----------------------------------------------------------------------------
--  For the LLM actions: context: todoist
-- -----------------------------------------------------------------------------
--  The tasks straight from Todoist, one plain line each, subtasks indented
--  under their parent, for the Claude / Ollama actions that ask for them
--  (`context: todoist`, pure/llm.lua). Added for the vault's daily note
--  action: the note's synced list is ~10 KB, mostly a long task URL on every
--  line, which the model paid for on every step.
--
--    - [ ] Revisar roteiro · 2026-09-30 · P1 · Vídeos

--- The tasks of `filter` (default "today | overdue | no date", as the daily note's blocks). Waits for Todoist (up
--- to 15 s); an error comes back as the text, so the action still runs.
function M.text(filter)
  filter = (filter and filter ~= '') and filter or 'today | overdue | no date'
  local tasks, projects, err, done
  fetch(filter, function(e, t, p) err, tasks, projects, done = e, t, p, true end)
  vim.wait(15000, function() return done end, 50)
  if err then return 'Todoist: ' .. err end
  if not done then return 'Todoist did not answer in time.' end

  local names = {}
  for _, p in ipairs(projects or {}) do names[p.id] = p.name end
  local children, roots, ids = {}, {}, {}
  for _, t in ipairs(tasks or {}) do ids[t.id] = true end
  for _, t in ipairs(tasks or {}) do
    if t.parent_id and ids[t.parent_id] then
      children[t.parent_id] = children[t.parent_id] or {}
      table.insert(children[t.parent_id], t)
    else
      table.insert(roots, t)
    end
  end
  sortTasks(roots)
  local out = { ('Todoist, "%s" (%d tasks):'):format(filter, #(tasks or {})) }
  local function add(t, depth)
    local f = taskFields(t, names)
    local meta = {}
    if f.d ~= '' then table.insert(meta, f.d) end
    if f.p > 1 then table.insert(meta, priorityLabel(f.p)) end
    if f.j ~= '' then table.insert(meta, f.j) end
    table.insert(out, ('%s- [ ] %s%s'):format(string.rep('  ', depth), f.c,
      #meta > 0 and (' · ' .. table.concat(meta, ' · ')) or ''))
    for _, c in ipairs(children[t.id] or {}) do add(c, depth + 1) end
  end
  for _, t in ipairs(roots) do add(t, 0) end
  if #roots == 0 then table.insert(out, '- nothing') end
  return table.concat(out, '\n')
end

return M

end

-- lua/pure/update.lua
package.preload["pure.update"] = function(...)
-- =============================================================================
--  Update
-- =============================================================================
--  One key to bring this machine up to date: the configuration's own git
--  repository first, then the plugins.
--
--    :PureUpdate        (u on the dashboard)
--
--  1. git fetch in the config folder (stdpath('config')), in the background.
--     Works for a clone of main / windows and for the single-file branch.
--  2. New commits upstream: lists them and asks; yes pulls with --ff-only.
--     Commits made here and not pushed yet, or a pull that would overwrite
--     local changes: nothing is touched, and the message says why.
--  3. After a pull: offers to restart Neovim (:restart), so the new
--     configuration is what runs; press u again then for the plugins (a new
--     configuration may list different ones). Declining updates them now.
--  4. Otherwise: the plugins, silently. vim.pack.update() is run by a
--     separate headless Neovim with force = true: no report buffer to
--     confirm, no progress messages, and the editor is not blocked while it
--     downloads (vim.pack waits for every plugin before returning). One
--     notification at the end names the plugins that changed. Not in the
--     portable one-file build, which has no plugins.
--
--  Every question defaults to Yes: Enter answers it.
-- =============================================================================

local M = {}

--- Run git in the config folder; `cb(ok, output)` on the main loop.
local function git(args, cb)
  local cmd = vim.list_extend({ 'git', '-C', vim.fn.stdpath('config') }, args)
  local ok = pcall(vim.system, cmd, { text = true }, vim.schedule_wrap(function(res)
    local out = res.code == 0 and res.stdout or res.stderr
    cb(res.code == 0, vim.trim(out or ''))
  end))
  if not ok then cb(false, 'git is not installed') end
end

-- Run by the headless Neovim: update every installed plugin and print the
-- names of those whose revision changed.
local update_script = [[
local before = {}
for _, p in ipairs(vim.pack.get(nil, { info = false })) do before[p.spec.name] = p.rev end
vim.pack.update(nil, { force = true })
local changed = {}
for _, p in ipairs(vim.pack.get(nil, { info = false })) do
  if before[p.spec.name] ~= p.rev then table.insert(changed, p.spec.name) end
end
io.stdout:write(table.concat(changed, ', '))
]]

local updating = false

--- Update the plugins in the background (see 4. above).
local function plugins()
  if vim.g.pure_portable or not (vim.pack and vim.pack.update) or updating then return end
  updating = true
  local cmd = { vim.v.progpath, '--headless', '-u', 'NONE', '-c', 'lua ' .. update_script, '-c', 'qa!' }
  local ok = pcall(vim.system, cmd, { text = true }, vim.schedule_wrap(function(res)
    updating = false
    local changed = vim.trim(res.stdout or '')
    if res.code ~= 0 then
      vim.notify('Plugin update failed: ' .. vim.trim(res.stderr or ''), vim.log.levels.WARN)
    elseif changed ~= '' then
      vim.notify('Plugins updated: ' .. changed .. '. Restart Neovim to use them.')
    else
      vim.notify('Plugins up to date')
    end
  end))
  if not ok then updating = false end
end

--- Whether :restart can bring the open files back. It saves the session to
--- the temp folder and sources it on the new Neovim through a Lua string
--- built from fnameescape(): with a space in that path ("C:/Users/Mia
--- Schionato/...") the escaped "\ " is an invalid Lua escape, and the new
--- Neovim starts with "E5107: invalid escape sequence" in UIEnter. Checked
--- on Neovim 0.12.5; the same folder its runtime (vim/_core/server.lua) uses.
local function sessionRestartWorks()
  local dir = vim.fs.abspath(vim.fs.dirname(vim.fs.dirname(vim.fn.tempname())))
  return vim.fn.fnameescape(dir) == dir
end

--- After a pull: restart now, or say that the new configuration needs one.
local function offerRestart(count)
  local msg = ('Configuration updated (%d new commit%s).'):format(count, count == 1 and '' or 's')
  if vim.fn.exists(':restart') == 2 and #vim.api.nvim_list_uis() > 0 then
    local keep = sessionRestartWorks()
    local question = keep and 'Restart Neovim now to load it?'
      or 'Restart Neovim now to load it? (open files are not reopened)'
    if vim.fn.confirm(msg .. '\n' .. question, '&Yes\n&No', 1) == 1 then
      -- restart! skips the session, and with it the broken path above.
      return vim.cmd(keep and 'restart' or 'restart!')
    end
  end
  vim.notify(msg .. ' Restart Neovim to load it.')
  plugins()
end

--- Pull the configuration if upstream has new commits, then the plugins.
function M.run()
  git({ 'rev-parse', '--is-inside-work-tree' }, function(is_repo)
    if not is_repo then
      vim.notify('The config folder is not a git repository: updating plugins only')
      return plugins()
    end
    git({ 'rev-parse', '--abbrev-ref', '@{upstream}' }, function(has_upstream, upstream)
      if not has_upstream then
        vim.notify('This branch has no upstream to pull from: updating plugins only')
        return plugins()
      end
      vim.notify('Checking ' .. upstream .. '…')
      git({ 'fetch', '--quiet' }, function(fetched, err)
        if not fetched then
          vim.notify('git fetch failed: ' .. err, vim.log.levels.WARN)
          return plugins()
        end
        git({ 'rev-list', '--left-right', '--count', 'HEAD...@{upstream}' }, function(_, counts)
          local ahead, behind = counts:match('(%d+)%s+(%d+)')
          ahead, behind = tonumber(ahead) or 0, tonumber(behind) or 0

          if behind == 0 then
            vim.notify(ahead > 0
              and ('Configuration up to date; %d local commit(s) not pushed yet'):format(ahead)
              or 'Configuration up to date')
            return plugins()
          end
          if ahead > 0 then
            -- --ff-only would refuse anyway; say why instead of failing.
            vim.notify(('This machine has %d commit(s) not pushed and %s has %d new: '
              .. 'pull by hand (git pull) to merge them'):format(ahead, upstream, behind), vim.log.levels.WARN)
            return plugins()
          end

          git({ 'log', '--oneline', '--no-decorate', '-15', 'HEAD..@{upstream}' }, function(_, log)
            local more = behind > 15 and ('\n… and %d more'):format(behind - 15) or ''
            local choice = #vim.api.nvim_list_uis() == 0 and 1 or vim.fn.confirm(
              ('%d new commit(s) on %s:\n%s%s\n\nPull them?'):format(behind, upstream, log, more), '&Yes\n&No', 1)
            if choice ~= 1 then return plugins() end

            git({ 'pull', '--ff-only', '--quiet' }, function(pulled, perr)
              if not pulled then
                -- Usually local edits to a file the pull changes.
                vim.notify('git pull failed, nothing was changed:\n' .. perr, vim.log.levels.WARN)
                return plugins()
              end
              offerRestart(behind)
            end)
          end)
        end)
      end)
    end)
  end)
end

vim.api.nvim_create_user_command('PureUpdate', M.run, {
  desc = 'Pull new commits of the configuration, then update the plugins',
})

return M

end

-- lua/pure/vaultsync.lua
package.preload["pure.vaultsync"] = function(...)
--- :VaultSync: commit, pull, then push the Obsidian vault.
---
--- Why a command instead of typing the git commands: the vault's remote is
--- encrypted with git-remote-gcrypt, and every push gcrypt makes is a forced
--- push (a long-standing bug it warns about on each push). A normal git push is
--- refused when the remote holds commits you have not pulled; a gcrypt push
--- replaces them. Pushing from the PC before pulling what the Mac sent would
--- drop the Mac's notes from the remote. So the order is fixed here instead of
--- left to memory: save, commit, pull, and push only after the pull worked.
---
--- The pull merges (--no-rebase) whatever pull.rebase says. A merge conflict
--- leaves the vault in one state that a single commit resolves, so after the
--- conflict markers are fixed, :VaultSync finishes the job by itself. A rebase
--- can stop once per commit and has to be continued by hand.
---
--- git runs in the background, so Neovim stays usable while ssh and gpg work.
--- gpg asks for its passphrase in a window of its own (pinentry).

local M = {}

local running = false

local function notify(msg, level)
  vim.notify('Vault: ' .. msg, level)
end

--- Run git in `dir` and wait for it. Only callable inside the sync coroutine.
--- @param dir string
--- @param args string[]
--- @return vim.SystemCompleted
local function git(dir, args)
  local co = coroutine.running()
  vim.system(vim.list_extend({ 'git', '-C', dir }, args), {
    text = true,
    -- Never wait for a username or password on a terminal nobody is looking at.
    env = { GIT_TERMINAL_PROMPT = '0' },
  }, function(result)
    vim.schedule(function() coroutine.resume(co, result) end)
  end)
  return coroutine.yield()
end

--- The NUL-separated paths git prints with -z.
--- @param text string|nil
--- @return string[]
local function paths(text)
  return vim.split(text or '', '\0', { trimempty = true })
end

--- @param path string
--- @param dir string
--- @return boolean
local function isInside(path, dir)
  local p, d = vim.fs.normalize(path), vim.fs.normalize(dir)
  if vim.fn.has('win32') == 1 then p, d = p:lower(), d:lower() end
  return p:sub(1, #d + 1) == d .. '/'
end

--- Files git marks as conflicted that still hold conflict markers. One whose
--- markers are gone counts as fixed: the next `git add` marks it resolved.
--- @param dir string
--- @return string[]
local function unresolved(dir)
  local left = {}
  for _, file in ipairs(paths(git(dir, { 'diff', '--name-only', '-z', '--diff-filter=U' }).stdout)) do
    local fh = io.open(dir .. '/' .. file, 'r')
    local text = fh and fh:read('*a') or ''
    if fh then fh:close() end
    if text:find('^<<<<<<< ') or text:find('\n<<<<<<< ') or text:find('\n>>>>>>> ') then
      left[#left + 1] = file
    end
  end
  return left
end

--- @param res vim.SystemCompleted
--- @return string
local function output(res)
  local text = vim.trim(res.stderr or '')
  return text ~= '' and text or vim.trim(res.stdout or '')
end

--- @param dir string
local function run(dir)
  -- The branch has to track a remote: that is where the notes go.
  local upstream = vim.trim(git(dir, { 'rev-parse', '--abbrev-ref', '--symbolic-full-name', '@{u}' }).stdout or '')
  if upstream == '' then
    return notify('this branch tracks no remote. Push it once with: git push -u <remote> <branch>',
      vim.log.levels.WARN)
  end

  -- A rebase started by hand has to be finished by hand: a commit made now
  -- would land in the middle of it.
  for _, state in ipairs({ 'rebase-merge', 'rebase-apply' }) do
    local path = vim.trim(git(dir, { 'rev-parse', '--git-path', state }).stdout or '')
    if vim.fn.isabsolutepath(path) == 0 then path = dir .. '/' .. path end
    if path ~= '' and vim.uv.fs_stat(path) then
      return notify('a rebase is in progress. Finish it first (git rebase --continue, or --abort)',
        vim.log.levels.WARN)
    end
  end

  -- Conflicts from the last sync come first: `git add -A` would otherwise
  -- commit the conflict markers as if they were notes.
  local left = unresolved(dir)
  if #left > 0 then
    return notify('fix the conflict markers first, then :VaultSync again:\n  ' .. table.concat(left, '\n  '),
      vim.log.levels.WARN)
  end

  -- Notes of the vault still being edited here go in too.
  local saved = 0
  for _, buf in ipairs(vim.api.nvim_list_bufs()) do
    local name = vim.api.nvim_buf_get_name(buf)
    if vim.bo[buf].modified and vim.bo[buf].buftype == '' and name ~= '' and isInside(name, dir) then
      vim.api.nvim_buf_call(buf, function() vim.cmd('silent write') end)
      saved = saved + 1
    end
  end

  -- Commit. A merge left open by a conflict keeps git's own message.
  git(dir, { 'add', '-A' })
  local merging = git(dir, { 'rev-parse', '-q', '--verify', 'MERGE_HEAD' }).code == 0
  local staged = #paths(git(dir, { 'diff', '--cached', '--name-only', '-z' }).stdout)
  if merging or staged > 0 then
    local res = git(dir, merging and { 'commit', '--no-edit' } or {
      'commit', '-m', ('Sync from %s, %s'):format(vim.uv.os_gethostname(), os.date('%Y-%m-%d %H:%M')),
    })
    if res.code ~= 0 then
      return notify('commit failed, nothing was pushed:\n' .. output(res), vim.log.levels.ERROR)
    end
  end

  -- Pull before any push: see the top of this file.
  local before = vim.trim(git(dir, { 'rev-parse', 'HEAD' }).stdout or '')
  local pull = git(dir, { 'pull', '--no-rebase', '--no-edit' })
  vim.cmd.checktime() -- reload the open notes the pull changed
  if pull.code ~= 0 then
    local conflicts = unresolved(dir)
    if #conflicts > 0 then
      return notify(('the same lines changed on both machines. Fix the conflict markers in:\n  %s\n'
        .. 'then :VaultSync again. Nothing was pushed.'):format(table.concat(conflicts, '\n  ')),
        vim.log.levels.WARN)
    end
    return notify('pull failed, nothing was pushed:\n' .. output(pull), vim.log.levels.ERROR)
  end
  local pulled = tonumber(vim.trim(git(dir, { 'rev-list', '--count', before .. '..' .. upstream }).stdout)) or 0

  -- Push only when the remote is missing something.
  local ahead = tonumber(vim.trim(git(dir, { 'rev-list', '--count', upstream .. '..HEAD' }).stdout)) or 0
  if ahead > 0 then
    local push = git(dir, { 'push' })
    if push.code ~= 0 then
      return notify('push failed:\n' .. output(push), vim.log.levels.ERROR)
    end
  end

  local done = {}
  if saved > 0 then done[#done + 1] = ('saved %d note%s'):format(saved, saved == 1 and '' or 's') end
  if staged > 0 then done[#done + 1] = ('committed %d file%s'):format(staged, staged == 1 and '' or 's') end
  if pulled > 0 then done[#done + 1] = ('pulled %d commit%s'):format(pulled, pulled == 1 and '' or 's') end
  if ahead > 0 then done[#done + 1] = 'pushed to ' .. upstream end
  notify(#done > 0 and table.concat(done, ', ') or 'already in sync')
end

--- Save, commit, pull and push the vault, in that order.
function M.sync()
  if running then return notify('a sync is already running') end
  local dir = require('pure.zettelkasten').vaultPath()
  if not dir then
    return notify('no vault set, see :ZettelVault', vim.log.levels.WARN)
  end

  running = true
  notify('syncing…')
  coroutine.wrap(function()
    local ok, err = pcall(run, dir)
    running = false
    if not ok then notify(tostring(err), vim.log.levels.ERROR) end
  end)()
end

vim.api.nvim_create_user_command('VaultSync', M.sync,
  { desc = 'Save, commit, pull, then push the Obsidian vault' })

-- Exposed for tests.
M._busy = function() return running end

return M

end

-- lua/pure/zettelkasten.lua
package.preload["pure.zettelkasten"] = function(...)
--- Obsidian-compatible note templates.
---
--- Templates live in the vault and use the syntax of Obsidian's *core*
--- Templates plugin, so the same file works in both editors without Templater:
---
---   {{title}}            the note's title (its file name without extension)
---   {{date}}             current date, default YYYY-MM-DD
---   {{time}}             current time, default HH:mm
---   {{date:FORMAT}}      a Moment.js format, e.g. {{date:YYYYMMDDHHmm}},
---   {{time:FORMAT}}      {{date:dddd, D [de] MMMM}}; [text] is copied as is
---
--- Day and month names follow vim.g.pure_templates_locale: 'en' (default, as
--- Obsidian ships) or 'pt'. Set it to the language Obsidian itself uses, so a
--- template expands to the same text in both editors.
---
--- Templater's `tp.file.move(...)` has no equivalent in the core plugin, so the
--- destination folder is not written into the template at all: it lives in the
--- `destinations` table below, keyed by template name. That keeps the template
--- files clean and puts the routing in one place.
---
--- The vault path is asked for once and remembered, the same way the Todoist
--- token is. In order of precedence:
---
---   vim.g.pure_vault              set in the config, wins over everything
---   $OBSIDIAN_VAULT               environment
---   stdpath('data')/obsidian_vault   the answer to the question below
---
--- :ZettelVault asks again at any time.

local M = {}

local vault_file = vim.fn.stdpath('data') .. '/obsidian_vault'
local no_prompt_file = vim.fn.stdpath('data') .. '/obsidian_vault_no_prompt'

--- Templates that are a note *per period* rather than a note about something.
---
--- Picking one of these does not insert into the current buffer: it works out
--- which note the period maps to, creates it from the template if it is not
--- there yet, and opens it. Opening the same period twice just returns to the
--- note, so the template never runs over what you already wrote.
---
--- `name` is an os.date format; %G-W%V is the ISO week, which Windows' strftime
--- does support (checked: 2026-09-25 gives 2026-W39).
---
--- The folders, the quotes file and the destinations below used to be fixed
--- here, so reorganising the vault meant editing this module. They are now
--- defaults that vim.g.pure_periodic_folders, vim.g.pure_quotes and
--- vim.g.pure_template_destinations (configs.lua) override. The options are
--- read on every use, not once at load: configs.lua may run after this file,
--- and a change made with :let takes effect without restarting.
local default_periodic = {
  Daily   = { folder = '9-Archive/Periodic/Daily',   name = '%Y-%m-%d', step = 86400,  unit = 'day' },
  Weekly  = { folder = '9-Archive/Periodic/Weekly',  name = '%G-W%V',   step = 604800, unit = 'week' },
  Monthly = { folder = '9-Archive/Periodic/Monthly', name = '%Y-%m',    step = nil,    unit = 'month' },
}

--- A vault-relative folder from an option, without slashes at either end.
local function relFolder(path)
  return (tostring(path):gsub('\\', '/'):gsub('^/+', ''):gsub('/+$', ''))
end

--- `periodic.Daily` etc.: the default entry with the folder from
--- vim.g.pure_periodic_folders when it names one.
local periodic = setmetatable({}, {
  __index = function(_, period)
    local entry = default_periodic[period]
    local folder = entry and (vim.g.pure_periodic_folders or {})[period]
    if not folder or folder == '' then return entry end
    return vim.tbl_extend('force', entry, { folder = relFolder(folder) })
  end,
})

--- Where the quote of the day lives, relative to the vault. The resurfaced
--- notes come from destinations.Permanent.
local function quotesFile()
  local path = vim.g.pure_quotes
  return (path and path ~= '') and relFolder(path) or '9-Archive/Periodic/Quotes.md'
end

--- Folder each template sends its note to, relative to the vault root.
--- "{{title}}" is expanded, which is what puts a project in its own folder.
--- "{{choose:A|B}}" asks which of them (Project: her projects live in
--- 1-Projects/Personal and 1-Projects/Clients, and a new one landed beside
--- those two folders). A template missing here leaves the note where it is.
local default_destinations = {
  Delete     = '0-Inbox/Trash',
  Literature = '3-Zettelkasten/Literature',
  MOC        = '4-Maps',
  Permanent  = '3-Zettelkasten/Permanent',
  Project    = '1-Projects/{{choose:Personal|Clients}}/{{title}}',
  Seed       = '3-Zettelkasten/Seeds',
  VideoIdeas = '2-Areas/Audiovisual/Ideas',
}

--- `destinations[name]`: vim.g.pure_template_destinations first, then the
--- default. `false` there leaves that template's note where it is, except for
--- Delete and Permanent: the trash and the resurfaced notes always need a
--- folder, so those fall back to the default.
local destinations = setmetatable({}, {
  __index = function(_, name)
    local value = (vim.g.pure_template_destinations or {})[name]
    if value == false and name ~= 'Delete' and name ~= 'Permanent' then return nil end
    if type(value) == 'string' and value ~= '' then return relFolder(value) end
    return default_destinations[name]
  end,
})

--- Day and month names per locale. os.date's %A / %B always gave English
--- (the C locale), whatever language Obsidian renders the same template in.
local locales = {
  en = {
    months = { 'January', 'February', 'March', 'April', 'May', 'June', 'July',
      'August', 'September', 'October', 'November', 'December' },
    months_short = { 'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec' },
    days = { 'Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday' },
    days_short = { 'Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat' },
    days_min = { 'Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa' },
    ordinal = function(n)
      local last2, last = n % 100, n % 10
      local suffix = (last2 >= 11 and last2 <= 13) and 'th'
        or ({ 'st', 'nd', 'rd' })[last] or 'th'
      return n .. suffix
    end,
  },
  -- As Moment's pt / pt-br locales write them: lower case.
  pt = {
    months = { 'janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho',
      'agosto', 'setembro', 'outubro', 'novembro', 'dezembro' },
    months_short = { 'jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez' },
    days = { 'domingo', 'segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado' },
    days_short = { 'dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb' },
    days_min = { 'do', '2ª', '3ª', '4ª', '5ª', '6ª', 'sá' },
    ordinal = function(n) return n .. 'º' end,
  },
}

--- Short weekday names used by the diary file names ("2026-09-25, sex").
local DIARY_WEEKDAY = locales.pt.days_short

--- `time` moved to noon of its day. Day arithmetic goes from noon: on a
--- daylight saving change a day lasts 23 or 25 hours, and 00:30 minus 86400
--- seconds could land on the same date, making "yesterday" today.
--- @param time integer
--- @return integer
local function noon(time)
  local t = os.date('*t', time)
  t.hour, t.min, t.sec, t.isdst = 12, 0, 0, nil
  return os.time(t)
end

--- The period `n` steps from the one holding `when` (n = -1 or 1).
--- Months have no fixed length, so they step by calendar month.
--- @param period table
--- @param when integer
--- @param n integer
--- @return integer
local function shifted(period, when, n)
  if period.step then return noon(when) + n * period.step end
  local t = os.date('*t', when)
  -- os.time() carries month 0 or 13 into the year before or after.
  t.day, t.month, t.hour, t.min, t.sec, t.isdst = 1, t.month + n, 12, 0, 0, nil
  return os.time(t)
end

--- First and last day of the period holding `when`, both at noon. A week is
--- the ISO week, Monday to Sunday; with no period, just the day.
--- @param period table|nil
--- @param when integer
--- @return integer first
--- @return integer last
local function bounds(period, when)
  local day = noon(when)
  local unit = period and period.unit or 'day'
  if unit == 'week' then
    -- os.date's wday counts from Sunday = 1, so Monday is 2.
    local first = day - ((os.date('*t', day).wday + 5) % 7) * 86400
    return first, noon(first + 6 * 86400)
  elseif unit == 'month' then
    local t = os.date('*t', day)
    local first = os.time({ year = t.year, month = t.month, day = 1, hour = 12 })
    -- Month 13 carries into January, as in shifted().
    local next_first = os.time({ year = t.year, month = t.month + 1, day = 1, hour = 12 })
    return first, noon(next_first - 86400)
  end
  return day, day
end

--- The day a periodic note is dated by. A week is dated by its Thursday: in
--- ISO 8601 the Thursday decides a week's year and month, so a week running
--- from September into October is October's when its Thursday is. A month is
--- dated by its first day. A day keeps its time, for {{time}}.
--- @param period table
--- @param when integer
--- @return integer
local function anchorOf(period, when)
  local first = bounds(period, when)
  if period.unit == 'week' then return noon(first + 3 * 86400) end
  if period.unit == 'month' then return first end
  return when
end

--- Noon of every day from `first` to `last`, both included.
--- @param first integer
--- @param last integer
--- @return integer[]
local function eachDay(first, last)
  local list, day, stop = {}, noon(first), os.date('%Y-%m-%d', last)
  while os.date('%Y-%m-%d', day) <= stop do
    list[#list + 1] = day
    day = noon(day + 86400)
  end
  return list
end

--- Moment.js tokens, longest first within each letter so "MMMM" is not eaten
--- by "MM", "Do" is tried before "D", and so on.
local TOKENS = {
  'YYYY', 'YY', 'GGGG', 'GG',
  'MMMM', 'MMM', 'MM', 'M',
  'Do', 'DDDD', 'DDD', 'DD', 'D',
  'dddd', 'ddd', 'dd', 'd',
  'HH', 'H', 'hh', 'h',
  'mm', 'm', 'ss', 's',
  'WW', 'W',
  'A', 'a',
}

--- Format `time` with a Moment.js format string, as Obsidian does.
---
--- Formatted directly rather than translated to an os.date format: strftime
--- has no unpadded day, month or hour (Moment's D, M, H, h) and no ordinals,
--- which the translation used to leave as literal letters. Text in [brackets]
--- is copied without formatting, as in Moment. Scanned left to right, so a
--- value can never be re-matched by a later token.
--- @param fmt string
--- @param time integer
--- @return string
local function formatMoment(fmt, time)
  local t = os.date('*t', time)
  local L = locales[vim.g.pure_templates_locale or 'en'] or locales.en
  local h12 = t.hour % 12 == 0 and 12 or t.hour % 12
  local value = {
    YYYY = ('%04d'):format(t.year), YY = ('%02d'):format(t.year % 100),
    MMMM = L.months[t.month], MMM = L.months_short[t.month],
    MM = ('%02d'):format(t.month), M = tostring(t.month),
    Do = L.ordinal(t.day), DDDD = ('%03d'):format(t.yday), DDD = tostring(t.yday),
    DD = ('%02d'):format(t.day), D = tostring(t.day),
    dddd = L.days[t.wday], ddd = L.days_short[t.wday], dd = L.days_min[t.wday], d = tostring(t.wday - 1),
    HH = ('%02d'):format(t.hour), H = tostring(t.hour), hh = ('%02d'):format(h12), h = tostring(h12),
    mm = ('%02d'):format(t.min), m = tostring(t.min), ss = ('%02d'):format(t.sec), s = tostring(t.sec),
    A = t.hour < 12 and 'AM' or 'PM', a = t.hour < 12 and 'am' or 'pm',
    -- ISO 8601, as Moment's GGGG and W: strftime's %G and %V, which the
    -- Windows CRT supports too.
    GGGG = os.date('%G', time), GG = os.date('%G', time):sub(3),
    WW = os.date('%V', time), W = tostring(tonumber(os.date('%V', time))),
  }

  local out, i = {}, 1
  while i <= #fmt do
    local literal = fmt:match('^%[([^%]]*)%]', i)
    if literal then
      out[#out + 1] = literal
      i = i + #literal + 2
    else
      local matched
      for _, token in ipairs(TOKENS) do
        if fmt:sub(i, i + #token - 1) == token then
          matched = token
          break
        end
      end
      if matched then
        out[#out + 1] = value[matched]
        i = i + #matched
      else
        out[#out + 1] = fmt:sub(i, i)
        i = i + 1
      end
    end
  end
  return table.concat(out)
end

--- Configured vault path, or nil when it has never been answered.
--- @return string|nil
local function vaultPath()
  local configured = vim.g.pure_vault
  if configured and configured ~= '' then
    return vim.fs.normalize(vim.fn.expand(configured))
  end

  local env = vim.env.OBSIDIAN_VAULT
  if env and env ~= '' then
    return vim.fs.normalize(vim.fn.expand(env))
  end

  local f = io.open(vault_file, 'r')
  if not f then return nil end
  local saved = vim.trim(f:read('*l') or '')
  f:close()
  -- An empty file counts as unanswered, so the question comes up again.
  return saved ~= '' and vim.fs.normalize(vim.fn.expand(saved)) or nil
end

local function templatesPath()
  local root = vaultPath()
  return root and (root .. '/' .. (vim.g.pure_templates or 'Templates')) or nil
end

--- Ask for the vault folder and remember it.
---
--- The answer is checked before saving: a path that is not a directory, or that
--- has no Templates folder, is almost certainly a typo, and finding that out
--- now beats finding out on the first <leader>nt.
function M.setVault()
  local ok, input = pcall(vim.fn.input, {
    prompt = 'Obsidian vault folder (empty to cancel): ',
    default = vaultPath() or vim.fn.expand('~/'),
    completion = 'dir',
  })
  input = ok and vim.trim(input or '') or ''
  if input == '' then
    return vim.notify('Vault not changed')
  end

  local path = vim.fs.normalize(vim.fn.expand(input))
  if vim.fn.isdirectory(path) == 0 then
    return vim.notify('Not a folder: ' .. path .. '\nNothing saved.', vim.log.levels.WARN)
  end

  vim.fn.mkdir(vim.fn.stdpath('data'), 'p')
  local f, err = io.open(vault_file, 'w')
  if not f then
    return vim.notify('Could not write ' .. vault_file .. ': ' .. tostring(err), vim.log.levels.ERROR)
  end
  f:write(path, '\n')
  f:close()
  os.remove(no_prompt_file)

  if vim.g.pure_vault and vim.g.pure_vault ~= '' then
    vim.notify('Saved, but vim.g.pure_vault is set and takes precedence', vim.log.levels.WARN)
  end
  -- pure/notes.lua and the <leader>ev / fv / nv keys follow the vault.
  vim.api.nvim_exec_autocmds('User', { pattern = 'PureVaultChanged', data = { vault = vaultPath() } })

  local templates = path .. '/' .. (vim.g.pure_templates or 'Templates')
  if vim.fn.isdirectory(templates) == 0 then
    vim.notify('Vault saved, but there is no Templates folder in it yet:\n  ' .. templates,
      vim.log.levels.WARN)
  else
    local n = #vim.tbl_filter(function(name) return name:match('%.md$') end, vim.fn.readdir(templates))
    vim.notify(('Vault saved: %s (%d templates)'):format(path, n))
  end
end

--- Offer to set the vault once, on the first start that has a UI.
--- Declining writes a marker so the question is not repeated; :ZettelVault
--- still works afterwards.
function M.maybeAskVault()
  if vaultPath() or vim.uv.fs_stat(no_prompt_file) or #vim.api.nvim_list_uis() == 0 then
    return
  end
  vim.schedule(function()
    local choice = vim.fn.confirm(
      'No Obsidian vault configured. Set it now?\n(templates come from <vault>/Templates)',
      '&Yes\n&Later\nNe&ver ask', 1)
    if choice == 1 then
      M.setVault()
    elseif choice == 3 then
      local f = io.open(no_prompt_file, 'w')
      if f then
        f:write('Delete this file to be asked again, or run :ZettelVault\n')
        f:close()
      end
      vim.notify('Will not ask again. Run :ZettelVault when you want to set it.')
    end
  end)
end

vim.api.nvim_create_user_command('ZettelVault', M.setVault,
  { desc = 'Set the Obsidian vault folder used for templates' })

--- Title of the current note: the file name without ".md". Only that extension
--- is dropped, so "v1.2 plan" typed without one keeps its ".2 plan".
local function currentTitle()
  local name = (vim.fn.expand('%:t'):gsub('%.md$', ''))
  return name ~= '' and name or 'Untitled'
end

--- Names that are not a title: the ID obsidian.nvim used to generate when given
--- none ("1790444711-VABT"), and the fallback of a new file created with no name.
--- @param stem string
--- @return boolean
local function isGeneratedName(stem)
  -- "Untitled 2" too: newNote() numbers a second nameless note that way.
  return stem == 'Untitled' or stem:match('^Untitled %d+$') ~= nil
    or stem:match('^%d+%-%a+$') ~= nil
end

--- A title made safe as a file or folder name: Windows rejects \ / : * ? " < > |
--- and a trailing dot or space.
--- @param name string
--- @return string
local function safeName(name)
  name = (name:gsub('[\\/:*?"<>|]', ''))
  name = (name:gsub('%s+', ' '))
  name = (name:gsub('[%s%.]+$', ''))
  return vim.trim(name)
end

--- The name of a note made from a [[link]] (pure/notes.lua): the name written
--- in the link.
---
--- The title, made safe for Windows, is the file name; an existing note is
--- never reused ("NovaNota 2"); only with no title at all does it fall back
--- to a timestamp.
--- @param title string|nil
--- @param dir string|nil  the folder the note is created in
--- @return string
function M.noteId(title, dir)
  local name = safeName(title or '')
  if name == '' then
    return os.date('%Y%m%d%H%M%S')
  end
  if dir then
    local candidate, n = name, 2
    while vim.uv.fs_stat(tostring(dir) .. '/' .. candidate .. '.md') do
      candidate = name .. ' ' .. n
      n = n + 1
    end
    name = candidate
  end
  return name
end

--- The title of the note being templated: its file name, or, when that is a
--- generated one, whatever the user types. Cancelling keeps the current name.
--- @param callback fun(title: string)
local function withTitle(callback)
  local stem = currentTitle()
  if not isGeneratedName(stem) then return callback(stem) end
  vim.ui.input({ prompt = 'Note title: ' }, function(input)
    input = safeName(input or '')
    callback(input ~= '' and input or stem)
  end)
end

--- One line of Quotes.md, picked by the day of the year so it is stable for a
--- given day and cycles through the file.
--- @param when integer
--- @return string
local function quoteOfTheDay(when)
  local root = vaultPath()
  if not root then return '' end
  local file = io.open(root .. '/' .. quotesFile(), 'r')
  if not file then return '' end

  local quotes = {}
  for line in file:lines() do
    if line:sub(1, 2) == '- ' then
      quotes[#quotes + 1] = line:sub(3)
    end
  end
  file:close()
  if #quotes == 0 then return '' end

  return quotes[(tonumber(os.date('%j', when)) % #quotes) + 1]
end

--- One of your own permanent notes, resurfaced by the day of the year.
--- @param when integer
--- @return string
local function resurfacedNote(when)
  local root = vaultPath()
  if not root then return '' end

  local notes = vim.fn.globpath(root .. '/' .. destinations.Permanent, '*.md', false, true)
  if #notes == 0 then
    return 'Write your first permanent note and it will show up here.'
  end
  table.sort(notes)

  local pick = notes[(tonumber(os.date('%j', when)) % #notes) + 1]
  return '[[' .. vim.fn.fnamemodify(pick, ':t:r') .. ']]'
end

--- Expand the template placeholders.
---
--- Every date comes from a single timestamp, so a template using both {{date}}
--- and {{time}} cannot straddle a second boundary. The previous version built
--- its table of values when the module was *required*, which meant {{time}}
--- returned the moment Neovim started rather than the moment of use.
---
--- `ctx.when` is the note's own date, which for a periodic note is the day it
--- covers rather than today. That is what makes reopening an old daily render
--- its own neighbours instead of this week's.
--- @param content string
--- @param ctx table
--- @return string
--- Placeholders that are dates, and so accept a shift in days: {{date+1}},
--- {{start-1:MMM D}}. Any other placeholder with a shift is left untouched.
local DATED = { date = true, time = true, start = true, ['end'] = true }

local function render(content, ctx)
  local when = ctx.when or os.time()
  local period = ctx.periodic
  local first, last = bounds(period, when)

  return (content:gsub('{{([%a_]+)([+-]?%d*)(:?)([^}]*)}}', function(name, shift, colon, fmt)
    local key = name:lower()
    fmt = colon == ':' and fmt or nil

    local days = tonumber(shift)
    if shift ~= '' and not (days and DATED[key]) then return nil end
    local function at(time)
      return days and noon(time) + days * 86400 or time
    end

    if key == 'title' then
      return ctx.title
    elseif key == 'date' then
      return formatMoment(fmt or 'YYYY-MM-DD', at(when))
    elseif key == 'time' then
      return formatMoment(fmt or 'HH:mm', at(when))
    elseif key == 'start' then
      return formatMoment(fmt or 'YYYY-MM-DD', at(first))
    elseif key == 'end' then
      return formatMoment(fmt or 'YYYY-MM-DD', at(last))
    elseif key == 'week' then
      return os.date('%G-W%V', when)
    elseif key == 'month' then
      return os.date('%Y-%m', when)
    elseif key == 'quote' then
      return quoteOfTheDay(when)
    elseif key == 'idea' then
      return resurfacedNote(when)
    elseif key == 'diary' then
      -- Matches the diary file names: "2026-09-25, sex"
      return os.date('%Y-%m-%d', when) .. ', ' .. DIARY_WEEKDAY[tonumber(os.date('%w', when)) + 1]
    elseif key == 'prev' or key == 'next' then
      -- Only meaningful inside a periodic note.
      if not period then return '' end
      return os.date(period.name, shifted(period, when, key == 'prev' and -1 or 1))
    elseif key == 'days' then
      -- A link to the daily note of each day of the period: "Mon 21/09".
      local out = {}
      for _, day in ipairs(eachDay(first, last)) do
        out[#out + 1] = ('- [[%s/%s|%s]]'):format(periodic.Daily.folder,
          os.date('%Y-%m-%d', day), formatMoment('ddd DD/MM', day))
      end
      return table.concat(out, '\n')
    elseif key == 'worklogs' then
      -- Each day's "Work log" section embedded, as lines of a callout.
      local out = {}
      for _, day in ipairs(eachDay(first, last)) do
        out[#out + 1] = ('> **%s**\n> ![[%s/%s#Work log]]'):format(
          formatMoment('ddd DD/MM', day), periodic.Daily.folder, os.date('%Y-%m-%d', day))
      end
      return table.concat(out, '\n>\n')
    elseif key == 'weeks' then
      -- A link to the weekly note of each ISO week that touches the period.
      local out, seen = {}, {}
      for _, day in ipairs(eachDay(first, last)) do
        local week = os.date('%G-W%V', day)
        if not seen[week] then
          seen[week] = true
          out[#out + 1] = ('- [[%s/%s|Week %d]]'):format(periodic.Weekly.folder, week,
            tonumber(os.date('%V', day)))
        end
      end
      return table.concat(out, '\n')
    end

    return nil -- unknown placeholder: leave it untouched
  end))
end

--- A path as the file system compares it: case-blind on Windows, where the
--- same file can be spelled C:/ or c:/.
--- @param path string
--- @return string
local function pathKey(path)
  path = vim.fs.normalize(path)
  return vim.fn.has('win32') == 1 and path:lower() or path
end

--- Whether `path` is `folder` or somewhere below it.
--- @param path string
--- @param folder string
--- @return boolean
local function isInside(path, folder)
  local p, f = pathKey(path), pathKey(folder)
  return p == f or p:sub(1, #f + 1) == f .. '/'
end

--- Move the current file into `folder` (relative to the vault).
---
--- Writes first, renames, then reopens at the new path and drops the stale
--- buffer, otherwise Neovim keeps editing a name that no longer exists.
---
--- The file is named after the title and always ends in ".md": a note created
--- without an extension, or with a generated name, would otherwise land in its
--- folder as something Obsidian does not treat as a note.
---
--- A note already somewhere under the template's folder (anywhere in
--- 1-Projects for '1-Projects/{{title}}') was put there on purpose, before
--- the template: it stays in its folder, only named after the title.
--- @param folder string
--- @param title string|nil  defaults to the current file name
local function moveCurrentFile(folder, title)
  local path = vim.api.nvim_buf_get_name(0)
  if path == '' then
    return vim.notify('Save the note before applying a template that moves it',
      vim.log.levels.WARN)
  end
  path = vim.fs.normalize(path)

  local root = vaultPath()
  if not root then return end -- insertTemplate checks first; this is a guard

  title = safeName(title or currentTitle())
  if title == '' then title = 'Untitled' end

  local base = folder:match('^(.-)/*{{title}}') or folder
  local stays = base ~= '' and isInside(path, root .. '/' .. base)
  local target_dir, folder_name
  if stays then
    target_dir = vim.fs.dirname(path)
    folder_name = target_dir:sub(#root + 2)
  else
    -- Replaced through a function: as a plain replacement string, a '%' in
    -- the title is gsub syntax, and "100% focus" became the folder "100 focus".
    folder_name = folder:gsub('{{title}}', function() return title end)
    target_dir = root .. '/' .. folder_name
  end
  local target = target_dir .. '/' .. title .. '.md'

  if pathKey(target) == pathKey(path) then
    return -- already there
  end
  if vim.uv.fs_stat(target) then
    return vim.notify('Not moving: a note already exists at ' .. target,
      vim.log.levels.WARN)
  end

  local old = vim.api.nvim_get_current_buf()
  local stat = vim.uv.fs_stat(path)
  vim.fn.mkdir(target_dir, 'p')
  if stat and stat.type == 'file' then
    -- On disk already: saved, then renamed, so it stays the same file.
    vim.cmd('silent write')
    local ok, err = os.rename(path, target)
    if not ok then
      return vim.notify('Could not move the note: ' .. tostring(err), vim.log.levels.ERROR)
    end
  else
    -- Never saved: written straight to its new place. Saving it at its own
    -- path first failed with E13 when that path had just been made a folder:
    -- a note named "Idea", no .md, becoming 1-Projects/Idea/Idea.md.
    local ok, err = pcall(vim.cmd, 'silent write ' .. vim.fn.fnameescape(target))
    if not ok then
      return vim.notify('Could not save the note: ' .. tostring(err), vim.log.levels.ERROR)
    end
    vim.bo[old].modified = false
  end

  vim.cmd('edit ' .. vim.fn.fnameescape(target))
  if vim.api.nvim_buf_is_valid(old) and vim.api.nvim_get_current_buf() ~= old then
    vim.api.nvim_buf_delete(old, { force = true })
  end
  vim.notify((stays and 'Saved as ' or 'Moved to ') .. target:sub(#root + 2))
end

--- Where the note for a period already is, if anywhere.
---
--- The period's folder is checked first, then the rest of the vault: a note
--- made by hand in the inbox with the date as its name is that same day, and
--- creating the canonical one beside it would leave two. The trash, the
--- templates and hidden folders (.obsidian, .trash) do not count.
--- @param root string
--- @param period table
--- @param name string  file name, e.g. "2026-09-25.md"
--- @return string|nil
local function findPeriodic(root, period, name)
  local canonical = root .. '/' .. period.folder .. '/' .. name
  if vim.uv.fs_stat(canonical) then
    return canonical
  end

  local skip = { root .. '/' .. destinations.Delete, templatesPath() }
  local found = vim.fs.find(function(file, dir)
    if file:lower() ~= name:lower() then return false end
    -- Relative to the vault, so a vault that itself sits under a dot folder
    -- is not skipped whole.
    if ('/' .. dir:sub(#root + 2)):find('/%.') then return false end
    for _, folder in ipairs(skip) do
      if isInside(dir, folder) then return false end
    end
    return true
  end, { path = root, type = 'file', limit = 1 })
  return found[1]
end

--- The note for a period, as lines, rendered from `template`; nil after
--- saying why when the template cannot be read.
--- @param template string  template file name, e.g. "Daily.md"
--- @param period table     entry from `periodic`
--- @param when integer     the period's anchor (anchorOf)
--- @return string[]|nil
local function periodicLines(template, period, when)
  local file = io.open(templatesPath() .. '/' .. template, 'r')
  if not file then
    vim.notify('Could not read ' .. template, vim.log.levels.ERROR)
    return nil
  end
  local content = file:read('*a')
  file:close()
  return vim.split(render(content, {
    title = os.date(period.name, when),
    when = when,
    periodic = period,
  }), '\n')
end

--- Open the note for a period, creating it from `template` when missing.
---
--- Unlike the other templates this does not touch the current buffer: the note
--- is a file whose name comes from the date, so it is written straight to disk
--- and opened. A note that already exists, in its folder or anywhere else in
--- the vault, is opened and never gets a second copy. It is filled from the
--- template only while it is blank: Obsidian's daily-note button makes an
--- empty one when it has no template set.
--- @param template string  template file name, e.g. "Daily.md"
--- @param period table     entry from `periodic`
--- @param when integer     timestamp of the period to open
local function openPeriodic(template, period, when)
  local root = vaultPath()
  if not root then return end
  when = anchorOf(period, when)

  local dir = root .. '/' .. period.folder
  local name = os.date(period.name, when) .. '.md'

  local existing = findPeriodic(root, period, name)
  if not existing then vim.fn.mkdir(dir, 'p') end
  vim.cmd('edit ' .. vim.fn.fnameescape(existing or (dir .. '/' .. name)))
  if existing and not isInside(existing, dir) then
    vim.notify(('%s already exists at %s, opened that one instead of making another')
      :format(name, existing:sub(#root + 2)), vim.log.levels.WARN)
  end

  -- Only a blank note gets the template. Text in it, written or not (a write
  -- that failed, the note typed after :e), is left as it is.
  local current = vim.api.nvim_buf_get_lines(0, 0, -1, false)
  if vim.trim(table.concat(current, '\n')) ~= '' then
    if not existing then
      vim.notify(name .. ' is open with unsaved text, left it as it is', vim.log.levels.WARN)
    end
    return
  end

  local lines = periodicLines(template, period, when)
  if not lines then return end
  vim.api.nvim_buf_set_lines(0, 0, -1, false, lines)
  vim.cmd('silent write')
  vim.notify((existing and 'Filled ' or 'Created ') .. period.folder .. '/' .. name)
end

--- Make today's daily note on disk, without opening it: created from the
--- template when it is not in the vault, filled when it is there but blank,
--- the same rules as opening it. Run once per start with a UI when
--- vim.g.pure_daily_on_start is set, so the note is there from the start
--- (for Obsidian, for Claude actions that write in it) and not only once it
--- is opened.
function M.createDaily()
  local root = vaultPath()
  if not root or vim.fn.isdirectory(root) == 0 then return end
  local period = periodic.Daily
  local when = anchorOf(period, os.time())
  local name = os.date(period.name, when) .. '.md'

  local path = findPeriodic(root, period, name)
  if path then
    -- Left alone if it has any text, or is open here (it would be written
    -- under the buffer).
    local ok, current = pcall(vim.fn.readfile, path)
    if not ok or vim.trim(table.concat(current, '\n')) ~= '' or vim.fn.bufloaded(path) == 1 then
      return
    end
  else
    path = root .. '/' .. period.folder .. '/' .. name
    vim.fn.mkdir(vim.fs.dirname(path), 'p')
  end

  local lines = periodicLines('Daily.md', period, when)
  if not lines then return end
  -- The line endings a :write of a new file would use (the first of
  -- 'fileformats'), like the notes opened and written from Neovim.
  if vim.o.fileformats:match('^[^,]*') == 'dos' then
    lines = vim.tbl_map(function(line) return line .. '\r' end, lines)
  end
  if vim.fn.writefile(lines, path) == 0 then
    vim.notify('Created ' .. path:sub(#root + 2))
  end
end

--- Open today's daily note, or another day with an offset in days.
--- @param offset integer|nil
function M.openDaily(offset)
  -- Today keeps the current time, for {{time}}; other days step from noon.
  local when = (offset and offset ~= 0) and (noon(os.time()) + offset * 86400) or os.time()
  openPeriodic('Daily.md', periodic.Daily, when)
end

--- The templates of the vault ("Name.md"), or nil after saying why there are
--- none. `notes_only` leaves out the periodic ones (Daily, Weekly, Monthly):
--- they name a note of their own and cannot become some other note.
--- @param notes_only boolean|nil
--- @return string[]|nil
local function templateNames(notes_only)
  local dir = templatesPath()
  if not dir then
    vim.notify('No Obsidian vault configured yet', vim.log.levels.WARN)
    M.setVault()
    return nil
  end
  if vim.fn.isdirectory(dir) == 0 then
    vim.notify('Templates folder not found: ' .. dir
      .. '\nRun :ZettelVault to point at another vault.', vim.log.levels.ERROR)
    return nil
  end

  local files = vim.tbl_filter(function(name)
    return name:match('%.md$') ~= nil and not (notes_only and periodic[(name:gsub('%.md$', ''))])
  end, vim.fn.readdir(dir))

  if #files == 0 then
    vim.notify('No templates in ' .. dir, vim.log.levels.WARN)
    return nil
  end
  return files
end

--- Folder new notes go to (<leader>vn / <leader>nv), relative to the vault.
--- Added so a new note asks for its name only: every new note starts in the
--- inbox and a template (<leader>vt) moves it to its place later.
local function inboxFolder()
  local folder = vim.g.pure_inbox
  if folder == nil or folder == '' then folder = '0-Inbox' end
  return (tostring(folder):gsub('^[/\\]+', ''):gsub('[/\\]+$', ''))
end

--- Whether `path` is a note whose place is not decided yet: in the inbox
--- (or below it) or directly in the vault's root.
--- @param root string
--- @param path string
--- @return boolean
local function undecided(root, path)
  root, path = vim.fs.normalize(root), vim.fs.normalize(path)
  return isInside(path, root .. '/' .. inboxFolder()) or pathKey(vim.fs.dirname(path)) == pathKey(root)
end

--- `folder` with its "{{choose:A|B}}" asked for; `callback(folder)`, or
--- `callback(nil)` when the pick is cancelled.
--- @param folder string
--- @param callback fun(folder: string|nil)
local function chooseIn(folder, callback)
  local options = folder:match('{{choose:([^}]*)}}')
  if not options then return callback(folder) end
  vim.ui.select(vim.split(options, '|', { plain = true }), { prompt = 'Where' }, function(pick)
    if not pick then return callback(nil) end
    callback((folder:gsub('{{choose:[^}]*}}', function() return pick end, 1)))
  end)
end

--- Expand the template `selected` ("Project.md") into the current note and
--- move the note if the template has a destination. A periodic template opens
--- its own note instead. <leader>nt and a note made from a [[link]] with a
--- template (pure/notes.lua) both come through here.
--- @param selected string
function M.applyTemplate(selected)
  local dir = templatesPath()
  local name = selected:gsub('%.md$', '')

  -- A periodic template addresses a note of its own, so it opens that note
  -- rather than expanding into whatever buffer happens to be focused.
  local period = periodic[name]
  if period then
    return openPeriodic(selected, period, os.time())
  end

  local file = io.open(dir .. '/' .. selected, 'r')
  if not file then
    return vim.notify('Could not read ' .. selected, vim.log.levels.ERROR)
  end
  local content = file:read('*a')
  file:close()

  -- The title is asked for first, so {{title}} in the template, the folder
  -- and the file name all agree.
  withTitle(function(title)
    local lines = vim.split(render(content, { title = title }), '\n')
    -- An empty note becomes the template; otherwise it goes in above the
    -- cursor line. (Inserting into an empty note left a stray blank line.)
    if vim.api.nvim_buf_line_count(0) == 1 and vim.api.nvim_get_current_line() == '' then
      vim.api.nvim_buf_set_lines(0, 0, -1, false, lines)
    else
      local row = vim.api.nvim_win_get_cursor(0)[1]
      vim.api.nvim_buf_set_lines(0, row - 1, row - 1, false, lines)
    end

    local folder = destinations[name]
    if not folder then return end
    -- Only a note still in the inbox (or loose in the vault's root) is
    -- moved: anywhere else she already chose its place, so the template
    -- just fills it and it stays, named after the title. Agreed with her in
    -- Improvment.md (2026-10-06). Delete is the exception: it is the trash.
    local root, path = vaultPath(), vim.api.nvim_buf_get_name(0)
    if root and path ~= '' and name ~= 'Delete' and not undecided(root, path) then
      local here = vim.fs.dirname(vim.fs.normalize(path)):sub(#vim.fs.normalize(root) + 2)
      return moveCurrentFile(here, title)
    end
    chooseIn(folder, function(chosen)
      if chosen then moveCurrentFile(chosen, title) end
    end)
  end)
end

--- Pick a template, expand it at the cursor, and move the note if the template
--- has a destination. Periodic templates open their own note instead.
function M.insertTemplate()
  local files = templateNames(false)
  if not files then return end
  vim.ui.select(files, { prompt = 'Template' }, function(selected)
    if selected then M.applyTemplate(selected) end
  end)
end

--- Pick a template for a note about to be made; `callback(selected)`, with nil
--- when there is none or the pick is cancelled.
--- @param callback fun(selected: string|nil)
function M.pickTemplate(callback)
  local files = templateNames(true)
  if not files then return callback(nil) end
  vim.ui.select(files, { prompt = 'Template' }, callback)
end

--- A new note in the vault's inbox: asks for its name only, never the path.
--- An existing note of that name is opened instead of overwritten.
function M.newNote()
  local root = vaultPath()
  if not root then
    vim.notify('No Obsidian vault set: run :ZettelVault', vim.log.levels.WARN)
    return M.setVault()
  end
  vim.ui.input({ prompt = 'New note: ' }, function(input)
    if input == nil then return end -- cancelled
    -- A typed ".md" is dropped first, so "idea.md" does not become "idea.md.md".
    local name = safeName((input:gsub('%.md$', '')))
    local dir = root .. '/' .. inboxFolder()
    vim.fn.mkdir(dir, 'p')
    -- No name: the same fallback the templates recognise as "not a title yet",
    -- so <leader>vt asks for one later (see isGeneratedName).
    if name == '' then name = M.noteId('Untitled', dir) end
    vim.cmd('edit ' .. vim.fn.fnameescape(dir .. '/' .. name .. '.md'))
  end)
end

--- A new note of a known kind (<leader>vN): the template first, then the
--- title, and the note is born where the template puts it (a template with
--- no destination, Fleeting, leaves it in the inbox). The second way in,
--- next to <leader>vn's capture that asks nothing but a name: for when she
--- already knows what she is writing (Improvment.md, 2026-10-06).
---
--- Made in the inbox and then applyTemplate, so it is the same path as
--- <leader>vt on a captured note: same title, same move, same {{choose}}.
function M.newNoteFromTemplate()
  local root = vaultPath()
  if not root then
    vim.notify('No Obsidian vault set: run :ZettelVault', vim.log.levels.WARN)
    return M.setVault()
  end
  local files = templateNames(true)
  if not files then return end
  -- Delete is the trash gesture, not a kind of note.
  files = vim.tbl_filter(function(f) return f ~= 'Delete.md' end, files)
  vim.ui.select(files, { prompt = 'New note from template' }, function(selected)
    if not selected then return end
    vim.ui.input({ prompt = 'Title: ' }, function(input)
      if input == nil then return end -- cancelled
      local dir = root .. '/' .. inboxFolder()
      vim.fn.mkdir(dir, 'p')
      -- An empty title gets the generated name, and applyTemplate asks again.
      local title = safeName((input:gsub('%.md$', '')))
      local name = M.noteId(title ~= '' and title or 'Untitled', dir)
      vim.cmd('edit ' .. vim.fn.fnameescape(dir .. '/' .. name .. '.md'))
      M.applyTemplate(selected)
    end)
  end)
end

--- Move the current note to the vault's trash (the Delete template's folder,
--- emptied by cleanTrash), then show the previous buffer. Added as a key of
--- its own (<leader>vd): the Delete template did the same but first asked for
--- a template and inserted its text into a note about to be thrown away.
function M.trashNote()
  local root = vaultPath()
  local path = vim.api.nvim_buf_get_name(0)
  if not root or path == '' or vim.bo.buftype ~= '' then
    return vim.notify('Not a note of the vault', vim.log.levels.WARN)
  end
  path = vim.fs.normalize(path)
  local trash = root .. '/' .. destinations.Delete
  if not isInside(path, root) then
    return vim.notify('Not a note of the vault: ' .. path, vim.log.levels.WARN)
  end
  if isInside(path, trash) then
    return vim.notify('Already in the trash', vim.log.levels.INFO)
  end
  local name = vim.fs.basename(path)
  if vim.fn.confirm('Move "' .. name .. '" to the trash?', '&Yes\n&No', 2) ~= 1 then return end

  local old = vim.api.nvim_get_current_buf()
  local stat = vim.uv.fs_stat(path)
  if stat and stat.type == 'file' then
    -- Unsaved changes go to the trash with the note, not lost with the buffer.
    if vim.bo[old].modified then vim.cmd('silent write') end
    vim.fn.mkdir(trash, 'p')
    -- Never over a note already in the trash: "Idea 2.md", as noteId names them.
    local stem = name:gsub('%.md$', '')
    local target = trash .. '/' .. M.noteId(stem, trash) .. '.md'
    local ok, err = os.rename(path, target)
    if not ok then
      return vim.notify('Could not move the note: ' .. tostring(err), vim.log.levels.ERROR)
    end
  end

  -- The window shows the previous buffer rather than closing with the note.
  local alt = vim.fn.bufnr('#')
  if alt > 0 and alt ~= old and vim.fn.buflisted(alt) == 1 then
    vim.cmd('buffer ' .. alt)
  else
    vim.cmd('enew')
  end
  if vim.api.nvim_buf_is_valid(old) then
    vim.api.nvim_buf_delete(old, { force = true })
  end
  vim.notify('Moved to the trash: ' .. name)
end

--- Empty the vault's trash, the folder the Delete template sends notes to, as
--- the TrashCleaner script did when Obsidian started.
---
--- vim.g.pure_trash_cleanup: true empties it; a number N removes only what has
--- not been modified for N days; false or unset leaves it alone. What goes is
--- deleted for good, not moved to the system's recycle bin.
---
--- Nothing open in this Neovim is removed, and nothing outside the trash is
--- ever touched: the folder has to be strictly inside the vault.
function M.cleanTrash()
  local setting = vim.g.pure_trash_cleanup
  if not setting then return end

  local root, folder = vaultPath(), destinations.Delete
  if not root or type(folder) ~= 'string' or vim.fn.isabsolutepath(folder) == 1 then
    return
  end
  -- Relative, with no '.' or '..' step: 'x/..' or '.' would otherwise name
  -- the vault itself, and the checks below would let it through.
  local steps = 0
  for step in folder:gmatch('[^/\\]+') do
    if step == '.' or step == '..' then return end
    steps = steps + 1
  end
  if steps == 0 then return end
  local trash = root .. '/' .. folder
  if pathKey(trash) == pathKey(root) or not isInside(trash, root)
      or vim.fn.isdirectory(trash) == 0 then
    return
  end

  local max_age = type(setting) == 'number' and setting * 86400 or nil
  local open = {}
  for _, buf in ipairs(vim.api.nvim_list_bufs()) do
    local name = vim.api.nvim_buf_get_name(buf)
    if name ~= '' then open[#open + 1] = name end
  end

  local removed = 0
  for name, kind in vim.fs.dir(trash) do
    local path = trash .. '/' .. name
    local stat = vim.uv.fs_stat(path)
    local old_enough = not max_age or (stat ~= nil and os.time() - stat.mtime.sec >= max_age)
    local in_use = false
    for _, buf in ipairs(open) do
      if isInside(buf, path) then in_use = true break end
    end
    if old_enough and not in_use
        and vim.fn.delete(path, kind == 'directory' and 'rf' or '') == 0 then
      removed = removed + 1
    end
  end
  if removed > 0 then
    vim.notify(('Trash: deleted %d item%s from %s'):format(removed, removed == 1 and '' or 's', folder))
  end
end

-- Also used by pure/notes.lua and configs/keymaps.lua, so the vault is
-- configured in one place.
M.vaultPath = vaultPath
M.templatesPath = templatesPath

-- Offer to set the vault on the first start with a UI (maybeAskVault itself
-- returns at once when one is set, declined, or there is no UI).
vim.api.nvim_create_autocmd('VimEnter', {
  group = vim.api.nvim_create_augroup('PureZettelVault', { clear = true }),
  once = true,
  callback = M.maybeAskVault,
})

-- Empty the trash once per start, when a UI attaches. --headless runs, such as
-- scripts and tests, never have one, so they never delete anything.
vim.api.nvim_create_autocmd('UIEnter', {
  group = vim.api.nvim_create_augroup('PureTrashCleanup', { clear = true }),
  once = true,
  callback = function() vim.schedule(M.cleanTrash) end,
})

-- Today's daily note, once per start with a UI (vim.g.pure_daily_on_start).
-- --headless runs never make one, like the trash above.
vim.api.nvim_create_autocmd('UIEnter', {
  group = vim.api.nvim_create_augroup('PureDailyOnStart', { clear = true }),
  once = true,
  callback = function()
    if vim.g.pure_daily_on_start then vim.schedule(M.createDaily) end
  end,
})

-- Exposed for tests.
M._render = render
M._formatMoment = formatMoment
M._shifted = shifted
M._bounds = bounds
M._anchorOf = anchorOf
M._periodic = periodic
M._destinations = destinations

return M

end

